enum nova64_button {
   NOVA64_BTN_LEFT = 0,
   NOVA64_BTN_RIGHT,
   NOVA64_BTN_UP,
   NOVA64_BTN_DOWN,
   NOVA64_BTN_Z,
   NOVA64_BTN_X,
   NOVA64_BTN_C,
   NOVA64_BTN_V,
   NOVA64_BUTTON_COUNT
};

enum nova64_mesh_type {
   NOVA64_MESH_NONE = 0,
   NOVA64_MESH_CUBE,
   NOVA64_MESH_SPHERE,
   NOVA64_MESH_PLANE,
   NOVA64_MESH_CAPSULE,
   NOVA64_MESH_CYLINDER,
   NOVA64_MESH_CUSTOM,
   NOVA64_MESH_INSTANCED,
   NOVA64_MESH_TORUS,
   NOVA64_MESH_CONE
};

/* Mesh-level blend mode for 3D meshes */
enum nova64_mesh_blend {
   NOVA64_MESH_BLEND_OPAQUE = 0,
   NOVA64_MESH_BLEND_ADDITIVE,
   NOVA64_MESH_BLEND_MULTIPLY
};

struct nova64_mesh {
   bool used;
   bool visible;
   bool flat_shading;
   bool cast_shadow;
   bool receive_shadow;
   enum nova64_mesh_type type;
   float position[3];
   float rotation[3];
   float scale[3];
   float opacity;
   bool transparent;
   uint32_t color;
   int texture_handle;      /* 0 = no texture */
   int normal_map_handle;   /* 0 = no normal map */
   uint32_t emissive_color; /* 0 = none, else RGBA8 */
   float emissive_intensity; /* 0 = off */
   float roughness;         /* 0 = smooth, 1 = rough */
   float metalness;         /* 0 = non-metal, 1 = metal */
   float shade_contrast;    /* 1 = neutral, >1 deepens normal lighting */
   float uv_offset[2];      /* UV scroll offset (u, v) */
   float uv_scale[2];       /* UV tiling scale (u, v) */
   bool face_uvs;           /* true: per-face UV from normal (correct box mapping); false: legacy XZ planar */
   float alpha_test;        /* >0: fragment discards when texel.a < alpha_test (Doom sprite cutout) */
   enum nova64_mesh_blend mesh_blend;
   int parent_handle;       /* 0 = no parent (8A scene hierarchy) */
   /* Custom mesh geometry (NOVA64_MESH_CUSTOM) */
   float *custom_verts;       /* interleaved pos[3]+normal[3] per vertex, malloced */
   unsigned custom_vert_count;
   uint16_t *custom_indices;  /* triangle indices, malloced */
   unsigned custom_index_count;
   unsigned gl_custom_vbo;    /* GPU buffer handles, 0 = not uploaded */
   unsigned gl_custom_ibo;
   enum nova64_mesh_type gl_generated_type;
   float gl_generated_scale[3];
   /* Instanced mesh (NOVA64_MESH_INSTANCED) */
   int instance_count;           /* number of instances */
   int instance_geometry;        /* 0=cube 1=sphere 2=plane 3=capsule 4=cylinder 5=cone */
   float *instance_transforms;   /* instance_count * 16 floats (column-major mat4 per instance) */
   uint32_t *instance_colors;    /* per-instance color override (NULL = use mesh color) */
   bool *instance_visible;       /* per-instance visibility */
   /* Extended properties (Batch 51) */
   bool wireframe;
   bool double_sided;
   int  layer;
   int  mesh_group;
   int  sort_order;
   /* Batch 61: tagging / per-mesh user data */
   char tag[32];
   char mesh_name[32];
   int  user_int;
   float user_float;
   /* Torus-specific (majorR=scale[0], minorR=scale[1]) */
   /* Cone-specific (radius=scale[0], height=scale[1]) */
};

struct nova64_camera {
   float position[3];
   float target[3];
   float fov;
   bool is_ortho;
   float ortho_width;
   float ortho_height;
};

struct nova64_light {
   uint32_t ambient;
   float ambient_intensity;
   uint32_t color;
   float intensity;
   float direction[3];
   bool fog_enabled;
   uint32_t fog_color;
   float fog_near;
   float fog_far;
};

struct nova64_point_light {
   bool used;
   uint32_t color;
   float intensity;
   float distance;
   float position[3];
};

/* WAD demos can easily exceed 64 unique textures: E1M1 alone produces
 * 60+ wall composites plus per-enemy sprite atlases plus floor flats.
 * 512 covers the largest FreeDoom maps without growing the static
 * footprint much (~32 KB at sizeof(nova64_texture) ~64). */
#define NOVA64_MAX_TEXTURES 512
struct nova64_texture {
   bool used;
   bool borrowed; /* if true, gl_name is owned by a render target — don't delete */
   GLuint gl_name; /* 0 = not uploaded / software mode */
   int width;
   int height;
};

#define NOVA64_MAX_RENDER_TARGETS 8
struct nova64_render_target {
   bool used;
   int width, height;
   GLuint fbo;
   GLuint color_tex;
   GLuint depth_rbo;
   int texture_handle; /* borrowed nova64_texture handle; 0 = not yet created */
};

enum nova64_renderer_backend {
   NOVA64_RENDERER_GLES3 = 0,
   NOVA64_RENDERER_VULKAN12
};

enum nova64_audio_wave {
   NOVA64_AUDIO_SQUARE = 0,
   NOVA64_AUDIO_SINE,
   NOVA64_AUDIO_SAWTOOTH,
   NOVA64_AUDIO_TRIANGLE,
   NOVA64_AUDIO_NOISE,
   NOVA64_AUDIO_PCM
};

struct nova64_audio_voice {
   bool active;
   enum nova64_audio_wave wave;
   double phase;
   double freq;
   double dur;
   double vol;
   double sweep;
   size_t elapsed_samples;
   size_t total_samples;
   uint32_t noise_state;
   /* PCM playback fields (wave == NOVA64_AUDIO_PCM) */
   const int16_t *pcm_data;
   const struct nova64_package_asset *pcm_asset; /* source asset for stop-by-path */
   size_t pcm_frames;   /* total sample frames */
   size_t pcm_channels; /* 1 or 2 */
   double pcm_rate;     /* source sample rate */
   double pcm_pos;      /* fractional playback position */
   bool pcm_loop;
   int16_t *ogg_decoded_data; /* owned malloc'd PCM from OGG decode, NULL otherwise */
   char channel[32];          /* named channel for volume grouping (8C) */
   float pan;                 /* stereo pan: -1 left, 0 center, +1 right (8C batch4) */
   float pitch;               /* playback pitch multiplier: 1.0 = normal, 2.0 = octave up */
};

struct nova64_sfx_params {
   enum nova64_audio_wave wave;
   double freq;
   double dur;
   double vol;
   double sweep;
};

struct nova64_package_asset {
   bool used;
   char path[256];
   uint8_t *data;
   size_t size;
};

struct nova64_perf_timer {
   bool used;
   bool active;
   char label[64];
   double total;
   uint32_t count;
   clock_t started_at;
};

struct nova64_save_header {
   uint32_t magic;
   uint32_t version;
   uint32_t width;
   uint32_t height;
   uint64_t frame_count;
   uint32_t framebuffer_bytes;
   uint32_t mesh_bytes;
   uint8_t buttons[NOVA64_BUTTON_COUNT];
   uint8_t previous_buttons[NOVA64_BUTTON_COUNT];
};

