static int alloc_trail(void) {
   for (int i = 0; i < NOVA64_MAX_TRAILS; i++)
      if (!g_trails[i].used) { g_trails[i].used = true; return i + 1; }
   return 0;
}

static struct nova64_trail2d *trail_from_handle(int h) {
   if (h < 1 || h > NOVA64_MAX_TRAILS) return NULL;
   return g_trails[h-1].used ? &g_trails[h-1] : NULL;
}

static JSValue js_create_trail2d(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   int h = alloc_trail(); if (!h) return JS_NewInt32(ctx, 0);
   struct nova64_trail2d *tr = &g_trails[h-1];
   int max = argc > 0 ? int_from_js(ctx, argv[0], 16) : 16;
   if (max < 2)  max = 2;
   if (max > NOVA64_MAX_TRAIL_PTS) max = NOVA64_MAX_TRAIL_PTS;
   tr->max_pts   = max;
   tr->head      = 0; tr->count = 0;
   tr->color_head = 0xffffffff;
   tr->color_tail = 0xffffff00; /* white fading to transparent */
   tr->width_head = 3.0f;
   tr->width_tail = 1.0f;
   return JS_NewInt32(ctx, h);
}

static JSValue js_add_trail2d_point(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   struct nova64_trail2d *tr = trail_from_handle(int_from_js(ctx, argc>0?argv[0]:JS_UNDEFINED, 0));
   if (!tr) return JS_UNDEFINED;
   float x = (float)double_from_js(ctx, argc>1?argv[1]:JS_UNDEFINED, 0);
   float y = (float)double_from_js(ctx, argc>2?argv[2]:JS_UNDEFINED, 0);
   /* Push to front: shift indices in ring buffer */
   tr->head = (tr->head + 1) % tr->max_pts;
   tr->pts[tr->head][0] = x;
   tr->pts[tr->head][1] = y;
   if (tr->count < tr->max_pts) tr->count++;
   return JS_UNDEFINED;
}

static JSValue js_set_trail2d_colors(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   struct nova64_trail2d *tr = trail_from_handle(int_from_js(ctx, argc>0?argv[0]:JS_UNDEFINED, 0));
   if (!tr) return JS_UNDEFINED;
   tr->color_head = (uint32_t)int_from_js(ctx, argc>1?argv[1]:JS_UNDEFINED, (int)0xffffffff);
   tr->color_tail = (uint32_t)int_from_js(ctx, argc>2?argv[2]:JS_UNDEFINED, (int)0xffffff00);
   return JS_UNDEFINED;
}

static JSValue js_set_trail2d_width(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   struct nova64_trail2d *tr = trail_from_handle(int_from_js(ctx, argc>0?argv[0]:JS_UNDEFINED, 0));
   if (!tr) return JS_UNDEFINED;
   tr->width_head = (float)double_from_js(ctx, argc>1?argv[1]:JS_UNDEFINED, 3.0);
   tr->width_tail = (float)double_from_js(ctx, argc>2?argv[2]:JS_UNDEFINED, 1.0);
   return JS_UNDEFINED;
}

/* Blend two RGBA8 packed colors by factor t (0=a, 1=b). */
static uint32_t blend_rgba8(uint32_t a, uint32_t b, float t) {
   if (t <= 0) return a; if (t >= 1) return b;
   uint8_t ar=(a>>24)&0xff, ag=(a>>16)&0xff, ab=(a>>8)&0xff, aa=a&0xff;
   uint8_t br=(b>>24)&0xff, bg=(b>>16)&0xff, bb=(b>>8)&0xff, ba=b&0xff;
   uint8_t r=(uint8_t)(ar+(int)((br-ar)*t));
   uint8_t g=(uint8_t)(ag+(int)((bg-ag)*t));
   uint8_t bl2=(uint8_t)(ab+(int)((bb-ab)*t));
   uint8_t al=(uint8_t)(aa+(int)((ba-aa)*t));
   return ((uint32_t)r<<24)|((uint32_t)g<<16)|((uint32_t)bl2<<8)|al;
}

static JSValue js_draw_trail2d(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   struct nova64_trail2d *tr = trail_from_handle(int_from_js(ctx, argc>0?argv[0]:JS_UNDEFINED, 0));
   if (!tr || tr->count < 2) return JS_UNDEFINED;
   /* Draw from newest (head) to oldest; each segment fades toward tail color */
   for (int i = 0; i < tr->count - 1; i++) {
      int idx0 = ((tr->head - i) % tr->max_pts + tr->max_pts) % tr->max_pts;
      int idx1 = ((tr->head - i - 1) % tr->max_pts + tr->max_pts) % tr->max_pts;
      float t = (tr->count > 1) ? (float)i / (float)(tr->count - 1) : 0;
      uint32_t col = blend_rgba8(tr->color_head, tr->color_tail, t);
      int x0 = (int)tr->pts[idx0][0], y0 = (int)tr->pts[idx0][1];
      int x1 = (int)tr->pts[idx1][0], y1 = (int)tr->pts[idx1][1];
      draw_line_pixels(x0, y0, x1, y1, col);
   }
   return JS_UNDEFINED;
}

static JSValue js_clear_trail2d(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   struct nova64_trail2d *tr = trail_from_handle(int_from_js(ctx, argc>0?argv[0]:JS_UNDEFINED, 0));
   if (tr) { tr->head = 0; tr->count = 0; }
   return JS_UNDEFINED;
}

static JSValue js_get_trail2d_count(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   struct nova64_trail2d *tr = trail_from_handle(int_from_js(ctx, argc>0?argv[0]:JS_UNDEFINED, 0));
   return JS_NewInt32(ctx, tr ? tr->count : 0);
}

static JSValue js_destroy_trail2d(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   struct nova64_trail2d *tr = trail_from_handle(int_from_js(ctx, argc>0?argv[0]:JS_UNDEFINED, 0));
   if (!tr) return JS_NewBool(ctx, false);
   memset(tr, 0, sizeof(*tr));
   return JS_NewBool(ctx, true);
}

/* ── Batch 70: triggerMeshFlash, updateMeshFlashes, isMeshFlashing,         ── */
/*              cancelMeshFlash                                                   */

static struct nova64_mesh_flash *flash_for_mesh(int mesh_h) {
   for (int i = 0; i < NOVA64_MAX_FLASH; i++)
      if (g_mesh_flashes[i].used && g_mesh_flashes[i].mesh_handle == mesh_h)
         return &g_mesh_flashes[i];
   return NULL;
}

static struct nova64_mesh_flash *alloc_flash(void) {
   for (int i = 0; i < NOVA64_MAX_FLASH; i++)
      if (!g_mesh_flashes[i].used) { g_mesh_flashes[i].used = true; return &g_mesh_flashes[i]; }
   return NULL;
}

static JSValue js_trigger_mesh_flash(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   int mesh_h = int_from_js(ctx, argc>0?argv[0]:JS_UNDEFINED, 0);
   struct nova64_mesh *mesh = mesh_from_handle(mesh_h);
   if (!mesh) return JS_UNDEFINED;
   uint32_t fcolor  = (uint32_t)int_from_js(ctx, argc>1?argv[1]:JS_UNDEFINED, (int)0xffffffff);
   float    dur     = (float)double_from_js(ctx, argc>2?argv[2]:JS_UNDEFINED, 0.15);
   if (dur < 0.001f) dur = 0.001f;
   /* Reuse existing flash slot for this mesh if any */
   struct nova64_mesh_flash *fl = flash_for_mesh(mesh_h);
   if (!fl) {
      fl = alloc_flash();
      if (!fl) return JS_UNDEFINED;
      fl->mesh_handle = mesh_h;
      fl->saved_color = mesh->color;
   }
   fl->flash_color = fcolor;
   fl->duration    = dur;
   fl->timer       = dur;
   mesh->color     = fcolor;
   return JS_UNDEFINED;
}

static JSValue js_update_mesh_flashes(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   float dt = (float)double_from_js(ctx, argc>0?argv[0]:JS_UNDEFINED, 0);
   for (int i = 0; i < NOVA64_MAX_FLASH; i++) {
      struct nova64_mesh_flash *fl = &g_mesh_flashes[i];
      if (!fl->used) continue;
      fl->timer -= dt;
      if (fl->timer <= 0) {
         struct nova64_mesh *mesh = mesh_from_handle(fl->mesh_handle);
         if (mesh) mesh->color = fl->saved_color;
         memset(fl, 0, sizeof(*fl));
      }
   }
   return JS_UNDEFINED;
}

static JSValue js_is_mesh_flashing(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   int mesh_h = int_from_js(ctx, argc>0?argv[0]:JS_UNDEFINED, 0);
   return JS_NewBool(ctx, flash_for_mesh(mesh_h) != NULL);
}

static JSValue js_cancel_mesh_flash(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   int mesh_h = int_from_js(ctx, argc>0?argv[0]:JS_UNDEFINED, 0);
   struct nova64_mesh_flash *fl = flash_for_mesh(mesh_h);
   if (!fl) return JS_NewBool(ctx, false);
   struct nova64_mesh *mesh = mesh_from_handle(mesh_h);
   if (mesh) mesh->color = fl->saved_color;
   memset(fl, 0, sizeof(*fl));
   return JS_NewBool(ctx, true);
}

/* ── Batch 71: createColorRamp, addColorRampStop, sampleColorRamp,          ── */
/*              colorRampStopCount, destroyColorRamp                             */

static int alloc_ramp(void) {
   for (int i = 0; i < NOVA64_MAX_RAMPS; i++)
      if (!g_color_ramps[i].used) { g_color_ramps[i].used = true; return i + 1; }
   return 0;
}

static struct nova64_color_ramp *ramp_from_handle(int h) {
   if (h < 1 || h > NOVA64_MAX_RAMPS) return NULL;
   return g_color_ramps[h-1].used ? &g_color_ramps[h-1] : NULL;
}

/* Insert stop maintaining sorted order by t; clamps t to [0,1]. */
static void ramp_add_stop(struct nova64_color_ramp *ramp, float t, uint32_t color) {
   if (ramp->count >= NOVA64_MAX_RAMP_STOPS) return;
   if (t < 0) t = 0; if (t > 1) t = 1;
   int pos = ramp->count;
   for (int i = 0; i < ramp->count; i++) {
      if (t <= ramp->stops[i].t) { pos = i; break; }
   }
   /* Shift right */
   for (int i = ramp->count; i > pos; i--)
      ramp->stops[i] = ramp->stops[i-1];
   ramp->stops[pos].t     = t;
   ramp->stops[pos].color = color;
   ramp->count++;
}

static JSValue js_create_color_ramp(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   int h = alloc_ramp(); if (!h) return JS_NewInt32(ctx, 0);
   struct nova64_color_ramp *ramp = &g_color_ramps[h-1];
   /* Argument: flat array of colors → evenly spaced stops */
   if (argc > 0 && JS_IsArray(argv[0])) {
      JSValue lenV = JS_GetPropertyStr(ctx, argv[0], "length");
      int len = int_from_js(ctx, lenV, 0); JS_FreeValue(ctx, lenV);
      if (len >= 2) {
         for (int i = 0; i < len && i < NOVA64_MAX_RAMP_STOPS; i++) {
            JSValue cv = JS_GetPropertyUint32(ctx, argv[0], (uint32_t)i);
            uint32_t col = (uint32_t)int_from_js(ctx, cv, (int)0xffffffff);
            JS_FreeValue(ctx, cv);
            float t = (len > 1) ? (float)i / (float)(len - 1) : 0;
            ramp_add_stop(ramp, t, col);
         }
      }
   }
   /* Default: white→transparent if no stops given */
   if (ramp->count == 0) {
      ramp_add_stop(ramp, 0.0f, 0xffffffff);
      ramp_add_stop(ramp, 1.0f, 0xffffff00);
   }
   return JS_NewInt32(ctx, h);
}

static JSValue js_add_color_ramp_stop(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   struct nova64_color_ramp *ramp = ramp_from_handle(int_from_js(ctx, argc>0?argv[0]:JS_UNDEFINED, 0));
   if (!ramp) return JS_UNDEFINED;
   float    t   = (float)double_from_js(ctx, argc>1?argv[1]:JS_UNDEFINED, 0);
   uint32_t col = (uint32_t)int_from_js(ctx, argc>2?argv[2]:JS_UNDEFINED, (int)0xffffffff);
   ramp_add_stop(ramp, t, col);
   return JS_UNDEFINED;
}

static JSValue js_sample_color_ramp(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   struct nova64_color_ramp *ramp = ramp_from_handle(int_from_js(ctx, argc>0?argv[0]:JS_UNDEFINED, 0));
   if (!ramp || ramp->count == 0) return JS_NewInt32(ctx, (int)0xffffffff);
   float t = (float)clamp_double(double_from_js(ctx, argc>1?argv[1]:JS_UNDEFINED, 0), 0, 1);
   if (ramp->count == 1) return JS_NewInt32(ctx, (int)ramp->stops[0].color);
   /* Find surrounding stops */
   int lo = 0, hi = ramp->count - 1;
   for (int i = 0; i < ramp->count - 1; i++) {
      if (t <= ramp->stops[i+1].t) { lo = i; hi = i + 1; break; }
   }
   float dt = ramp->stops[hi].t - ramp->stops[lo].t;
   float frac = (dt > 1e-6f) ? (t - ramp->stops[lo].t) / dt : 0;
   uint32_t col = blend_rgba8(ramp->stops[lo].color, ramp->stops[hi].color, frac);
   return JS_NewInt32(ctx, (int)col);
}

static JSValue js_color_ramp_stop_count(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   struct nova64_color_ramp *ramp = ramp_from_handle(int_from_js(ctx, argc>0?argv[0]:JS_UNDEFINED, 0));
   return JS_NewInt32(ctx, ramp ? ramp->count : 0);
}

static JSValue js_destroy_color_ramp(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv) {
   (void)this_val;
   struct nova64_color_ramp *ramp = ramp_from_handle(int_from_js(ctx, argc>0?argv[0]:JS_UNDEFINED, 0));
   if (!ramp) return JS_NewBool(ctx, false);
   memset(ramp, 0, sizeof(*ramp));
   return JS_NewBool(ctx, true);
}

/* ── Batch 85: Particle burst ─────────────────────────────────────────────── */

static struct nova64_burst *burst_from_handle(int h)
{
   if (h < 1 || h > NOVA64_MAX_BURSTS) return NULL;
   struct nova64_burst *b = &g_bursts[h - 1];
   return b->used ? b : NULL;
}

static void burst_spawn(struct nova64_burst *b, float ox, float oy, float speed)
{
   for (int i = 0; i < b->count && i < NOVA64_BURST_PARTICLES; i++) {
      float angle = (float)(rng_next_impl() * 6.2831853);
      float sp    = speed * (0.4f + (float)rng_next_impl() * 0.6f);
      b->px[i]    = ox;
      b->py[i]    = oy;
      b->vx[i]    = cosf(angle) * sp;
      b->vy[i]    = sinf(angle) * sp;
      b->max_life[i] = 0.6f + (float)rng_next_impl() * 0.6f;
      b->life[i]  = b->max_life[i];
   }
}

static JSValue js_create_burst(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   float ox    = (float)double_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0.0);
   float oy    = (float)double_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0.0);
   int   count = int_from_js(ctx, argc > 2 ? argv[2] : JS_UNDEFINED, 12);
   float speed = (float)double_from_js(ctx, argc > 3 ? argv[3] : JS_UNDEFINED, 80.0);
   if (count < 1) count = 1;
   if (count > NOVA64_BURST_PARTICLES) count = NOVA64_BURST_PARTICLES;
   for (int i = 0; i < NOVA64_MAX_BURSTS; i++) {
      if (!g_bursts[i].used) {
         memset(&g_bursts[i], 0, sizeof(g_bursts[i]));
         g_bursts[i].used    = true;
         g_bursts[i].count   = count;
         g_bursts[i].gravity = 120.0f;
         g_bursts[i].ncolors = 1;
         g_bursts[i].colors[0] = 0xffffffff;
         burst_spawn(&g_bursts[i], ox, oy, speed);
         return JS_NewInt32(ctx, i + 1);
      }
   }
   return JS_NewInt32(ctx, 0);
}

static JSValue js_trigger_burst(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_burst *b = burst_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!b) return JS_UNDEFINED;
   float ox    = (float)double_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0.0);
   float oy    = (float)double_from_js(ctx, argc > 2 ? argv[2] : JS_UNDEFINED, 0.0);
   float speed = (float)double_from_js(ctx, argc > 3 ? argv[3] : JS_UNDEFINED, 80.0);
   burst_spawn(b, ox, oy, speed);
   return JS_UNDEFINED;
}

static JSValue js_update_burst(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_burst *b = burst_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!b) return JS_UNDEFINED;
   float dt = (float)double_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0.0);
   for (int i = 0; i < b->count; i++) {
      if (b->life[i] <= 0.0f) continue;
      b->vy[i] += b->gravity * dt;
      b->px[i] += b->vx[i] * dt;
      b->py[i] += b->vy[i] * dt;
      b->life[i] -= dt;
   }
   return JS_UNDEFINED;
}

static JSValue js_draw_burst(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_burst *b = burst_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!b) return JS_UNDEFINED;
   for (int i = 0; i < b->count; i++) {
      if (b->life[i] <= 0.0f) continue;
      float frac  = b->life[i] / (b->max_life[i] > 0.0f ? b->max_life[i] : 1.0f);
      int ci      = b->ncolors > 0 ? (i % b->ncolors) : 0;
      uint32_t c  = b->colors[ci];
      uint8_t  a  = (uint8_t)((float)((c) & 0xff) * frac);
      uint32_t fc = (c & 0xffffff00u) | a;
      set_pixel((int)b->px[i], (int)b->py[i], fc);
   }
   return JS_UNDEFINED;
}

static JSValue js_is_burst_done(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_burst *b = burst_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!b) return JS_NewBool(ctx, true);
   for (int i = 0; i < b->count; i++)
      if (b->life[i] > 0.0f) return JS_NewBool(ctx, false);
   return JS_NewBool(ctx, true);
}

static JSValue js_set_burst_colors(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_burst *b = burst_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!b) return JS_UNDEFINED;
   b->ncolors = 0;
   for (int i = 1; i < argc && b->ncolors < 4; i++) {
      uint32_t v = 0;
      JS_ToUint32(ctx, &v, argv[i]);
      b->colors[b->ncolors++] = v;
   }
   return JS_UNDEFINED;
}

static JSValue js_destroy_burst(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_burst *b = burst_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!b) return JS_NewBool(ctx, false);
   b->used = false;
   return JS_NewBool(ctx, true);
}

/* ── Batch 86: Text effects ────────────────────────────────────────────────── */

static void draw_text_gradient(const char *text, int x, int y, uint32_t ctop, uint32_t cbot)
{
   if (!text) return;
   int cursor = x;
   for (const char *p = text; *p; p++) {
      if (*p == '\n') { cursor = x; y += 9; continue; }
      for (int row = 0; row < 7; row++) {
         uint8_t bits = glyph_row(*p, row);
         float t2 = (float)row / 6.0f;
         uint8_t r2 = (uint8_t)((float)((ctop>>24)&0xff)*(1.0f-t2) + (float)((cbot>>24)&0xff)*t2);
         uint8_t g2 = (uint8_t)((float)((ctop>>16)&0xff)*(1.0f-t2) + (float)((cbot>>16)&0xff)*t2);
         uint8_t b2 = (uint8_t)((float)((ctop>>8) &0xff)*(1.0f-t2) + (float)((cbot>>8) &0xff)*t2);
         uint8_t a2 = (uint8_t)((float)((ctop>>0) &0xff)*(1.0f-t2) + (float)((cbot>>0) &0xff)*t2);
         uint32_t col = ((uint32_t)r2<<24)|((uint32_t)g2<<16)|((uint32_t)b2<<8)|a2;
         for (int col2 = 0; col2 < 5; col2++)
            if (bits & (1U << (4 - col2)))
               set_pixel(cursor + col2, y + row, col);
      }
      cursor += 6;
   }
}

static void draw_text_gradient_tight(const char *text, int x, int y, uint32_t ctop, uint32_t cbot)
{
   if (!text) return;
   int cursor = x;
   for (const char *p = text; *p; p++) {
      if (*p == '\n') { cursor = x; y += 9; continue; }
      int minc = 0, maxc = 0;
      if (glyph_tight_bounds(*p, &minc, &maxc)) {
         for (int row = 0; row < 7; row++) {
            uint8_t bits = glyph_row(*p, row);
            float t2 = (float)row / 6.0f;
            uint8_t r2 = (uint8_t)((float)((ctop>>24)&0xff)*(1.0f-t2) + (float)((cbot>>24)&0xff)*t2);
            uint8_t g2 = (uint8_t)((float)((ctop>>16)&0xff)*(1.0f-t2) + (float)((cbot>>16)&0xff)*t2);
            uint8_t b2 = (uint8_t)((float)((ctop>>8) &0xff)*(1.0f-t2) + (float)((cbot>>8) &0xff)*t2);
            uint8_t a2 = (uint8_t)((float)((ctop>>0) &0xff)*(1.0f-t2) + (float)((cbot>>0) &0xff)*t2);
            uint32_t col = ((uint32_t)r2<<24)|((uint32_t)g2<<16)|((uint32_t)b2<<8)|a2;
            for (int col2 = minc; col2 <= maxc; col2++)
               if (bits & (1U << (4 - col2)))
                  set_pixel(cursor + (col2 - minc), y + row, col);
         }
      }
      cursor += glyph_tight_advance(*p);
   }
}

static JSValue js_print_gradient(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int x = int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0);
   int y = int_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0);
   const char *text = JS_ToCString(ctx, argc > 2 ? argv[2] : JS_UNDEFINED);
   uint32_t ctop = 0; JS_ToUint32(ctx, &ctop, argc > 3 ? argv[3] : JS_UNDEFINED);
   uint32_t cbot = 0; JS_ToUint32(ctx, &cbot, argc > 4 ? argv[4] : JS_UNDEFINED);
   draw_text_gradient(text, x, y, ctop, cbot);
   JS_FreeCString(ctx, text);
   return JS_UNDEFINED;
}

static JSValue js_print_wave(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int x    = int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0);
   int y    = int_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0);
   const char *text = JS_ToCString(ctx, argc > 2 ? argv[2] : JS_UNDEFINED);
   uint32_t color = 0; JS_ToUint32(ctx, &color, argc > 3 ? argv[3] : JS_UNDEFINED);
   float amp  = (float)double_from_js(ctx, argc > 4 ? argv[4] : JS_UNDEFINED, 4.0);
   float freq = (float)double_from_js(ctx, argc > 5 ? argv[5] : JS_UNDEFINED, 0.8f);
   float t2   = (float)double_from_js(ctx, argc > 6 ? argv[6] : JS_UNDEFINED, 0.0);
   if (text) {
      int cursor = x;
      int ci = 0;
      for (const char *p = text; *p; p++, ci++) {
         if (*p == '\n') { cursor = x; y += 9; ci = 0; continue; }
         int dy = (int)(amp * sinf(ci * freq + t2));
         for (int row = 0; row < 7; row++) {
            uint8_t bits = glyph_row(*p, row);
            for (int col2 = 0; col2 < 5; col2++)
               if (bits & (1U << (4 - col2)))
                  set_pixel(cursor + col2, y + row + dy, color);
         }
         cursor += 6;
      }
   }
   JS_FreeCString(ctx, text);
   return JS_UNDEFINED;
}

static JSValue js_print_flash(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int x = int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0);
   int y = int_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0);
   const char *text = JS_ToCString(ctx, argc > 2 ? argv[2] : JS_UNDEFINED);
   uint32_t color = 0; JS_ToUint32(ctx, &color, argc > 3 ? argv[3] : JS_UNDEFINED);
   float t2  = (float)double_from_js(ctx, argc > 4 ? argv[4] : JS_UNDEFINED, 0.0);
   float hz  = (float)double_from_js(ctx, argc > 5 ? argv[5] : JS_UNDEFINED, 2.0);
   if (text && ((int)(t2 * hz * 2.0f) & 1) == 0) {
      int cursor = x;
      for (const char *p = text; *p; p++) {
         if (*p == '\n') { cursor = x; y += 9; continue; }
         for (int row = 0; row < 7; row++) {
            uint8_t bits = glyph_row(*p, row);
            for (int col2 = 0; col2 < 5; col2++)
               if (bits & (1U << (4 - col2)))
                  set_pixel(cursor + col2, y + row, color);
         }
         cursor += 6;
      }
   }
   JS_FreeCString(ctx, text);
   return JS_UNDEFINED;
}

static JSValue js_print_shake(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int x = int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0);
   int y = int_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0);
   const char *text = JS_ToCString(ctx, argc > 2 ? argv[2] : JS_UNDEFINED);
   uint32_t color = 0; JS_ToUint32(ctx, &color, argc > 3 ? argv[3] : JS_UNDEFINED);
   float t2     = (float)double_from_js(ctx, argc > 4 ? argv[4] : JS_UNDEFINED, 0.0);
   float amount = (float)double_from_js(ctx, argc > 5 ? argv[5] : JS_UNDEFINED, 2.0);
   if (text) {
      int cursor = x;
      int ci = 0;
      for (const char *p = text; *p; p++, ci++) {
         if (*p == '\n') { cursor = x; y += 9; ci = 0; continue; }
         int ox = (int)(sinf((float)(ci * 7) + t2 * 20.0f) * amount);
         int oy = (int)(cosf((float)(ci * 5) + t2 * 17.0f) * amount);
         for (int row = 0; row < 7; row++) {
            uint8_t bits = glyph_row(*p, row);
            for (int col2 = 0; col2 < 5; col2++)
               if (bits & (1U << (4 - col2)))
                  set_pixel(cursor + col2 + ox, y + row + oy, color);
         }
         cursor += 6;
      }
   }
   JS_FreeCString(ctx, text);
   return JS_UNDEFINED;
}

static uint32_t hsv_to_rgba8(float h, float s, float v, uint8_t a)
{
   h = fmodf(h, 360.0f);
   if (h < 0.0f) h += 360.0f;
   float c = v * s;
   float x = c * (1.0f - fabsf(fmodf(h / 60.0f, 2.0f) - 1.0f));
   float m = v - c;
   float r2, g2, b2;
   if      (h < 60.0f)  { r2=c; g2=x; b2=0; }
   else if (h < 120.0f) { r2=x; g2=c; b2=0; }
   else if (h < 180.0f) { r2=0; g2=c; b2=x; }
   else if (h < 240.0f) { r2=0; g2=x; b2=c; }
   else if (h < 300.0f) { r2=x; g2=0; b2=c; }
   else                 { r2=c; g2=0; b2=x; }
   return ((uint32_t)((r2+m)*255)<<24)|((uint32_t)((g2+m)*255)<<16)|((uint32_t)((b2+m)*255)<<8)|a;
}

static JSValue js_print_rainbow(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int x = int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0);
   int y = int_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0);
   const char *text = JS_ToCString(ctx, argc > 2 ? argv[2] : JS_UNDEFINED);
   float t2 = (float)double_from_js(ctx, argc > 3 ? argv[3] : JS_UNDEFINED, 0.0);
   if (text) {
      int cursor = x;
      int ci = 0;
      for (const char *p = text; *p; p++, ci++) {
         if (*p == '\n') { cursor = x; y += 9; ci = 0; continue; }
         float hue   = fmodf((float)ci * 30.0f + t2 * 100.0f, 360.0f);
         uint32_t col = hsv_to_rgba8(hue, 1.0f, 1.0f, 255);
         for (int row = 0; row < 7; row++) {
            uint8_t bits = glyph_row(*p, row);
            for (int col2 = 0; col2 < 5; col2++)
               if (bits & (1U << (4 - col2)))
                  set_pixel(cursor + col2, y + row, col);
         }
         cursor += 6;
      }
   }
   JS_FreeCString(ctx, text);
   return JS_UNDEFINED;
}

/* ── Tight (variable-width) versions of animated text effects ──────────────
   Identical argument shape to the fixed-width effects, but each glyph
   advances by its content width + 1 px (via glyph_tight_advance) instead of
   the flat 6 px. Carts opt in by calling the *Tight name. Drop-in for HUDs
   where the chunky fixed-width look bothers you. */

static JSValue js_print_wave_tight(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int x = int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0);
   int y = int_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0);
   const char *text = JS_ToCString(ctx, argc > 2 ? argv[2] : JS_UNDEFINED);
   uint32_t color = 0; JS_ToUint32(ctx, &color, argc > 3 ? argv[3] : JS_UNDEFINED);
   float amp  = (float)double_from_js(ctx, argc > 4 ? argv[4] : JS_UNDEFINED, 4.0);
   float freq = (float)double_from_js(ctx, argc > 5 ? argv[5] : JS_UNDEFINED, 0.8f);
   float t2   = (float)double_from_js(ctx, argc > 6 ? argv[6] : JS_UNDEFINED, 0.0);
   if (text) {
      int cursor = x;
      int ci = 0;
      for (const char *p = text; *p; p++, ci++) {
         if (*p == '\n') { cursor = x; y += 9; ci = 0; continue; }
         int dy = (int)(amp * sinf(ci * freq + t2));
         int minc = 0, maxc = 0;
         if (glyph_tight_bounds(*p, &minc, &maxc)) {
            for (int row = 0; row < 7; row++) {
               uint8_t bits = glyph_row(*p, row);
               for (int col2 = minc; col2 <= maxc; col2++)
                  if (bits & (1U << (4 - col2)))
                     set_pixel(cursor + (col2 - minc), y + row + dy, color);
            }
         }
         cursor += glyph_tight_advance(*p);
      }
   }
   if (text) JS_FreeCString(ctx, text);
   return JS_UNDEFINED;
}

static JSValue js_print_flash_tight(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int x = int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0);
   int y = int_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0);
   const char *text = JS_ToCString(ctx, argc > 2 ? argv[2] : JS_UNDEFINED);
   uint32_t color = 0; JS_ToUint32(ctx, &color, argc > 3 ? argv[3] : JS_UNDEFINED);
   float t2  = (float)double_from_js(ctx, argc > 4 ? argv[4] : JS_UNDEFINED, 0.0);
   float hz  = (float)double_from_js(ctx, argc > 5 ? argv[5] : JS_UNDEFINED, 2.0);
   if (text && ((int)(t2 * hz * 2.0f) & 1) == 0) {
      draw_text_tight_pixels(text, x, y, color);
   }
   if (text) JS_FreeCString(ctx, text);
   return JS_UNDEFINED;
}

static JSValue js_print_shake_tight(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int x = int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0);
   int y = int_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0);
   const char *text = JS_ToCString(ctx, argc > 2 ? argv[2] : JS_UNDEFINED);
   uint32_t color = 0; JS_ToUint32(ctx, &color, argc > 3 ? argv[3] : JS_UNDEFINED);
   float t2     = (float)double_from_js(ctx, argc > 4 ? argv[4] : JS_UNDEFINED, 0.0);
   float amount = (float)double_from_js(ctx, argc > 5 ? argv[5] : JS_UNDEFINED, 2.0);
   if (text) {
      int cursor = x;
      int ci = 0;
      for (const char *p = text; *p; p++, ci++) {
         if (*p == '\n') { cursor = x; y += 9; ci = 0; continue; }
         int ox = (int)(sinf((float)(ci * 7) + t2 * 20.0f) * amount);
         int oy = (int)(cosf((float)(ci * 5) + t2 * 17.0f) * amount);
         int minc = 0, maxc = 0;
         if (glyph_tight_bounds(*p, &minc, &maxc)) {
            for (int row = 0; row < 7; row++) {
               uint8_t bits = glyph_row(*p, row);
               for (int col2 = minc; col2 <= maxc; col2++)
                  if (bits & (1U << (4 - col2)))
                     set_pixel(cursor + (col2 - minc) + ox, y + row + oy, color);
            }
         }
         cursor += glyph_tight_advance(*p);
      }
   }
   if (text) JS_FreeCString(ctx, text);
   return JS_UNDEFINED;
}

static JSValue js_print_rainbow_tight(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int x = int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0);
   int y = int_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0);
   const char *text = JS_ToCString(ctx, argc > 2 ? argv[2] : JS_UNDEFINED);
   float t2 = (float)double_from_js(ctx, argc > 3 ? argv[3] : JS_UNDEFINED, 0.0);
   if (text) {
      int cursor = x;
      int ci = 0;
      for (const char *p = text; *p; p++, ci++) {
         if (*p == '\n') { cursor = x; y += 9; ci = 0; continue; }
         float hue   = fmodf((float)ci * 30.0f + t2 * 100.0f, 360.0f);
         uint32_t col = hsv_to_rgba8(hue, 1.0f, 1.0f, 255);
         int minc = 0, maxc = 0;
         if (glyph_tight_bounds(*p, &minc, &maxc)) {
            for (int row = 0; row < 7; row++) {
               uint8_t bits = glyph_row(*p, row);
               for (int col2 = minc; col2 <= maxc; col2++)
                  if (bits & (1U << (4 - col2)))
                     set_pixel(cursor + (col2 - minc), y + row, col);
            }
         }
         cursor += glyph_tight_advance(*p);
      }
   }
   if (text) JS_FreeCString(ctx, text);
   return JS_UNDEFINED;
}

static void draw_text_gradient_tight(const char *text, int x, int y, uint32_t ctop, uint32_t cbot);

static JSValue js_print_gradient_tight(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int x = int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0);
   int y = int_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0);
   const char *text = JS_ToCString(ctx, argc > 2 ? argv[2] : JS_UNDEFINED);
   uint32_t ctop = 0; JS_ToUint32(ctx, &ctop, argc > 3 ? argv[3] : JS_UNDEFINED);
   uint32_t cbot = 0; JS_ToUint32(ctx, &cbot, argc > 4 ? argv[4] : JS_UNDEFINED);
   draw_text_gradient_tight(text, x, y, ctop, cbot);
   if (text) JS_FreeCString(ctx, text);
   return JS_UNDEFINED;
}

/* ── Batch 87: Speech bubble ───────────────────────────────────────────────── */

static struct nova64_bubble *bubble_from_handle(int h)
{
   if (h < 1 || h > NOVA64_MAX_BUBBLES) return NULL;
   struct nova64_bubble *b = &g_bubbles[h - 1];
   return b->used ? b : NULL;
}

static JSValue js_create_speech_bubble(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int x = int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0);
   int y = int_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0);
   int w = int_from_js(ctx, argc > 2 ? argv[2] : JS_UNDEFINED, 120);
   int h = int_from_js(ctx, argc > 3 ? argv[3] : JS_UNDEFINED, 50);
   for (int i = 0; i < NOVA64_MAX_BUBBLES; i++) {
      if (!g_bubbles[i].used) {
         memset(&g_bubbles[i], 0, sizeof(g_bubbles[i]));
         g_bubbles[i].used         = true;
         g_bubbles[i].x            = x;
         g_bubbles[i].y            = y;
         g_bubbles[i].w            = w;
         g_bubbles[i].h            = h;
         g_bubbles[i].tail_x       = x + w / 2;
         g_bubbles[i].tail_y       = y + h;
         g_bubbles[i].tail_side    = 0;
         g_bubbles[i].bg_color     = 0xffffffff;
         g_bubbles[i].border_color = 0x222222ff;
         g_bubbles[i].text_color   = 0x111111ff;
         return JS_NewInt32(ctx, i + 1);
      }
   }
   return JS_NewInt32(ctx, 0);
}

static JSValue js_set_speech_bubble_text(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_bubble *b = bubble_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!b) return JS_UNDEFINED;
   const char *t2 = JS_ToCString(ctx, argc > 1 ? argv[1] : JS_UNDEFINED);
   if (t2) {
      strncpy(b->text, t2, sizeof(b->text) - 1);
      b->text[sizeof(b->text) - 1] = '\0';
      JS_FreeCString(ctx, t2);
   }
   return JS_UNDEFINED;
}

static JSValue js_set_speech_bubble_tail(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_bubble *b = bubble_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!b) return JS_UNDEFINED;
   b->tail_x    = int_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, b->tail_x);
   b->tail_y    = int_from_js(ctx, argc > 2 ? argv[2] : JS_UNDEFINED, b->tail_y);
   b->tail_side = int_from_js(ctx, argc > 3 ? argv[3] : JS_UNDEFINED, b->tail_side);
   return JS_UNDEFINED;
}

static JSValue js_set_speech_bubble_colors(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_bubble *b = bubble_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!b) return JS_UNDEFINED;
   if (argc > 1) JS_ToUint32(ctx, &b->bg_color,     argv[1]);
   if (argc > 2) JS_ToUint32(ctx, &b->border_color, argv[2]);
   if (argc > 3) JS_ToUint32(ctx, &b->text_color,   argv[3]);
   return JS_UNDEFINED;
}

static JSValue js_draw_speech_bub(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_bubble *b = bubble_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!b) return JS_UNDEFINED;
   draw_rect_pixels(b->x, b->y, b->w, b->h, b->bg_color, true);
   draw_rect_pixels(b->x, b->y, b->w, b->h, b->border_color, false);
   /* tail triangle (side 0 = bottom-center, 1 = top-center) */
   int tx = b->tail_x;
   int ty = b->tail_y;
   int ts = 8;
   if (b->tail_side == 0) {
      for (int i = 0; i <= ts; i++) {
         set_pixel(tx - i, ty + i, b->bg_color);
         set_pixel(tx + i, ty + i, b->bg_color);
         set_pixel(tx - i, ty + i, b->border_color);
         set_pixel(tx + i, ty + i, b->border_color);
      }
      set_pixel(tx, ty + ts + 1, b->border_color);
   } else if (b->tail_side == 1) {
      for (int i = 0; i <= ts; i++) {
         set_pixel(tx - i, ty - i, b->bg_color);
         set_pixel(tx + i, ty - i, b->bg_color);
      }
   }
   /* text */
   if (b->text[0])
      draw_text_pixels(b->text, b->x + 5, b->y + 5, b->text_color);
   return JS_UNDEFINED;
}

static JSValue js_destroy_speech_bub(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_bubble *b = bubble_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!b) return JS_NewBool(ctx, false);
   b->used = false;
   return JS_NewBool(ctx, true);
}

/* ── Batch 88: Smooth 2D camera ────────────────────────────────────────────── */

static struct nova64_smooth_cam *smooth_cam_from_handle(int h)
{
   if (h < 1 || h > NOVA64_MAX_SMOOTH_CAMS) return NULL;
   struct nova64_smooth_cam *c = &g_smooth_cams[h - 1];
   return c->used ? c : NULL;
}

static JSValue js_create_cam2d(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   float tx   = (float)double_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0.0);
   float ty   = (float)double_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0.0);
   float lerp = (float)double_from_js(ctx, argc > 2 ? argv[2] : JS_UNDEFINED, 5.0);
   for (int i = 0; i < NOVA64_MAX_SMOOTH_CAMS; i++) {
      if (!g_smooth_cams[i].used) {
         memset(&g_smooth_cams[i], 0, sizeof(g_smooth_cams[i]));
         g_smooth_cams[i].used        = true;
         g_smooth_cams[i].x           = tx;
         g_smooth_cams[i].y           = ty;
         g_smooth_cams[i].tx          = tx;
         g_smooth_cams[i].ty          = ty;
         g_smooth_cams[i].lerp        = lerp;
         g_smooth_cams[i].zoom        = 1.0f;
         g_smooth_cams[i].zoom_target = 1.0f;
         return JS_NewInt32(ctx, i + 1);
      }
   }
   return JS_NewInt32(ctx, 0);
}

static JSValue js_set_cam2d_target(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_smooth_cam *c = smooth_cam_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!c) return JS_UNDEFINED;
   c->tx = (float)double_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, c->tx);
   c->ty = (float)double_from_js(ctx, argc > 2 ? argv[2] : JS_UNDEFINED, c->ty);
   return JS_UNDEFINED;
}

static JSValue js_set_cam2d_zoom(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_smooth_cam *c = smooth_cam_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!c) return JS_UNDEFINED;
   c->zoom_target = (float)double_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 1.0);
   return JS_UNDEFINED;
}

static JSValue js_update_cam2d(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_smooth_cam *c = smooth_cam_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!c) return JS_UNDEFINED;
   float dt = (float)double_from_js(ctx, argc > 1 ? argv[1] : JS_UNDEFINED, 0.0);
   float k  = 1.0f - expf(-c->lerp * dt);
   c->x    += (c->tx - c->x) * k;
   c->y    += (c->ty - c->y) * k;
   c->zoom += (c->zoom_target - c->zoom) * k;
   return JS_UNDEFINED;
}

static JSValue js_apply_cam2d(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_smooth_cam *c = smooth_cam_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!c) return JS_UNDEFINED;
   cam2d_x    = (int)c->x;
   cam2d_y    = (int)c->y;
   cam2d_zoom = c->zoom;
   return JS_UNDEFINED;
}

static JSValue js_get_cam2d_x(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_smooth_cam *c = smooth_cam_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   return JS_NewFloat64(ctx, c ? c->x : 0.0);
}

static JSValue js_get_cam2d_y(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_smooth_cam *c = smooth_cam_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   return JS_NewFloat64(ctx, c ? c->y : 0.0);
}

static JSValue js_destroy_cam2d(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   struct nova64_smooth_cam *c = smooth_cam_from_handle(int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0));
   if (!c) return JS_NewBool(ctx, false);
   c->used = false;
   return JS_NewBool(ctx, true);
}

