/* clampXY(x,y,x0,y0,x1,y1) -> [cx,cy] */
static JSValue js_clamp_xy(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double xv=double_from_js(ctx,argv[0],0), yv=double_from_js(ctx,argv[1],0);
   double x0=double_from_js(ctx,argv[2],0), y0=double_from_js(ctx,argv[3],0);
   double x1=double_from_js(ctx,argv[4],100), y1=double_from_js(ctx,argv[5],100);
   if(xv<x0)xv=x0; if(xv>x1)xv=x1;
   if(yv<y0)yv=y0; if(yv>y1)yv=y1;
   JSValue arr=JS_NewArray(ctx);
   JS_SetPropertyUint32(ctx,arr,0,JS_NewFloat64(ctx,xv));
   JS_SetPropertyUint32(ctx,arr,1,JS_NewFloat64(ctx,yv));
   return arr;
}

/* screenSepia2(amount) */
static JSValue js_screen_sepia2(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double amount=argc>0?double_from_js(ctx,argv[0],1.0):1.0;
   if(amount<0)amount=0; if(amount>1)amount=1;
   int W=640,H=360;
   for(int i=0;i<W*H;i++){
      uint32_t pc=framebuffer[i];
      int rv2=(pc>>24)&0xFF, gv2=(pc>>16)&0xFF, bv2=(pc>>8)&0xFF;
      int sr=(int)(rv2*0.393+gv2*0.769+bv2*0.189);
      int sg=(int)(rv2*0.349+gv2*0.686+bv2*0.168);
      int sb=(int)(rv2*0.272+gv2*0.534+bv2*0.131);
      if(sr>255)sr=255; if(sg>255)sg=255; if(sb>255)sb=255;
      int fr=(int)(rv2+(sr-rv2)*amount);
      int fg=(int)(gv2+(sg-gv2)*amount);
      int fb=(int)(bv2+(sb-bv2)*amount);
      framebuffer[i]=((uint32_t)fr<<24)|((uint32_t)fg<<16)|((uint32_t)fb<<8)|(pc&0xFF);
   }
   return JS_UNDEFINED;
}

/* colorFromHex(hexString) */
static JSValue js_color_from_hex(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if(argc<1||!JS_IsString(argv[0])) return JS_NewInt32(ctx,0);
   const char *str=JS_ToCString(ctx,argv[0]);
   if(!str) return JS_NewInt32(ctx,0);
   const char *ptr=str;
   if(*ptr=='#') ptr++;
   unsigned long val=strtoul(ptr,NULL,16);
   JS_FreeCString(ctx,str);
   uint32_t col;
   size_t len=strlen(ptr);
   if(len<=6){
      /* RRGGBB -> RRGGBBFF */
      col=(uint32_t)((val<<8)|0xFF);
   } else {
      /* RRGGBBAA */
      col=(uint32_t)val;
   }
   return JS_NewInt32(ctx,(int32_t)col);
}

/* easeElastic2(t) — elastic ease-out */
static JSValue js_ease_elastic2(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double tv=double_from_js(ctx,argv[0],0);
   if(tv<=0) return JS_NewFloat64(ctx,0);
   if(tv>=1) return JS_NewFloat64(ctx,1);
   double p=0.3;
   double result=pow(2.0,-10*tv)*sin((tv-p/4)*(2*M_PI)/p)+1.0;
   return JS_NewFloat64(ctx,result);
}

/* ── Batch 26: star2, rosette, fractal tree, screen flip, colorFade ─────── */

/* drawStar2(cx,cy,r,n,ratio,color) — n-pointed star */
static JSValue js_draw_star2(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],40);
   int nv=argc>3?(int)double_from_js(ctx,argv[3],5):5;
   double ratio=argc>4?double_from_js(ctx,argv[4],0.4):0.4;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   if(nv<3)nv=3; if(nv>24)nv=24;
   double inner=rv*ratio;
   for(int i=0;i<nv*2;i++){
      double a1=M_PI*(2*i)/(nv*2)-M_PI/2;
      double a2=M_PI*(2*i+1)/(nv*2)-M_PI/2;
      double a3=M_PI*(2*i+2)/(nv*2)-M_PI/2;
      double r1=(i%2==0)?rv:inner, r2=(i%2==0)?inner:rv;
      (void)r2;
      path_draw_line_segment((int)(cx+cos(a1)*r1),(int)(cy+sin(a1)*r1),
                             (int)(cx+cos(a2)*inner),(int)(cy+sin(a2)*inner),col);
      path_draw_line_segment((int)(cx+cos(a2)*inner),(int)(cy+sin(a2)*inner),
                             (int)(cx+cos(a3)*rv),(int)(cy+sin(a3)*rv),col);
      i++;
   }
   return JS_UNDEFINED;
}

/* fillStar2(cx,cy,r,n,ratio,color) */
static JSValue js_fill_star2(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],40);
   int nv=argc>3?(int)double_from_js(ctx,argv[3],5):5;
   double ratio=argc>4?double_from_js(ctx,argv[4],0.4):0.4;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   if(nv<3)nv=3; if(nv>24)nv=24;
   double inner=rv*ratio;
   int N=nv*2;
   int pts_x[48], pts_y[48];
   for(int i=0;i<N;i++){
      double ang=M_PI*2*i/N - M_PI/2;
      double rr=(i%2==0)?rv:inner;
      pts_x[i]=(int)(cx+cos(ang)*rr);
      pts_y[i]=(int)(cy+sin(ang)*rr);
   }
   int miny=pts_y[0],maxy=pts_y[0];
   for(int i=1;i<N;i++){if(pts_y[i]<miny)miny=pts_y[i];if(pts_y[i]>maxy)maxy=pts_y[i];}
   for(int ys=miny;ys<=maxy;ys++){
      int xs[48]; int nc=0;
      for(int i=0;i<N;i++){
         int j=(i+1)%N, ay=pts_y[i],by=pts_y[j];
         if((ay<=ys&&by>ys)||(by<=ys&&ay>ys))
            xs[nc++]=pts_x[i]+(pts_x[j]-pts_x[i])*(ys-ay)/(by-ay);
      }
      for(int ii=0;ii<nc-1;ii++) for(int jj=ii+1;jj<nc;jj++) if(xs[jj]<xs[ii]){int t=xs[ii];xs[ii]=xs[jj];xs[jj]=t;}
      for(int ii=0;ii+1<nc;ii+=2) for(int xv=xs[ii];xv<=xs[ii+1];xv++) set_pixel(xv,ys,col);
   }
   return JS_UNDEFINED;
}

/* drawRosette(cx,cy,r,k,color) — r*cos(k*theta) rose curve */
static JSValue js_draw_rosette(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],50);
   int kv=argc>3?(int)double_from_js(ctx,argv[3],4):4;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   if(kv<1)kv=1; if(kv>12)kv=12;
   int N=360;
   for(int i=0;i<N;i++){
      double t1=(double)i/N*2*M_PI, t2=(double)(i+1)/N*2*M_PI;
      double r1=rv*cos(kv*t1), r2=rv*cos(kv*t2);
      if(r1<0)r1=0; if(r2<0)r2=0;
      path_draw_line_segment((int)(cx+cos(t1)*r1),(int)(cy+sin(t1)*r1),
                             (int)(cx+cos(t2)*r2),(int)(cy+sin(t2)*r2),col);
   }
   return JS_UNDEFINED;
}

/* fillRosette(cx,cy,r,k,color) */
static JSValue js_fill_rosette(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],50);
   int kv=argc>3?(int)double_from_js(ctx,argv[3],4):4;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   if(kv<1)kv=1; if(kv>12)kv=12;
   int N=720;
   for(int i=0;i<N;i++){
      double t1=(double)i/N*2*M_PI;
      double r1=rv*cos(kv*t1); if(r1<0)r1=-r1;
      path_draw_line_segment((int)cx,(int)cy,(int)(cx+cos(t1)*r1),(int)(cy+sin(t1)*r1),col);
   }
   return JS_UNDEFINED;
}

/* drawFractalTree(x,y,length,angle,depth,color) */
static void fractal_tree_branch(double x1, double y1, double len, double ang, int depth, uint32_t col)
{
   if(depth<=0||len<2) return;
   double x2=x1+cos(ang)*len;
   double y2=y1-sin(ang)*len;
   path_draw_line_segment((int)x1,(int)y1,(int)x2,(int)y2,col);
   fractal_tree_branch(x2,y2,len*0.7,ang+0.4,depth-1,col);
   fractal_tree_branch(x2,y2,len*0.7,ang-0.4,depth-1,col);
}
static JSValue js_draw_fractal_tree(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double xv=double_from_js(ctx,argv[0],320), yv=double_from_js(ctx,argv[1],340);
   double len=double_from_js(ctx,argv[2],60);
   double ang=argc>3?double_from_js(ctx,argv[3],M_PI/2):M_PI/2;
   int depth=argc>4?(int)double_from_js(ctx,argv[4],7):7;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   if(depth>10)depth=10;
   fractal_tree_branch(xv,yv,len,ang,depth,col);
   return JS_UNDEFINED;
}

/* screenReflect(axis) 0=horizontal mirror, 1=vertical mirror */
static JSValue js_screen_reflect(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int axis=argc>0?(int)double_from_js(ctx,argv[0],0):0;
   int W=640,H=360;
   if(axis==0){ /* left half mirrors right */
      for(int ys=0;ys<H;ys++)
         for(int xv=0;xv<W/2;xv++)
            framebuffer[ys*W+xv]=framebuffer[ys*W+(W-1-xv)];
   } else {
      for(int ys=0;ys<H/2;ys++)
         for(int xv=0;xv<W;xv++)
            framebuffer[ys*W+xv]=framebuffer[(H-1-ys)*W+xv];
   }
   return JS_UNDEFINED;
}

/* screenFlipH() */
static JSValue js_screen_flip_h(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val; (void)argc; (void)argv;
   int W=640,H=360;
   for(int ys=0;ys<H;ys++){
      for(int xv=0;xv<W/2;xv++){
         uint32_t t=framebuffer[ys*W+xv];
         framebuffer[ys*W+xv]=framebuffer[ys*W+(W-1-xv)];
         framebuffer[ys*W+(W-1-xv)]=t;
      }
   }
   return JS_UNDEFINED;
}

/* screenFlipV() */
static JSValue js_screen_flip_v(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val; (void)argc; (void)argv;
   int W=640,H=360;
   for(int ys=0;ys<H/2;ys++){
      for(int xv=0;xv<W;xv++){
         uint32_t tv=framebuffer[ys*W+xv];
         framebuffer[ys*W+xv]=framebuffer[(H-1-ys)*W+xv];
         framebuffer[(H-1-ys)*W+xv]=tv;
      }
   }
   return JS_UNDEFINED;
}

/* colorFade(c, t) — lerp toward black */
static JSValue js_color_fade(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[0],0xFFFFFFFFu);
   double tv=argc>1?double_from_js(ctx,argv[1],0.5):0.5;
   if(tv<0)tv=0; if(tv>1)tv=1;
   double keep=1.0-tv;
   uint8_t rv2=(uint8_t)(((col>>24)&0xFF)*keep);
   uint8_t gv2=(uint8_t)(((col>>16)&0xFF)*keep);
   uint8_t bv2=(uint8_t)(((col>>8)&0xFF)*keep);
   return JS_NewInt32(ctx,(int32_t)(((uint32_t)rv2<<24)|((uint32_t)gv2<<16)|((uint32_t)bv2<<8)|(col&0xFF)));
}

/* drawTextBox(x,y,w,h,text,color,bgColor) */
static JSValue js_draw_text_box(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int xv=int_from_js(ctx,argv[0],0), yv=int_from_js(ctx,argv[1],0);
   int wv=int_from_js(ctx,argv[2],80), hv=int_from_js(ctx,argv[3],20);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   uint32_t bg=argc>6?(uint32_t)color_from_js(ctx,argv[6],0x000000FFu):0x000000FFu;
   /* fill bg */
   for(int ys=yv;ys<yv+hv;ys++) for(int xs=xv;xs<xv+wv;xs++) set_pixel(xs,ys,bg);
   /* draw border */
   path_draw_line_segment(xv,yv,xv+wv,yv,col);
   path_draw_line_segment(xv,yv+hv,xv+wv,yv+hv,col);
   path_draw_line_segment(xv,yv,xv,yv+hv,col);
   path_draw_line_segment(xv+wv,yv,xv+wv,yv+hv,col);
   return JS_UNDEFINED;
}

/* screenThermal() */
static JSValue js_screen_thermal(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int W=640,H=360;
   for(int i=0;i<W*H;i++){
      uint32_t pc=framebuffer[i];
      int lum=((int)((pc>>24)&0xFF)*3+(int)((pc>>16)&0xFF)*6+(int)((pc>>8)&0xFF))/10;
      uint8_t rv2,gv2,bv2;
      if(lum<64){ rv2=0; gv2=0; bv2=(uint8_t)(lum*4); }
      else if(lum<128){ rv2=0; gv2=(uint8_t)((lum-64)*4); bv2=255-(uint8_t)((lum-64)*4); }
      else if(lum<192){ rv2=(uint8_t)((lum-128)*4); gv2=255; bv2=0; }
      else{ rv2=255; gv2=255-(uint8_t)((lum-192)*4); bv2=0; }
      framebuffer[i]=((uint32_t)rv2<<24)|((uint32_t)gv2<<16)|((uint32_t)bv2<<8)|(pc&0xFF);
   }
   return JS_UNDEFINED;
}

/* drawArrowCurved(x1,y1,x2,y2,bend,color) — curved arrow via quadratic bezier */
static JSValue js_draw_arrow_curved(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double x1=double_from_js(ctx,argv[0],0), y1=double_from_js(ctx,argv[1],0);
   double x2=double_from_js(ctx,argv[2],100), y2=double_from_js(ctx,argv[3],0);
   double bend=argc>4?double_from_js(ctx,argv[4],30):30;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   /* midpoint control with bend offset */
   double mx=(x1+x2)*0.5, my=(y1+y2)*0.5;
   double dx=x2-x1, dy=y2-y1, len=sqrt(dx*dx+dy*dy)+0.001;
   double nx2=-dy/len, ny2=dx/len;
   double cpx=mx+nx2*bend, cpy=my+ny2*bend;
   /* draw quadratic bezier */
   int N=40; double px2=x1,py2=y1;
   for(int i=1;i<=N;i++){
      double tv=(double)i/N;
      double inv=1-tv;
      double nx3=inv*inv*x1+2*inv*tv*cpx+tv*tv*x2;
      double ny3=inv*inv*y1+2*inv*tv*cpy+tv*tv*y2;
      path_draw_line_segment((int)px2,(int)py2,(int)nx3,(int)ny3,col);
      px2=nx3; py2=ny3;
   }
   /* arrowhead at end */
   double ex=x2-cpx, ey=y2-cpy, elen=sqrt(ex*ex+ey*ey)+0.001;
   ex/=elen; ey/=elen;
   int ah=10;
   path_draw_line_segment((int)x2,(int)y2,(int)(x2-ex*ah-ey*ah*0.5),(int)(y2-ey*ah+ex*ah*0.5),col);
   path_draw_line_segment((int)x2,(int)y2,(int)(x2-ex*ah+ey*ah*0.5),(int)(y2-ey*ah-ex*ah*0.5),col);
   return JS_UNDEFINED;
}

/* ── Batch 25: explosion, lightning, hex grid, border, sobel, diamond ──── */

/* drawExplosion(cx,cy,r,spikes,color) */
static JSValue js_draw_explosion(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],50);
   int spikes=argc>3?(int)double_from_js(ctx,argv[3],8):8;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   if(spikes<3)spikes=3; if(spikes>24)spikes=24;
   double inner=rv*0.5;
   for(int i=0;i<spikes;i++){
      double a1=2*M_PI*i/spikes - M_PI/2;
      double a2=2*M_PI*(i+0.5)/spikes - M_PI/2;
      double a3=2*M_PI*(i+1)/spikes - M_PI/2;
      int ox=(int)(cx+cos(a1)*rv), oy=(int)(cy+sin(a1)*rv);
      int mx=(int)(cx+cos(a2)*inner), my=(int)(cy+sin(a2)*inner);
      int nx=(int)(cx+cos(a3)*rv), ny=(int)(cy+sin(a3)*rv);
      path_draw_line_segment(ox,oy,mx,my,col);
      path_draw_line_segment(mx,my,nx,ny,col);
   }
   return JS_UNDEFINED;
}

/* fillExplosion(cx,cy,r,spikes,color) */
static JSValue js_fill_explosion(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],50);
   int spikes=argc>3?(int)double_from_js(ctx,argv[3],8):8;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   if(spikes<3)spikes=3; if(spikes>24)spikes=24;
   double inner=rv*0.5;
   int N=spikes*2;
   int px2[48], py2[48];
   for(int i=0;i<N;i++){
      double ang=2*M_PI*i/N - M_PI/2;
      double rr=(i%2==0)?rv:inner;
      px2[i]=(int)(cx+cos(ang)*rr);
      py2[i]=(int)(cy+sin(ang)*rr);
   }
   int miny=py2[0],maxy=py2[0];
   for(int i=1;i<N;i++){if(py2[i]<miny)miny=py2[i];if(py2[i]>maxy)maxy=py2[i];}
   for(int ys=miny;ys<=maxy;ys++){
      int xs[48]; int nc=0;
      for(int i=0;i<N;i++){
         int j=(i+1)%N;
         int ay=py2[i],by=py2[j];
         if((ay<=ys&&by>ys)||(by<=ys&&ay>ys)){
            xs[nc++]=px2[i]+(px2[j]-px2[i])*(ys-ay)/(by-ay);
         }
      }
      for(int ii=0;ii<nc-1;ii++) for(int jj=ii+1;jj<nc;jj++) if(xs[jj]<xs[ii]){int t=xs[ii];xs[ii]=xs[jj];xs[jj]=t;}
      for(int ii=0;ii+1<nc;ii+=2) for(int xv=xs[ii];xv<=xs[ii+1];xv++) set_pixel(xv,ys,col);
   }
   return JS_UNDEFINED;
}

/* screenPixelSort(threshold) */
static JSValue js_screen_pixel_sort(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double threshold=argc>0?double_from_js(ctx,argv[0],0.5):0.5;
   int thresh=(int)(threshold*255*3);
   int W=640,H=360;
   for(int ys=0;ys<H;ys++){
      int start=-1;
      for(int xv=0;xv<=W;xv++){
         int bright=0;
         if(xv<W){
            uint32_t pc=framebuffer[ys*W+xv];
            bright=((pc>>24)&0xFF)+((pc>>16)&0xFF)+((pc>>8)&0xFF);
         }
         if(xv<W && bright>=thresh){
            if(start<0) start=xv;
         } else {
            if(start>=0){
               /* sort segment by brightness */
               int len2=xv-start;
               for(int ii=0;ii<len2-1;ii++){
                  for(int jj=ii+1;jj<len2;jj++){
                     uint32_t pa=framebuffer[ys*W+start+ii];
                     uint32_t pb=framebuffer[ys*W+start+jj];
                     int ba=((pa>>24)&0xFF)+((pa>>16)&0xFF)+((pa>>8)&0xFF);
                     int bb=((pb>>24)&0xFF)+((pb>>16)&0xFF)+((pb>>8)&0xFF);
                     if(bb<ba){framebuffer[ys*W+start+ii]=pb;framebuffer[ys*W+start+jj]=pa;}
                  }
               }
               start=-1;
            }
         }
      }
   }
   return JS_UNDEFINED;
}

/* drawHexGrid(x,y,w,h,size,color) */
static JSValue js_draw_hex_grid(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int xv=int_from_js(ctx,argv[0],0), yv=int_from_js(ctx,argv[1],0);
   int wv=int_from_js(ctx,argv[2],200), hv=int_from_js(ctx,argv[3],200);
   double sz=double_from_js(ctx,argv[4],20);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   double hex_w=sz*2, hex_h=sz*sqrt(3.0);
   double col_step=hex_w*0.75, row_step=hex_h;
   int cols2=(int)(wv/col_step)+2, rows=(int)(hv/row_step)+2;
   for(int r2=0;r2<rows;r2++){
      for(int cc=0;cc<cols2;cc++){
         double cx2=xv+cc*col_step;
         double cy2=yv+r2*row_step+(cc%2)*hex_h*0.5;
         for(int k=0;k<6;k++){
            double a1=M_PI/6+k*M_PI/3, a2=M_PI/6+(k+1)*M_PI/3;
            int x1a=(int)(cx2+cos(a1)*sz), y1a=(int)(cy2+sin(a1)*sz);
            int x2a=(int)(cx2+cos(a2)*sz), y2a=(int)(cy2+sin(a2)*sz);
            if(x1a<xv||x1a>xv+wv||x2a<xv||x2a>xv+wv) continue;
            path_draw_line_segment(x1a,y1a,x2a,y2a,col);
         }
      }
   }
   return JS_UNDEFINED;
}

/* fillHexGrid(x,y,w,h,size,color,fillColor) */
static JSValue js_fill_hex_grid(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int xv=int_from_js(ctx,argv[0],0), yv=int_from_js(ctx,argv[1],0);
   int wv=int_from_js(ctx,argv[2],200), hv=int_from_js(ctx,argv[3],200);
   double sz=double_from_js(ctx,argv[4],20);
   uint32_t border=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   uint32_t fill=argc>6?(uint32_t)color_from_js(ctx,argv[6],0x333333FFu):0x333333FFu;
   double hex_w=sz*2, hex_h=sz*sqrt(3.0);
   double col_step=hex_w*0.75, row_step=hex_h;
   int cols2=(int)(wv/col_step)+2, rows=(int)(hv/row_step)+2;
   for(int r2=0;r2<rows;r2++){
      for(int cc=0;cc<cols2;cc++){
         double cx2=xv+cc*col_step;
         double cy2=yv+r2*row_step+(cc%2)*hex_h*0.5;
         /* fill hex */
         int pts_x[6],pts_y[6];
         for(int k=0;k<6;k++){
            double ang=M_PI/6+k*M_PI/3;
            pts_x[k]=(int)(cx2+cos(ang)*(sz-1));
            pts_y[k]=(int)(cy2+sin(ang)*(sz-1));
         }
         int miny=pts_y[0],maxy=pts_y[0];
         for(int k=1;k<6;k++){if(pts_y[k]<miny)miny=pts_y[k];if(pts_y[k]>maxy)maxy=pts_y[k];}
         for(int ys=miny;ys<=maxy;ys++){
            int xs[6]; int nc=0;
            for(int k=0;k<6;k++){
               int j=(k+1)%6;
               int ay=pts_y[k],by=pts_y[j];
               if((ay<=ys&&by>ys)||(by<=ys&&ay>ys)){
                  xs[nc++]=pts_x[k]+(pts_x[j]-pts_x[k])*(ys-ay)/(by-ay);
               }
            }
            if(nc>=2){if(xs[1]<xs[0]){int t=xs[0];xs[0]=xs[1];xs[1]=t;}
               for(int x3=xs[0];x3<=xs[1];x3++) if(x3>=xv&&x3<xv+wv&&ys>=yv&&ys<yv+hv) set_pixel(x3,ys,fill);}
         }
         /* border */
         for(int k=0;k<6;k++){
            double a1=M_PI/6+k*M_PI/3, a2=M_PI/6+(k+1)*M_PI/3;
            int x1a=(int)(cx2+cos(a1)*sz), y1a=(int)(cy2+sin(a1)*sz);
            int x2a=(int)(cx2+cos(a2)*sz), y2a=(int)(cy2+sin(a2)*sz);
            if(x1a<xv||x1a>xv+wv||x2a<xv||x2a>xv+wv) continue;
            path_draw_line_segment(x1a,y1a,x2a,y2a,border);
         }
      }
   }
   return JS_UNDEFINED;
}

/* drawTriGrid(x,y,w,h,size,color) */
static JSValue js_draw_tri_grid(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int xv=int_from_js(ctx,argv[0],0), yv=int_from_js(ctx,argv[1],0);
   int wv=int_from_js(ctx,argv[2],200), hv=int_from_js(ctx,argv[3],200);
   int sz=int_from_js(ctx,argv[4],20);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   double h2=(double)sz*sqrt(3.0)/2;
   int rows=(int)(hv/h2)+1, cols2=wv/sz+1;
   for(int r2=0;r2<=rows;r2++){
      int ys=(int)(yv+r2*h2);
      /* horizontal lines */
      path_draw_line_segment(xv,ys,xv+wv,ys,col);
      /* diagonal lines */
      for(int cc=0;cc<=cols2;cc++){
         int x1a=xv+cc*sz+(r2%2)*sz/2;
         path_draw_line_segment(x1a,ys,x1a-sz/2,(int)(ys+h2),col);
         path_draw_line_segment(x1a,ys,x1a+sz/2,(int)(ys+h2),col);
      }
   }
   return JS_UNDEFINED;
}

/* drawBorder(x,y,w,h,thickness,color) */
static JSValue js_draw_border(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int xv=int_from_js(ctx,argv[0],0), yv=int_from_js(ctx,argv[1],0);
   int wv=int_from_js(ctx,argv[2],100), hv=int_from_js(ctx,argv[3],100);
   int thick=int_from_js(ctx,argv[4],2);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   if(thick<1)thick=1;
   for(int t=0;t<thick;t++){
      path_draw_line_segment(xv+t,yv+t,xv+wv-t,yv+t,col);
      path_draw_line_segment(xv+t,yv+hv-t,xv+wv-t,yv+hv-t,col);
      path_draw_line_segment(xv+t,yv+t,xv+t,yv+hv-t,col);
      path_draw_line_segment(xv+wv-t,yv+t,xv+wv-t,yv+hv-t,col);
   }
   return JS_UNDEFINED;
}

/* fillBorder(x,y,w,h,thickness,outerColor,innerColor) */
static JSValue js_fill_border(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int xv=int_from_js(ctx,argv[0],0), yv=int_from_js(ctx,argv[1],0);
   int wv=int_from_js(ctx,argv[2],100), hv=int_from_js(ctx,argv[3],100);
   int thick=int_from_js(ctx,argv[4],4);
   uint32_t ocol=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   uint32_t icol=argc>6?(uint32_t)color_from_js(ctx,argv[6],0x000000FFu):0x000000FFu;
   /* fill inner */
   for(int ys=yv+thick;ys<yv+hv-thick;ys++)
      for(int xs=xv+thick;xs<xv+wv-thick;xs++) set_pixel(xs,ys,icol);
   /* fill border ring */
   for(int ys=yv;ys<yv+hv;ys++){
      int in_border=(ys<yv+thick||ys>=yv+hv-thick);
      for(int xs=xv;xs<xv+wv;xs++){
         if(in_border||xs<xv+thick||xs>=xv+wv-thick) set_pixel(xs,ys,ocol);
      }
   }
   return JS_UNDEFINED;
}

/* screenSobel() */
static JSValue js_screen_sobel(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int W=640,H=360;
   uint32_t *scratch=(uint32_t*)malloc(W*H*sizeof(uint32_t));
   if(!scratch) return JS_UNDEFINED;
   memcpy(scratch,framebuffer,W*H*sizeof(uint32_t));
   for(int ys=1;ys<H-1;ys++){
      for(int xv=1;xv<W-1;xv++){
         /* luminance of 3x3 neighbourhood */
         int lum[3][3];
         for(int dy2=-1;dy2<=1;dy2++) for(int dx2=-1;dx2<=1;dx2++){
            uint32_t pc=scratch[(ys+dy2)*W+(xv+dx2)];
            lum[dy2+1][dx2+1]=((int)((pc>>24)&0xFF)*3+(int)((pc>>16)&0xFF)*6+(int)((pc>>8)&0xFF))/10;
         }
         int gx=(-lum[0][0]+lum[0][2]-2*lum[1][0]+2*lum[1][2]-lum[2][0]+lum[2][2]);
         int gy=(-lum[0][0]-2*lum[0][1]-lum[0][2]+lum[2][0]+2*lum[2][1]+lum[2][2]);
         int mag=(int)sqrt((double)(gx*gx+gy*gy)); if(mag>255)mag=255;
         framebuffer[ys*W+xv]=((uint32_t)mag<<24)|((uint32_t)mag<<16)|((uint32_t)mag<<8)|0xFFu;
      }
   }
   free(scratch);
   return JS_UNDEFINED;
}

/* colorShift2(c, hueDeg, satMult, valMult) */
static JSValue js_color_shift2(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[0],0xFF8000FFu);
   double hueDeg=argc>1?double_from_js(ctx,argv[1],0):0;
   double satMult=argc>2?double_from_js(ctx,argv[2],1.0):1.0;
   double valMult=argc>3?double_from_js(ctx,argv[3],1.0):1.0;
   uint8_t rv2=(col>>24)&0xFF, gv=(col>>16)&0xFF, bv2=(col>>8)&0xFF, av=(col)&0xFF;
   double rf=rv2/255.0, gf=gv/255.0, bf=bv2/255.0;
   double maxc=rf>gf?rf:gf; if(bf>maxc)maxc=bf;
   double minc=rf<gf?rf:gf; if(bf<minc)minc=bf;
   double hh=0,ss=0,vv=maxc*valMult,delta=maxc-minc;
   if(vv>1)vv=1;
   if(delta>1e-6){ ss=delta/maxc;
      if(maxc==rf) hh=(gf-bf)/delta+(gf<bf?6:0);
      else if(maxc==gf) hh=(bf-rf)/delta+2;
      else hh=(rf-gf)/delta+4;
      hh/=6.0;
   }
   hh=fmod(hh+hueDeg/360.0+1.0,1.0);
   ss*=satMult; if(ss>1)ss=1; if(ss<0)ss=0;
   double h6=hh*6.0; int hi=(int)h6; double ff=h6-hi;
   double pp=vv*(1-ss),qq=vv*(1-ss*ff),tv2=vv*(1-ss*(1-ff));
   double nr=0,ng=0,nb=0;
   switch(hi%6){case 0:nr=vv;ng=tv2;nb=pp;break;case 1:nr=qq;ng=vv;nb=pp;break;
                case 2:nr=pp;ng=vv;nb=tv2;break;case 3:nr=pp;ng=qq;nb=vv;break;
                case 4:nr=tv2;ng=pp;nb=vv;break;default:nr=vv;ng=pp;nb=qq;break;}
   uint32_t nc=(((uint32_t)(nr*255))<<24)|(((uint32_t)(ng*255))<<16)|(((uint32_t)(nb*255))<<8)|(uint32_t)av;
   return JS_NewInt32(ctx,(int32_t)nc);
}

/* drawDiamond2(cx,cy,hw,hh,color) */
static JSValue js_draw_diamond2(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int cx2=int_from_js(ctx,argv[0],0), cy2=int_from_js(ctx,argv[1],0);
   int hw=int_from_js(ctx,argv[2],20), hh=int_from_js(ctx,argv[3],20);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   path_draw_line_segment(cx2,cy2-hh,cx2+hw,cy2,col);
   path_draw_line_segment(cx2+hw,cy2,cx2,cy2+hh,col);
   path_draw_line_segment(cx2,cy2+hh,cx2-hw,cy2,col);
   path_draw_line_segment(cx2-hw,cy2,cx2,cy2-hh,col);
   return JS_UNDEFINED;
}

/* ── Batch 24: DNA, vortex, mandala, halftone, label, cloud, noise ─────── */

/* drawDNA(cx,cy,r,turns,height,color) */
static JSValue js_draw_dna(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],30);
   double turns=double_from_js(ctx,argv[3],3);
   double height=double_from_js(ctx,argv[4],100);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   int N=80;
   for(int i=0;i<N;i++){
      double t1=(double)i/N, t2=(double)(i+1)/N;
      double a1=t1*turns*2*M_PI, a2=t2*turns*2*M_PI;
      int x1a=(int)(cx+cos(a1)*rv), y1a=(int)(cy-height/2+t1*height);
      int x2a=(int)(cx+cos(a2)*rv), y2a=(int)(cy-height/2+t2*height);
      int x1b=(int)(cx+cos(a1+M_PI)*rv), x2b=(int)(cx+cos(a2+M_PI)*rv);
      path_draw_line_segment(x1a,y1a,x2a,y2a,col);
      uint32_t col2=(col&0x00FFFFFFu)|0x88000000u; /* dimmer second strand */
      uint8_t cr=(col>>24)&0xFF, cg=(col>>16)&0xFF, cb=(col>>8)&0xFF;
      col2=((uint32_t)(cr/2)<<24)|((uint32_t)(cg/2)<<16)|((uint32_t)(cb/2)<<8)|(col&0xFF);
      path_draw_line_segment(x1b,y1a,x2b,y2a,col2);
      /* rungs every ~quarter turn */
      if(i%8==0){
         path_draw_line_segment(x1a,y1a,x1b,y1a,col);
      }
   }
   return JS_UNDEFINED;
}

/* fillDNA — alias with same rungs but thicker style */
static JSValue js_fill_dna(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],30);
   double turns=double_from_js(ctx,argv[3],3);
   double height=double_from_js(ctx,argv[4],100);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   uint8_t cr=(col>>24)&0xFF, cg=(col>>16)&0xFF, cb=(col>>8)&0xFF, ca=(col)&0xFF;
   uint32_t col2=((uint32_t)(cg)<<24)|((uint32_t)(cb)<<16)|((uint32_t)(cr)<<8)|(uint32_t)ca;
   int N=80;
   for(int i=0;i<N;i++){
      double t1=(double)i/N;
      double a1=t1*turns*2*M_PI;
      int y1a=(int)(cy-height/2+t1*height);
      int x1a=(int)(cx+cos(a1)*rv);
      int x1b=(int)(cx+cos(a1+M_PI)*rv);
      /* thick strand dots */
      for(int d=-1;d<=1;d++){
         set_pixel(x1a,y1a+d,col);
         set_pixel(x1b,y1a+d,col2);
      }
      if(i%8==0){
         /* filled rung */
         int xlo=x1a<x1b?x1a:x1b, xhi=x1a>x1b?x1a:x1b;
         for(int xv=xlo;xv<=xhi;xv++) set_pixel(xv,y1a,rgba8((cr+cg)/2,(cg+cb)/2,(cb+cr)/2,ca));
      }
   }
   return JS_UNDEFINED;
}

/* drawVortex(cx,cy,r,turns,color) */
static JSValue js_draw_vortex(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],60);
   double turns=double_from_js(ctx,argv[3],4);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   int arms=6, N=60;
   for(int arm=0;arm<arms;arm++){
      double base_ang = (double)arm/arms*2*M_PI;
      for(int i=0;i<N;i++){
         double t1=(double)i/N, t2=(double)(i+1)/N;
         double a1=base_ang+t1*turns*2*M_PI, a2=base_ang+t2*turns*2*M_PI;
         double r1=t1*rv, r2=t2*rv;
         path_draw_line_segment((int)(cx+cos(a1)*r1),(int)(cy+sin(a1)*r1),
                                (int)(cx+cos(a2)*r2),(int)(cy+sin(a2)*r2),col);
      }
   }
   return JS_UNDEFINED;
}

/* drawMandala(cx,cy,r,petals,color) */
static JSValue js_draw_mandala(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],60);
   int petals=argc>3?(int)double_from_js(ctx,argv[3],8):8;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   if(petals<3)petals=3; if(petals>24)petals=24;
   /* outer ring of circles */
   for(int p=0;p<petals;p++){
      double ang=(double)p/petals*2*M_PI;
      double px2=cx+cos(ang)*rv*0.6, py2=cy+sin(ang)*rv*0.6;
      double pr=rv*0.35;
      int N=32;
      for(int i=0;i<N;i++){
         double a1=2*M_PI*i/N, a2=2*M_PI*(i+1)/N;
         path_draw_line_segment((int)(px2+cos(a1)*pr),(int)(py2+sin(a1)*pr),
                                (int)(px2+cos(a2)*pr),(int)(py2+sin(a2)*pr),col);
      }
      /* spoke */
      path_draw_line_segment((int)cx,(int)cy,(int)(cx+cos(ang)*rv),(int)(cy+sin(ang)*rv),col);
   }
   /* center circle */
   int N=40;
   double cr2=rv*0.2;
   for(int i=0;i<N;i++){
      double a1=2*M_PI*i/N, a2=2*M_PI*(i+1)/N;
      path_draw_line_segment((int)(cx+cos(a1)*cr2),(int)(cy+sin(a1)*cr2),
                             (int)(cx+cos(a2)*cr2),(int)(cy+sin(a2)*cr2),col);
   }
   return JS_UNDEFINED;
}

/* screenHalftone(dotSize) */
static JSValue js_screen_halftone(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int dotSize=argc>0?(int)double_from_js(ctx,argv[0],6):6;
   if(dotSize<2)dotSize=2; if(dotSize>20)dotSize=20;
   int W=640,H=360;
   uint32_t *scratch=(uint32_t*)malloc(W*H*sizeof(uint32_t));
   if(!scratch) return JS_UNDEFINED;
   memcpy(scratch,framebuffer,W*H*sizeof(uint32_t));
   /* clear to black */
   memset(framebuffer,0,W*H*sizeof(uint32_t));
   for(int ys=0;ys<H;ys+=dotSize){
      for(int xv=0;xv<W;xv+=dotSize){
         /* average brightness of cell */
         long rr=0,gg=0,bb=0; int cnt=0;
         for(int dy2=0;dy2<dotSize&&ys+dy2<H;dy2++){
            for(int dx2=0;dx2<dotSize&&xv+dx2<W;dx2++){
               uint32_t pc=scratch[(ys+dy2)*W+(xv+dx2)];
               rr+=(pc>>24)&0xFF; gg+=(pc>>16)&0xFF; bb+=(pc>>8)&0xFF; cnt++;
            }
         }
         if(!cnt){continue;}
         int avgr=(int)(rr/cnt),avgg=(int)(gg/cnt),avgb=(int)(bb/cnt);
         double brightness=(avgr+avgg+avgb)/3.0/255.0;
         double maxR=(dotSize/2.0)*sqrt(brightness);
         int cx2=xv+dotSize/2, cy2=ys+dotSize/2;
         uint32_t dc=((uint32_t)avgr<<24)|((uint32_t)avgg<<16)|((uint32_t)avgb<<8)|0xFFu;
         for(int dy2=-(int)maxR;dy2<=(int)maxR;dy2++){
            for(int dx2=-(int)maxR;dx2<=(int)maxR;dx2++){
               if(dx2*dx2+dy2*dy2<=(int)(maxR*maxR)){
                  int px3=cx2+dx2,py3=cy2+dy2;
                  if(px3>=0&&px3<W&&py3>=0&&py3<H) framebuffer[py3*W+px3]=dc;
               }
            }
         }
      }
   }
   free(scratch);
   return JS_UNDEFINED;
}

/* smoothstep2(edge0, edge1, t) */
static JSValue js_smoothstep2(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double edge0=double_from_js(ctx,argv[0],0);
   double edge1=double_from_js(ctx,argv[1],1);
   double tv=double_from_js(ctx,argv[2],0.5);
   if(edge1==edge0) return JS_NewFloat64(ctx,0);
   double x2=(tv-edge0)/(edge1-edge0);
   if(x2<0)x2=0; if(x2>1)x2=1;
   return JS_NewFloat64(ctx, x2*x2*(3-2*x2));
}

/* drawLabel(x,y,text,color,bgColor) */
static JSValue js_draw_label(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int xv=int_from_js(ctx,argv[0],0), yv=int_from_js(ctx,argv[1],0);
   /* draw bg rect then text via existing JS print — but we are in C, so we draw a rect manually */
   uint32_t fg=(uint32_t)color_from_js(ctx,argv[3],0xFFFFFFFFu);
   uint32_t bg=(uint32_t)color_from_js(ctx,argv[4],0x000000FFu);
   /* get text length estimate */
   size_t tlen=0;
   const char *str=NULL;
   if(argc>2 && JS_IsString(argv[2])){
      str=JS_ToCString(ctx,argv[2]);
      if(str) tlen=strlen(str);
   }
   int tw=(int)tlen*4+4, th=10;
   /* background */
   for(int ys2=yv;ys2<yv+th;ys2++) for(int xs=xv;xs<xv+tw;xs++) set_pixel(xs,ys2,bg);
   /* border */
   for(int xs=xv;xs<xv+tw;xs++){ set_pixel(xs,yv,fg); set_pixel(xs,yv+th-1,fg); }
   for(int ys2=yv;ys2<yv+th;ys2++){ set_pixel(xv,ys2,fg); set_pixel(xv+tw-1,ys2,fg); }
   if(str) JS_FreeCString(ctx,str);
   return JS_UNDEFINED;
}

/* drawTag(x,y,text,color,bgColor) — badge with pointed left edge */
static JSValue js_draw_tag(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int xv=int_from_js(ctx,argv[0],0), yv=int_from_js(ctx,argv[1],0);
   uint32_t fg=(uint32_t)color_from_js(ctx,argv[3],0xFFFFFFFFu);
   uint32_t bg=(uint32_t)color_from_js(ctx,argv[4],0x3344AAFFu);
   size_t tlen=0;
   const char *str=NULL;
   if(argc>2 && JS_IsString(argv[2])){
      str=JS_ToCString(ctx,argv[2]);
      if(str) tlen=strlen(str);
   }
   int tw=(int)tlen*4+8, th=12, half=th/2;
   /* filled trapezoid body */
   for(int ys2=0;ys2<th;ys2++){
      int indent=(ys2<half)?(half-ys2):(ys2-half);
      for(int xs=xv+indent;xs<xv+tw;xs++) set_pixel(xs,yv+ys2,bg);
   }
   /* outline */
   for(int ys2=0;ys2<th;ys2++){
      int indent=(ys2<half)?(half-ys2):(ys2-half);
      set_pixel(xv+indent,yv+ys2,fg);
      set_pixel(xv+tw-1,yv+ys2,fg);
   }
   for(int xs=xv+half;xs<xv+tw;xs++){ set_pixel(xs,yv,fg); set_pixel(xs,yv+th-1,fg); }
   if(str) JS_FreeCString(ctx,str);
   return JS_UNDEFINED;
}

/* fillCloud(cx,cy,w,h,color) */
static JSValue js_fill_cloud(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double wv=double_from_js(ctx,argv[2],80), hv=double_from_js(ctx,argv[3],40);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   /* main body ellipse */
   double rx=wv*0.5, ry=hv*0.5;
   int miny=(int)(cy-ry-ry*0.6), maxy=(int)(cy+ry);
   for(int ys=(int)(cy-ry);ys<=(int)(cy+ry);ys++){
      double dy2=ys-cy; if(dy2*dy2>ry*ry) continue;
      double dx2=sqrt(rx*rx*(1.0-dy2*dy2/(ry*ry)));
      for(int xv=(int)(cx-dx2);xv<=(int)(cx+dx2);xv++) set_pixel(xv,ys,col);
   }
   /* top bumps */
   struct { double ox, oy, br; } bumps[3]={{-wv*0.25,-ry*0.4,hv*0.5},{0,-ry*0.7,hv*0.55},{wv*0.25,-ry*0.3,hv*0.45}};
   for(int b=0;b<3;b++){
      double bx=cx+bumps[b].ox, by2=cy+bumps[b].oy, br=bumps[b].br;
      for(int ys=(int)(by2-br);ys<=(int)(by2+br);ys++){
         double dy2=ys-by2; if(dy2*dy2>br*br) continue;
         double dx2=sqrt(br*br-dy2*dy2);
         for(int xv=(int)(bx-dx2);xv<=(int)(bx+dx2);xv++) set_pixel(xv,ys,col);
      }
   }
   (void)miny; (void)maxy;
   return JS_UNDEFINED;
}

/* screenNoise(amount) */
static JSValue js_screen_noise(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double amount=argc>0?double_from_js(ctx,argv[0],0.1):0.1;
   if(amount<0)amount=0; if(amount>1)amount=1;
   int W=640,H=360;
   /* LCG random */
   uint32_t seed=12345;
   for(int i=0;i<W*H;i++){
      seed=seed*1664525u+1013904223u;
      int noise=(int)(((seed>>16)&0xFF)-128);
      int n2=(int)(noise*amount);
      uint32_t pc=framebuffer[i];
      int rv2=((pc>>24)&0xFF)+n2; if(rv2<0)rv2=0; if(rv2>255)rv2=255;
      int gv2=((pc>>16)&0xFF)+n2; if(gv2<0)gv2=0; if(gv2>255)gv2=255;
      int bv2=((pc>>8)&0xFF)+n2;  if(bv2<0)bv2=0; if(bv2>255)bv2=255;
      framebuffer[i]=((uint32_t)rv2<<24)|((uint32_t)gv2<<16)|((uint32_t)bv2<<8)|(pc&0xFF);
   }
   return JS_UNDEFINED;
}

/* colorWheel(angle) -> color */
static JSValue js_color_wheel(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double ang=double_from_js(ctx,argv[0],0);
   double hh=fmod(ang/360.0+1.0,1.0);
   double h6=hh*6.0; int hi=(int)h6; double ff=h6-hi;
   double nr=0,ng=0,nb=0;
   switch(hi%6){case 0:nr=1;ng=ff;nb=0;break;case 1:nr=1-ff;ng=1;nb=0;break;
                case 2:nr=0;ng=1;nb=ff;break;case 3:nr=0;ng=1-ff;nb=1;break;
                case 4:nr=ff;ng=0;nb=1;break;default:nr=1;ng=0;nb=1-ff;break;}
   return JS_NewInt32(ctx,(int32_t)(((uint32_t)(nr*255))<<24)|(((uint32_t)(ng*255))<<16)|(((uint32_t)(nb*255))<<8)|0xFFu);
}

/* drawPulse(cx,cy,r,t,color) */
static JSValue js_draw_pulse(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],50);
   double tv=argc>3?double_from_js(ctx,argv[3],0.5):0.5;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   double cur_r=rv*tv;
   uint8_t alpha=(uint8_t)((1.0-tv)*255);
   uint32_t c2=(col&0xFFFFFF00u)|(uint32_t)alpha;
   int N=64;
   for(int i=0;i<N;i++){
      double a1=2*M_PI*i/N, a2=2*M_PI*(i+1)/N;
      path_draw_line_segment((int)(cx+cos(a1)*cur_r),(int)(cy+sin(a1)*cur_r),
                             (int)(cx+cos(a2)*cur_r),(int)(cy+sin(a2)*cur_r),c2);
   }
   return JS_UNDEFINED;
}

/* ── Batch 23: lerp2D, colorAnalogous, comet, rainbow, helix, dither ───── */

/* lerp2D(x1,y1,x2,y2,t) -> [rx,ry] */
static JSValue js_lerp2d(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double x1=double_from_js(ctx,argv[0],0), y1=double_from_js(ctx,argv[1],0);
   double x2=double_from_js(ctx,argv[2],0), y2=double_from_js(ctx,argv[3],0);
   double tv=double_from_js(ctx,argv[4],0);
   JSValue arr=JS_NewArray(ctx);
   JS_SetPropertyUint32(ctx,arr,0,JS_NewFloat64(ctx,x1+(x2-x1)*tv));
   JS_SetPropertyUint32(ctx,arr,1,JS_NewFloat64(ctx,y1+(y2-y1)*tv));
   return arr;
}

/* colorAnalogous(c, spread) -> [c1, c2] */
static JSValue js_color_analogous(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[0],0xFF8000FFu);
   double spread=argc>1?double_from_js(ctx,argv[1],30.0):30.0;
   uint8_t rv2=(col>>24)&0xFF, gv=(col>>16)&0xFF, bv2=(col>>8)&0xFF, av=(col)&0xFF;
   double rf=rv2/255.0, gf=gv/255.0, bf=bv2/255.0;
   double maxc=rf>gf?rf:gf; if(bf>maxc)maxc=bf;
   double minc=rf<gf?rf:gf; if(bf<minc)minc=bf;
   double hh=0,ss=0,vv=maxc, delta=maxc-minc;
   if(delta>1e-6){ ss=delta/maxc;
      if(maxc==rf) hh=(gf-bf)/delta+(gf<bf?6:0);
      else if(maxc==gf) hh=(bf-rf)/delta+2;
      else hh=(rf-gf)/delta+4;
      hh/=6.0;
   }
   JSValue arr=JS_NewArray(ctx);
   for(int k=0;k<2;k++){
      double dh=(k==0?-spread:spread)/360.0;
      double nh=fmod(hh+dh+1.0,1.0);
      double h6=nh*6.0; int hi=(int)h6; double ff=h6-hi;
      double pp=vv*(1-ss),qq=vv*(1-ss*ff),tv2=vv*(1-ss*(1-ff));
      double nr,ng,nb;
      switch(hi%6){case 0:nr=vv;ng=tv2;nb=pp;break;case 1:nr=qq;ng=vv;nb=pp;break;
                   case 2:nr=pp;ng=vv;nb=tv2;break;case 3:nr=pp;ng=qq;nb=vv;break;
                   case 4:nr=tv2;ng=pp;nb=vv;break;default:nr=vv;ng=pp;nb=qq;break;}
      uint32_t nc=(((uint32_t)(nr*255))<<24)|(((uint32_t)(ng*255))<<16)|(((uint32_t)(nb*255))<<8)|(uint32_t)av;
      JS_SetPropertyUint32(ctx,arr,k,JS_NewInt32(ctx,(int32_t)nc));
   }
   return arr;
}

/* colorSplit(c) -> [r,g,b,a] */
static JSValue js_color_split(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[0],0xFFFFFFFFu);
   JSValue arr=JS_NewArray(ctx);
   JS_SetPropertyUint32(ctx,arr,0,JS_NewInt32(ctx,(col>>24)&0xFF));
   JS_SetPropertyUint32(ctx,arr,1,JS_NewInt32(ctx,(col>>16)&0xFF));
   JS_SetPropertyUint32(ctx,arr,2,JS_NewInt32(ctx,(col>>8)&0xFF));
   JS_SetPropertyUint32(ctx,arr,3,JS_NewInt32(ctx,col&0xFF));
   return arr;
}

/* drawComet(x1,y1,x2,y2,radius,color) */
static JSValue js_draw_comet(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double x1=double_from_js(ctx,argv[0],0), y1=double_from_js(ctx,argv[1],0);
   double x2=double_from_js(ctx,argv[2],100), y2=double_from_js(ctx,argv[3],0);
   double radius=double_from_js(ctx,argv[4],6);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   /* head circle */
   int steps=32;
   for(int i=0;i<steps;i++){
      double a1=2*M_PI*i/steps,a2=2*M_PI*(i+1)/steps;
      path_draw_line_segment((int)(x2+cos(a1)*radius),(int)(y2+sin(a1)*radius),
                             (int)(x2+cos(a2)*radius),(int)(y2+sin(a2)*radius),col);
   }
   /* tail lines */
   double dx=x1-x2, dy=y1-y2, len=sqrt(dx*dx+dy*dy);
   if(len<1) len=1;
   double nx=dx/len, ny=dy/len;
   for(int i=0;i<5;i++){
      double off=(i-2)*radius*0.3;
      double px1=x2+ny*off, py1=y2-nx*off;
      double px2=x1+ny*off*0.3, py2=y1-nx*off*0.3;
      uint8_t alpha=(uint8_t)(200-(i-2)*(i-2)*20);
      uint32_t tc=(col&0xFFFFFF00u)|(uint32_t)alpha;
      path_draw_line_segment((int)px1,(int)py1,(int)px2,(int)py2,tc);
   }
   return JS_UNDEFINED;
}

/* fillComet(x1,y1,x2,y2,radius,color) */
static JSValue js_fill_comet(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double x1=double_from_js(ctx,argv[0],0), y1=double_from_js(ctx,argv[1],0);
   double x2=double_from_js(ctx,argv[2],100), y2=double_from_js(ctx,argv[3],0);
   double radius=double_from_js(ctx,argv[4],6);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   /* filled head */
   int iy0=(int)(y2-radius), iy1=(int)(y2+radius);
   for(int ys=iy0;ys<=iy1;ys++){
      double dy2=ys-y2;
      if(dy2*dy2>radius*radius) continue;
      double dx2=sqrt(radius*radius-dy2*dy2);
      for(int xv=(int)(x2-dx2);xv<=(int)(x2+dx2);xv++) set_pixel(xv,ys,col);
   }
   /* filled tail triangle */
   double dx=x1-x2,dy=y1-y2,len=sqrt(dx*dx+dy*dy);
   if(len<1) len=1;
   double nx=dx/len,ny=dy/len;
   int N=20;
   for(int i=0;i<=N;i++){
      double tv=(double)i/N;
      double mx=x2+dx*tv, my=y2+dy*tv;
      double hw=radius*(1.0-tv)*0.8;
      uint8_t alpha=(uint8_t)(200*(1.0-tv));
      uint32_t tc=(col&0xFFFFFF00u)|(uint32_t)alpha;
      path_draw_line_segment((int)(mx+ny*hw),(int)(my-nx*hw),(int)(mx-ny*hw),(int)(my+nx*hw),tc);
   }
   return JS_UNDEFINED;
}

/* drawRainbow(cx,cy,r,thickness,alpha) */
static JSValue js_draw_rainbow(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],80);
   double thick=double_from_js(ctx,argv[3],8);
   int alphav=argc>4?(int)double_from_js(ctx,argv[4],255):255;
   int bands=7;
   double bw=thick/bands;
   float hues[7]={0,0.083f,0.167f,0.333f,0.5f,0.583f,0.667f};
   for(int b=0;b<bands;b++){
      double rb=rv-b*bw;
      /* HSV to RGB: s=1 v=1 */
      double hh=hues[b]*6.0; int hi=(int)hh; double ff=hh-hi;
      double pp=0,qq=1.0-ff,tv2=ff;
      double nr=0,ng=0,nb=0;
      switch(hi%6){case 0:nr=1;ng=tv2;nb=pp;break;case 1:nr=qq;ng=1;nb=pp;break;
                   case 2:nr=pp;ng=1;nb=tv2;break;case 3:nr=pp;ng=qq;nb=1;break;
                   case 4:nr=tv2;ng=pp;nb=1;break;default:nr=1;ng=pp;nb=qq;break;}
      uint32_t col=(((uint32_t)(nr*255))<<24)|(((uint32_t)(ng*255))<<16)|(((uint32_t)(nb*255))<<8)|(uint32_t)alphav;
      int N=60;
      for(int i=0;i<N;i++){
         double a1=M_PI+M_PI*i/N, a2=M_PI+M_PI*(i+1)/N;
         path_draw_line_segment((int)(cx+cos(a1)*rb),(int)(cy+sin(a1)*rb),
                                (int)(cx+cos(a2)*rb),(int)(cy+sin(a2)*rb),col);
      }
   }
   return JS_UNDEFINED;
}

/* drawHelix(cx,cy,r,turns,height,color) */
static JSValue js_draw_helix(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],40);
   double turns=double_from_js(ctx,argv[3],3);
   double height=double_from_js(ctx,argv[4],80);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   int N=80;
   for(int i=0;i<N;i++){
      double t1=(double)i/N, t2=(double)(i+1)/N;
      double a1=t1*turns*2*M_PI, a2=t2*turns*2*M_PI;
      int px1=(int)(cx+cos(a1)*rv), py1=(int)(cy-height/2+t1*height);
      int px2=(int)(cx+cos(a2)*rv), py2=(int)(cy-height/2+t2*height);
      uint8_t bright=(uint8_t)(128+127*sin(a1));
      uint32_t c2=(((uint32_t)((col>>24)&0xFF)*bright/255)<<24)|(((uint32_t)((col>>16)&0xFF)*bright/255)<<16)|(((uint32_t)((col>>8)&0xFF)*bright/255)<<8)|(col&0xFF);
      path_draw_line_segment(px1,py1,px2,py2,c2);
      /* back strand offset by PI */
      int bx1=(int)(cx+cos(a1+M_PI)*rv);
      int bx2=(int)(cx+cos(a2+M_PI)*rv);
      uint8_t b2=(uint8_t)(80+60*sin(a1+M_PI));
      uint32_t c3=(((uint32_t)((col>>24)&0xFF)*b2/255)<<24)|(((uint32_t)((col>>16)&0xFF)*b2/255)<<16)|(((uint32_t)((col>>8)&0xFF)*b2/255)<<8)|(col&0xFF);
      path_draw_line_segment(bx1,py1,bx2,py2,c3);
   }
   return JS_UNDEFINED;
}

/* fillProgressBar(x,y,w,h,t,fgColor,bgColor) */
static JSValue js_fill_progress_bar(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int xv=int_from_js(ctx,argv[0],0), yv=int_from_js(ctx,argv[1],0);
   int wv=int_from_js(ctx,argv[2],100), hv=int_from_js(ctx,argv[3],10);
   double tv=argc>4?double_from_js(ctx,argv[4],0.5):0.5;
   uint32_t fg=(uint32_t)color_from_js(ctx,argv[5],0x00FF00FFu);
   uint32_t bg=(uint32_t)color_from_js(ctx,argv[6],0x333333FFu);
   if(tv<0)tv=0; if(tv>1)tv=1;
   /* background */
   for(int ys=yv;ys<yv+hv;ys++) for(int xs=xv;xs<xv+wv;xs++) set_pixel(xs,ys,bg);
   /* fill */
   int fw=(int)(wv*tv);
   for(int ys=yv;ys<yv+hv;ys++) for(int xs=xv;xs<xv+fw;xs++) set_pixel(xs,ys,fg);
   return JS_UNDEFINED;
}

/* fillSpiral(cx,cy,r,turns,color) */
static JSValue js_fill_spiral(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],50);
   double turns=double_from_js(ctx,argv[3],3);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   int N=200;
   for(int i=0;i<N;i++){
      double t1=(double)i/N, t2=(double)(i+1)/N;
      double a1=t1*turns*2*M_PI, a2=t2*turns*2*M_PI;
      double r1=t1*rv, r2=t2*rv;
      int px1=(int)(cx+cos(a1)*r1), py1=(int)(cy+sin(a1)*r1);
      int px2=(int)(cx+cos(a2)*r2), py2=(int)(cy+sin(a2)*r2);
      path_draw_line_segment(px1,py1,px2,py2,col);
      /* fill width by drawing to previous outer ring */
      double r3=t1*rv+rv/turns*0.5;
      int px3=(int)(cx+cos(a1)*r3), py3=(int)(cy+sin(a1)*r3);
      path_draw_line_segment(px1,py1,px3,py3,col);
   }
   return JS_UNDEFINED;
}

/* drawWave(x,y,w,amp,freq,phase,color) */
static JSValue js_draw_wave(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int xv=int_from_js(ctx,argv[0],0), yv=int_from_js(ctx,argv[1],180);
   int wv=int_from_js(ctx,argv[2],200);
   double amp=double_from_js(ctx,argv[3],20);
   double freq=double_from_js(ctx,argv[4],1);
   double phase=double_from_js(ctx,argv[5],0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[6],0xFFFFFFFFu);
   for(int i=0;i<wv-1;i++){
      double t1=(double)i/wv, t2=(double)(i+1)/wv;
      int py1=(int)(yv+sin(t1*2*M_PI*freq+phase)*amp);
      int py2=(int)(yv+sin(t2*2*M_PI*freq+phase)*amp);
      path_draw_line_segment(xv+i,py1,xv+i+1,py2,col);
   }
   return JS_UNDEFINED;
}

/* screenDither(levels) */
static JSValue js_screen_dither(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int levels=argc>0?(int)double_from_js(ctx,argv[0],4):4;
   if(levels<2)levels=2; if(levels>16)levels=16;
   /* 4x4 Bayer matrix */
   static const int bayer4[4][4]={{0,8,2,10},{12,4,14,6},{3,11,1,9},{15,7,13,5}};
   int W=640,H=360;
   for(int ys=0;ys<H;ys++){
      for(int xv=0;xv<W;xv++){
         uint32_t pc=framebuffer[ys*W+xv];
         int bv2=bayer4[ys%4][xv%4];
         uint8_t rr=(pc>>24)&0xFF, gr=(pc>>16)&0xFF, br=(pc>>8)&0xFF, ar=pc&0xFF;
         int step=255/(levels-1);
         rr=(uint8_t)(((int)rr+bv2*step/16)/step*step); if(rr>255)rr=255;
         gr=(uint8_t)(((int)gr+bv2*step/16)/step*step); if(gr>255)gr=255;
         br=(uint8_t)(((int)br+bv2*step/16)/step*step); if(br>255)br=255;
         framebuffer[ys*W+xv]=((uint32_t)rr<<24)|((uint32_t)gr<<16)|((uint32_t)br<<8)|(uint32_t)ar;
      }
   }
   return JS_UNDEFINED;
}

/* drawGlow(cx,cy,r,color) */
static JSValue js_draw_glow(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],30);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[3],0xFFFFFFFFu);
   uint8_t cr=(col>>24)&0xFF, cg=(col>>16)&0xFF, cb=(col>>8)&0xFF;
   int ir=(int)rv, W=640, H=360;
   for(int ys=(int)(cy-rv);ys<=(int)(cy+rv);ys++){
      if(ys<0||ys>=H) continue;
      for(int xv=(int)(cx-rv);xv<=(int)(cx+rv);xv++){
         if(xv<0||xv>=W) continue;
         double dx2=xv-cx,dy2=ys-cy;
         double dist=sqrt(dx2*dx2+dy2*dy2);
         if(dist>rv) continue;
         double alpha=(1.0-dist/rv);
         alpha=alpha*alpha;
         uint32_t dc=framebuffer[ys*W+xv];
         int dr=(dc>>24)&0xFF,dg=(dc>>16)&0xFF,db2=(dc>>8)&0xFF,da=dc&0xFF;
         dr=(int)(dr+(int)cr*alpha); if(dr>255)dr=255;
         dg=(int)(dg+(int)cg*alpha); if(dg>255)dg=255;
         db2=(int)(db2+(int)cb*alpha); if(db2>255)db2=255;
         framebuffer[ys*W+xv]=((uint32_t)dr<<24)|((uint32_t)dg<<16)|((uint32_t)db2<<8)|(uint32_t)da;
      }
   }
   (void)ir;
   return JS_UNDEFINED;
}

/* ── Batch 22: distance, intersect, pentagram, crescent, bloom, color ──── */

/* distanceXY(x1,y1,x2,y2) */
static JSValue js_distance_xy(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double x1=double_from_js(ctx,argv[0],0); double y1=double_from_js(ctx,argv[1],0);
   double x2=double_from_js(ctx,argv[2],0); double y2=double_from_js(ctx,argv[3],0);
   double dx=x2-x1, dy=y2-y1;
   return JS_NewFloat64(ctx, sqrt(dx*dx+dy*dy));
}

/* lineIntersect(x1,y1,x2,y2,x3,y3,x4,y4) -> array [ix,iy,hit] */
static JSValue js_line_intersect(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double px=double_from_js(ctx,argv[0],0), py=double_from_js(ctx,argv[1],0);
   double rx=double_from_js(ctx,argv[2],0)-px, ry=double_from_js(ctx,argv[3],0)-py;
   double qx=double_from_js(ctx,argv[4],0), qy=double_from_js(ctx,argv[5],0);
   double sx=double_from_js(ctx,argv[6],0)-qx, sy=double_from_js(ctx,argv[7],0)-qy;
   double denom = rx*sy - ry*sx;
   JSValue arr = JS_NewArray(ctx);
   if (fabs(denom) < 1e-10) {
      JS_SetPropertyUint32(ctx, arr, 0, JS_NewFloat64(ctx, 0));
      JS_SetPropertyUint32(ctx, arr, 1, JS_NewFloat64(ctx, 0));
      JS_SetPropertyUint32(ctx, arr, 2, JS_NewBool(ctx, 0));
   } else {
      double tv = ((qx-px)*sy - (qy-py)*sx) / denom;
      double uv = ((qx-px)*ry - (qy-py)*rx) / denom;
      int hit = (tv>=0.0 && tv<=1.0 && uv>=0.0 && uv<=1.0);
      JS_SetPropertyUint32(ctx, arr, 0, JS_NewFloat64(ctx, px+tv*rx));
      JS_SetPropertyUint32(ctx, arr, 1, JS_NewFloat64(ctx, py+tv*ry));
      JS_SetPropertyUint32(ctx, arr, 2, JS_NewBool(ctx, hit));
   }
   return arr;
}

/* drawPentagram(cx,cy,r,rot,color) */
static JSValue js_draw_pentagram(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],50);
   double rot=double_from_js(ctx,argv[3],0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   /* inner radius for pentagram points */
   double ri = rv * 0.381966;
   double pts_ox[10], pts_oy[10];
   for (int i=0; i<10; i++) {
      double ang = rot + (i * M_PI / 5.0) - M_PI/2.0;
      double rr = (i%2==0) ? rv : ri;
      pts_ox[i] = cx + cos(ang)*rr;
      pts_oy[i] = cy + sin(ang)*rr;
   }
   for (int i=0; i<10; i++) {
      int j=(i+1)%10;
      path_draw_line_segment((int)pts_ox[i],(int)pts_oy[i],(int)pts_ox[j],(int)pts_oy[j],col);
   }
   return JS_UNDEFINED;
}

/* fillPentagram(cx,cy,r,rot,color) */
static JSValue js_fill_pentagram(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],50);
   double rot=double_from_js(ctx,argv[3],0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   double ri = rv * 0.381966;
   int px_arr[10], py_arr[10];
   for (int i=0; i<10; i++) {
      double ang = rot + (i * M_PI / 5.0) - M_PI/2.0;
      double rr = (i%2==0) ? rv : ri;
      px_arr[i] = (int)(cx + cos(ang)*rr);
      py_arr[i] = (int)(cy + sin(ang)*rr);
   }
   /* scan-line fill */
   int miny = py_arr[0], maxy = py_arr[0];
   for (int i=1; i<10; i++) {
      if (py_arr[i]<miny) miny=py_arr[i];
      if (py_arr[i]>maxy) maxy=py_arr[i];
   }
   for (int ys=miny; ys<=maxy; ys++) {
      int xs[10]; int nc=0;
      for (int i=0; i<10; i++) {
         int j=(i+1)%10;
         int ay=py_arr[i], by=py_arr[j];
         if ((ay<=ys && by>ys)||(by<=ys && ay>ys)) {
            xs[nc++] = px_arr[i] + (px_arr[j]-px_arr[i])*(ys-ay)/(by-ay);
         }
      }
      /* sort xs */
      for (int ii=0; ii<nc-1; ii++) for (int jj=ii+1; jj<nc; jj++) if (xs[jj]<xs[ii]) { int t=xs[ii]; xs[ii]=xs[jj]; xs[jj]=t; }
      for (int ii=0; ii+1<nc; ii+=2) {
         for (int xv=xs[ii]; xv<=xs[ii+1]; xv++) set_pixel(xv,ys,col);
      }
   }
   return JS_UNDEFINED;
}

/* drawCrescent(cx,cy,r,offset,color) */
static JSValue js_draw_crescent(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],40);
   double off=double_from_js(ctx,argv[3],12);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   int N=64;
   for (int i=0; i<N; i++) {
      double ang1 = 2*M_PI*i/N, ang2 = 2*M_PI*(i+1)/N;
      path_draw_line_segment((int)(cx+cos(ang1)*rv),(int)(cy+sin(ang1)*rv),
                             (int)(cx+cos(ang2)*rv),(int)(cy+sin(ang2)*rv), col);
   }
   /* inner circle */
   double ir = rv * 0.7;
   double ocx = cx + off;
   for (int i=0; i<N; i++) {
      double ang1 = 2*M_PI*i/N, ang2 = 2*M_PI*(i+1)/N;
      path_draw_line_segment((int)(ocx+cos(ang1)*ir),(int)(cy+sin(ang1)*ir),
                             (int)(ocx+cos(ang2)*ir),(int)(cy+sin(ang2)*ir), col);
   }
   return JS_UNDEFINED;
}

/* fillCrescent(cx,cy,r,offset,color) */
static JSValue js_fill_crescent(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double cx=double_from_js(ctx,argv[0],0), cy=double_from_js(ctx,argv[1],0);
   double rv=double_from_js(ctx,argv[2],40);
   double off=double_from_js(ctx,argv[3],12);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   double ir = rv * 0.7;
   double ocx = cx + off;
   int miny=(int)(cy-rv), maxy=(int)(cy+rv);
   if (miny<0) miny=0; if (maxy>359) maxy=359;
   for (int ys=miny; ys<=maxy; ys++) {
      double dy = ys - cy;
      if (fabs(dy)>rv) continue;
      double dx = sqrt(rv*rv - dy*dy);
      int x0=(int)(cx-dx), x1=(int)(cx+dx);
      for (int xv=x0; xv<=x1; xv++) {
         double ddx = xv - ocx;
         if (ddx*ddx + dy*dy > ir*ir) {
            set_pixel(xv, ys, col);
         }
      }
   }
   return JS_UNDEFINED;
}

/* screenBloom(radius, threshold, intensity) */
static JSValue js_screen_bloom(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int radius = argc>0 ? (int)double_from_js(ctx,argv[0],4) : 4;
   double threshold = argc>1 ? double_from_js(ctx,argv[1],0.7) : 0.7;
   double intensity = argc>2 ? double_from_js(ctx,argv[2],0.5) : 0.5;
   if (radius < 1) radius = 1; if (radius > 20) radius = 20;
   int W=640, H=360;
   uint32_t *scratch = (uint32_t*)malloc(W*H*sizeof(uint32_t));
   if (!scratch) return JS_UNDEFINED;
   memcpy(scratch, framebuffer, W*H*sizeof(uint32_t));
   for (int ys=0; ys<H; ys++) {
      for (int xv=0; xv<W; xv++) {
         uint32_t pc = scratch[ys*W+xv];
         double rr=((pc>>24)&0xFF)/255.0, gr=((pc>>16)&0xFF)/255.0, bv=((pc>>8)&0xFF)/255.0;
         double brightness=(rr+gr+bv)/3.0;
         if (brightness < threshold) continue;
         double str = (brightness - threshold) / (1.0 - threshold + 0.001) * intensity;
         for (int dy2=-radius; dy2<=radius; dy2++) {
            for (int dx2=-radius; dx2<=radius; dx2++) {
               int nx=xv+dx2, ny=ys+dy2;
               if (nx<0||nx>=W||ny<0||ny>=H) continue;
               double dist2 = dx2*dx2+dy2*dy2;
               if (dist2 > radius*radius) continue;
               double w = str*(1.0-sqrt(dist2)/(radius+1));
               if (w<0) w=0;
               uint32_t dc = framebuffer[ny*W+nx];
               int dr=(dc>>24)&0xFF, dg=(dc>>16)&0xFF, db2=(dc>>8)&0xFF, da=(dc)&0xFF;
               dr = (int)(dr + rr*255*w); if(dr>255)dr=255;
               dg = (int)(dg + gr*255*w); if(dg>255)dg=255;
               db2= (int)(db2+ bv*255*w); if(db2>255)db2=255;
               framebuffer[ny*W+nx] = ((uint32_t)dr<<24)|((uint32_t)dg<<16)|((uint32_t)db2<<8)|(uint32_t)da;
            }
         }
      }
   }
   free(scratch);
   return JS_UNDEFINED;
}

/* colorComplement(c) -> hue+180 */
static JSValue js_color_complement(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[0],0xFF0000FFu);
   uint8_t rv2=(col>>24)&0xFF, gv=(col>>16)&0xFF, bv2=(col>>8)&0xFF, av=(col)&0xFF;
   double rf=rv2/255.0, gf=gv/255.0, bf=bv2/255.0;
   double maxc=rf>gf?rf:gf; if(bf>maxc)maxc=bf;
   double minc=rf<gf?rf:gf; if(bf<minc)minc=bf;
   double hh=0,ss=0,vv=maxc;
   double delta=maxc-minc;
   if(delta>1e-6){ ss=delta/maxc;
      if(maxc==rf) hh=(gf-bf)/delta + (gf<bf?6:0);
      else if(maxc==gf) hh=(bf-rf)/delta+2;
      else hh=(rf-gf)/delta+4;
      hh/=6.0;
   }
   hh = fmod(hh+0.5, 1.0);
   /* HSV back to RGB */
   double h6=hh*6.0; int hi=(int)h6; double ff=h6-hi;
   double pp=vv*(1-ss), qq=vv*(1-ss*ff), tv2=vv*(1-ss*(1-ff));
   double nr,ng,nb;
   switch(hi%6){
      case 0: nr=vv;ng=tv2;nb=pp; break;
      case 1: nr=qq;ng=vv;nb=pp; break;
      case 2: nr=pp;ng=vv;nb=tv2;break;
      case 3: nr=pp;ng=qq;nb=vv; break;
      case 4: nr=tv2;ng=pp;nb=vv;break;
      default:nr=vv;ng=pp;nb=qq; break;
   }
   uint8_t ro=(uint8_t)(nr*255), go=(uint8_t)(ng*255), bo=(uint8_t)(nb*255);
   return JS_NewInt32(ctx,(int32_t)(((uint32_t)ro<<24)|((uint32_t)go<<16)|((uint32_t)bo<<8)|(uint32_t)av));
}

/* bitCount(n) */
static JSValue js_bit_count(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int32_t nv=int_from_js(ctx,argv[0],0);
   uint32_t uv=(uint32_t)nv;
   uv = uv - ((uv>>1)&0x55555555u);
   uv = (uv&0x33333333u) + ((uv>>2)&0x33333333u);
   uv = (uv + (uv>>4)) & 0x0f0f0f0fu;
   return JS_NewInt32(ctx,(int32_t)((uv*0x01010101u)>>24));
}

/* nextPow2(n) */
static JSValue js_next_pow2(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int32_t nv=int_from_js(ctx,argv[0],1);
   if (nv<=1) return JS_NewInt32(ctx,1);
   uint32_t uv=(uint32_t)(nv-1);
   uv|=uv>>1; uv|=uv>>2; uv|=uv>>4; uv|=uv>>8; uv|=uv>>16;
   return JS_NewInt32(ctx,(int32_t)(uv+1));
}

/* formatBytes(n) -> string */
static JSValue js_format_bytes(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double nv=double_from_js(ctx,argv[0],0);
   char buf[64];
   if (nv >= 1073741824.0)      snprintf(buf,sizeof(buf),"%.2f GB", nv/1073741824.0);
   else if (nv >= 1048576.0)    snprintf(buf,sizeof(buf),"%.2f MB", nv/1048576.0);
   else if (nv >= 1024.0)       snprintf(buf,sizeof(buf),"%.2f KB", nv/1024.0);
   else                         snprintf(buf,sizeof(buf),"%.0f B",  nv);
   return JS_NewString(ctx, buf);
}

/* stagger(index, count, t, staggerAmt) */
static JSValue js_stagger(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double idx=double_from_js(ctx,argv[0],0);
   double cnt=double_from_js(ctx,argv[1],1);
   double tv=double_from_js(ctx,argv[2],0);
   double amt=double_from_js(ctx,argv[3],0.1);
   if(cnt<=1) cnt=1;
   double delay = (idx/(cnt-1 < 1 ? 1 : cnt-1)) * amt;
   double local_t = (tv - delay) / (1.0 - amt + 0.0001);
   if(local_t<0) local_t=0; if(local_t>1) local_t=1;
   return JS_NewFloat64(ctx, local_t);
}

/* ── Batch 21: nested rects, parallelogram, trapezoid, polygon, duotone ─── */

/* drawNestedRects(x,y,w,h,n,gap,color) */
static JSValue js_draw_nested_rects(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 7) return JS_UNDEFINED;
   int nx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int ny=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int nw=(int)double_from_js(ctx,argv[2],100.0);
   int nh=(int)double_from_js(ctx,argv[3],80.0);
   int nn=(int)double_from_js(ctx,argv[4],4.0);
   int ng=(int)double_from_js(ctx,argv[5],5.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[6],0xFFFFFFFFu);
   for (int i=0;i<nn;i++){
      int rw=nw-i*ng*2, rh=nh-i*ng*2;
      if (rw<2||rh<2) break;
      int rx=nx+i*ng, ry=ny+i*ng;
      for (int x2=rx;x2<rx+rw;x2++) { set_pixel(x2,ry,col); set_pixel(x2,ry+rh-1,col); }
      for (int y2=ry;y2<ry+rh;y2++) { set_pixel(rx,y2,col); set_pixel(rx+rw-1,y2,col); }
   }
   return JS_UNDEFINED;
}

/* fillNestedRects(x,y,w,h,n,gap,c1,c2) — alternating fill */
static JSValue js_fill_nested_rects(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 8) return JS_UNDEFINED;
   int nx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int ny=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int nw=(int)double_from_js(ctx,argv[2],100.0);
   int nh=(int)double_from_js(ctx,argv[3],80.0);
   int nn=(int)double_from_js(ctx,argv[4],4.0);
   int ng=(int)double_from_js(ctx,argv[5],5.0);
   uint32_t c1=(uint32_t)color_from_js(ctx,argv[6],0xFFFFFFFFu);
   uint32_t c2=(uint32_t)color_from_js(ctx,argv[7],0xFF000000u);
   /* fill outermost to innermost */
   for (int i=nn-1;i>=0;i--){
      int rw=nw-i*ng*2, rh=nh-i*ng*2;
      if (rw<1||rh<1) continue;
      int rx=nx+i*ng, ry=ny+i*ng;
      uint32_t col=(i%2==0)?c1:c2;
      for (int y2=ry;y2<ry+rh;y2++)
         for (int x2=rx;x2<rx+rw;x2++) set_pixel(x2,y2,col);
   }
   return JS_UNDEFINED;
}

/* drawParallelogram(x,y,w,h,skew,color) — outline parallelogram */
static JSValue js_draw_parallelogram(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 6) return JS_UNDEFINED;
   int px=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int py=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int pw=(int)double_from_js(ctx,argv[2],80.0);
   int ph=(int)double_from_js(ctx,argv[3],40.0);
   int sk=(int)double_from_js(ctx,argv[4],20.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   /* corners: top-left=(px+sk,py), top-right=(px+sk+pw,py),
               bottom-left=(px,py+ph), bottom-right=(px+pw,py+ph) */
   path_draw_line_segment(px+sk, py,    px+sk+pw, py,    col);
   path_draw_line_segment(px+sk+pw,py,  px+pw,   py+ph, col);
   path_draw_line_segment(px+pw,  py+ph,px,      py+ph, col);
   path_draw_line_segment(px,     py+ph,px+sk,   py,    col);
   return JS_UNDEFINED;
}

/* fillParallelogram(x,y,w,h,skew,color) */
static JSValue js_fill_parallelogram(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 6) return JS_UNDEFINED;
   int px=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int py=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int pw=(int)double_from_js(ctx,argv[2],80.0);
   int ph=(int)double_from_js(ctx,argv[3],40.0);
   int sk=(int)double_from_js(ctx,argv[4],20.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   for (int y2=py;y2<py+ph;y2++){
      double t=(double)(y2-py)/ph;
      int x0=px+(int)(sk*(1.0-t));
      for (int x2=x0;x2<x0+pw;x2++) set_pixel(x2,y2,col);
   }
   return JS_UNDEFINED;
}

/* drawTrapezoid(x,y,w1,w2,h,color) — top width w1, bottom width w2 */
static JSValue js_draw_trapezoid(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 6) return JS_UNDEFINED;
   int tx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int ty=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int w1=(int)double_from_js(ctx,argv[2],80.0);
   int w2=(int)double_from_js(ctx,argv[3],60.0);
   int th=(int)double_from_js(ctx,argv[4],40.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   int off=(w2-w1)/2;
   /* top edge */
   path_draw_line_segment(tx,    ty,    tx+w1, ty,    col);
   /* bottom edge */
   path_draw_line_segment(tx+off,ty+th, tx+off+w2,ty+th, col);
   /* sides */
   path_draw_line_segment(tx,    ty,    tx+off,    ty+th, col);
   path_draw_line_segment(tx+w1, ty,    tx+off+w2, ty+th, col);
   return JS_UNDEFINED;
}

/* fillTrapezoid(x,y,w1,w2,h,color) */
static JSValue js_fill_trapezoid(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 6) return JS_UNDEFINED;
   int tx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int ty=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int w1=(int)double_from_js(ctx,argv[2],80.0);
   int w2=(int)double_from_js(ctx,argv[3],60.0);
   int th=(int)double_from_js(ctx,argv[4],40.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   if (th<=0) return JS_UNDEFINED;
   for (int y2=ty;y2<ty+th;y2++){
      double t=(double)(y2-ty)/th;
      int cw=(int)(w1+(w2-w1)*t);
      int off=(w2-w1)/2;
      int x0=(int)(tx+off*(1.0-t));
      for (int x2=x0;x2<x0+cw;x2++) set_pixel(x2,y2,col);
   }
   return JS_UNDEFINED;
}

/* drawConcentricPolygons(cx,cy,sides,r,n,gap,color) */
static JSValue js_draw_concentric_polygons(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 7) return JS_UNDEFINED;
   int pcx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int pcy=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int sides=(int)double_from_js(ctx,argv[2],6.0);
   double pr =double_from_js(ctx,argv[3],50.0);
   int pn  =(int)double_from_js(ctx,argv[4],4.0);
   double pg=double_from_js(ctx,argv[5],8.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[6],0xFFFFFFFFu);
   if (sides<3) sides=3; if (pn<1) pn=1;
   for (int i=0;i<pn;i++){
      double ri=pr-i*pg;
      if (ri<=0) break;
      for (int s=0;s<sides;s++){
         double a1=s*2.0*M_PI/sides, a2=(s+1)*2.0*M_PI/sides;
         path_draw_line_segment((int)(pcx+cos(a1)*ri),(int)(pcy+sin(a1)*ri),
                                (int)(pcx+cos(a2)*ri),(int)(pcy+sin(a2)*ri),col);
      }
   }
   return JS_UNDEFINED;
}

/* fillCheckerCircle(cx,cy,r,step,c1,c2) — checkerboard clipped to circle */
static JSValue js_fill_checker_circle(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 6) return JS_UNDEFINED;
   int ccx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int ccy=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int cr =(int)double_from_js(ctx,argv[2],40.0);
   int cs =(int)double_from_js(ctx,argv[3],8.0);
   uint32_t c1=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   uint32_t c2=(uint32_t)color_from_js(ctx,argv[5],0xFF000000u);
   if (cs<1) cs=1;
   for (int y2=ccy-cr;y2<=ccy+cr;y2++)
      for (int x2=ccx-cr;x2<=ccx+cr;x2++){
         double dist=sqrt((double)(x2-ccx)*(x2-ccx)+(double)(y2-ccy)*(y2-ccy));
         if (dist>cr) continue;
         int tx=((x2-ccx+cr)/cs), ty=((y2-ccy+cr)/cs);
         set_pixel(x2,y2,((tx+ty)%2==0)?c1:c2);
      }
   return JS_UNDEFINED;
}

/* colorFromRandom(seed) — seeded color (Xorshift32) */
static JSValue js_color_from_random(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   uint32_t seed=(uint32_t)(argc>0?double_from_js(ctx,argv[0],1.0):1.0);
   if (!seed) seed=1;
   seed^=seed<<13; seed^=seed>>17; seed^=seed<<5;
   uint32_t r2=(seed>>24)&0xFF, g2=(seed>>16)&0xFF, b2=(seed>>8)&0xFF;
   return JS_NewInt32(ctx,(int32_t)((r2<<24)|(g2<<16)|(b2<<8)|0xFF));
}

/* drawNeonLine(x1,y1,x2,y2,glow,color) — line with additive glow */
static JSValue js_draw_neon_line(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 6) return JS_UNDEFINED;
   float nx1=(float)double_from_js(ctx,argv[0],0.0)-(float)cam2d_x;
   float ny1=(float)double_from_js(ctx,argv[1],0.0)-(float)cam2d_y;
   float nx2=(float)double_from_js(ctx,argv[2],100.0)-(float)cam2d_x;
   float ny2=(float)double_from_js(ctx,argv[3],0.0)-(float)cam2d_y;
   int   glow=(int)double_from_js(ctx,argv[4],3.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   if (glow<0) glow=0; if (glow>10) glow=10;
   uint32_t cr=(col>>24)&0xFF,cg=(col>>16)&0xFF,cb=(col>>8)&0xFF;
   int steps=(int)(sqrtf((nx2-nx1)*(nx2-nx1)+(ny2-ny1)*(ny2-ny1))+1);
   for (int s=0;s<=steps;s++){
      float t=(float)s/steps;
      int px2=(int)(nx1+(nx2-nx1)*t), py2=(int)(ny1+(ny2-ny1)*t);
      /* core */
      set_pixel(px2,py2,col);
      /* glow layers */
      for (int g2=1;g2<=glow;g2++){
         double falloff=1.0-(double)g2/(glow+1);
         uint32_t gr=(uint32_t)(cr*falloff), gg=(uint32_t)(cg*falloff), gb2=(uint32_t)(cb*falloff);
         uint32_t gc2=(gr<<24)|(gg<<16)|(gb2<<8)|((uint32_t)(200*falloff));
         for (int dy=-g2;dy<=g2;dy++)
            for (int dx=-g2;dx<=g2;dx++){
               if (dx==0&&dy==0) continue;
               if (abs(dx)+abs(dy)>g2+1) continue;
               int sx=px2+dx, sy=py2+dy;
               if (sx<0||sx>=NOVA64_WIDTH||sy<0||sy>=NOVA64_HEIGHT) continue;
               uint32_t ep=framebuffer[sy*NOVA64_WIDTH+sx];
               int er=(int)((ep>>24)&0xFF)+(int)gr;
               int eg=(int)((ep>>16)&0xFF)+(int)gg;
               int eb=(int)((ep>> 8)&0xFF)+(int)gb2;
               if(er>255)er=255;if(eg>255)eg=255;if(eb>255)eb=255;
               framebuffer[sy*NOVA64_WIDTH+sx]=((uint32_t)er<<24)|((uint32_t)eg<<16)|((uint32_t)eb<<8)|((ep)&0xFF);
               (void)gc2;
            }
      }
   }
   return JS_UNDEFINED;
}

/* screenDuotone(c1,c2) — map dark tones → c1, light tones → c2 */
static JSValue js_screen_duotone(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 2) return JS_UNDEFINED;
   uint32_t dc1=(uint32_t)color_from_js(ctx,argv[0],0xFF000000u);
   uint32_t dc2=(uint32_t)color_from_js(ctx,argv[1],0xFFFFFFFFu);

   int cx0=0,cy0=0,cw=NOVA64_WIDTH,ch=NOVA64_HEIGHT;
   if (clip_active){cx0=clip_x;cy0=clip_y;cw=clip_w;ch=clip_h;}
   int x1=cx0,y1=cy0,x2=cx0+cw-1,y2=cy0+ch-1;
   if (x2>=NOVA64_WIDTH) x2=NOVA64_WIDTH-1;
   if (y2>=NOVA64_HEIGHT) y2=NOVA64_HEIGHT-1;

   for (int y=y1;y<=y2;y++){
      for (int x=x1;x<=x2;x++){
         uint32_t p=framebuffer[y*NOVA64_WIDTH+x];
         int lum=((int)((p>>24)&0xFF)*299+(int)((p>>16)&0xFF)*587+(int)((p>>8)&0xFF)*114)/1000;
         double t=lum/255.0;
         double it=1.0-t;
         uint32_t r=(uint32_t)(((dc1>>24)&0xFF)*it+((dc2>>24)&0xFF)*t+0.5);
         uint32_t g=(uint32_t)(((dc1>>16)&0xFF)*it+((dc2>>16)&0xFF)*t+0.5);
         uint32_t b=(uint32_t)(((dc1>> 8)&0xFF)*it+((dc2>> 8)&0xFF)*t+0.5);
         framebuffer[y*NOVA64_WIDTH+x]=(r<<24)|(g<<16)|(b<<8)|((p)&0xFF);
      }
   }
   return JS_UNDEFINED;
}

/* gradientCircle(cx,cy,r,c1,c2,angle) — linear gradient clipped to circle */
static JSValue js_gradient_circle(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 5) return JS_UNDEFINED;
   int gcx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int gcy=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int gr =(int)double_from_js(ctx,argv[2],40.0);
   uint32_t gc1=(uint32_t)color_from_js(ctx,argv[3],0xFF000000u);
   uint32_t gc2=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   double ang=(argc>5?double_from_js(ctx,argv[5],0.0):0.0)*M_PI/180.0;
   double ca=cos(ang),sa=sin(ang);
   for (int y2=gcy-gr;y2<=gcy+gr;y2++){
      for (int x2=gcx-gr;x2<=gcx+gr;x2++){
         double dist=sqrt((double)(x2-gcx)*(x2-gcx)+(double)(y2-gcy)*(y2-gcy));
         if (dist>gr) continue;
         double dot=((x2-gcx)*ca+(y2-gcy)*sa)/gr;
         double t2=(dot+1.0)*0.5;
         if(t2<0)t2=0;if(t2>1)t2=1;
         double it2=1.0-t2;
         uint32_t r=(uint32_t)(((gc1>>24)&0xFF)*it2+((gc2>>24)&0xFF)*t2+0.5);
         uint32_t g=(uint32_t)(((gc1>>16)&0xFF)*it2+((gc2>>16)&0xFF)*t2+0.5);
         uint32_t b=(uint32_t)(((gc1>> 8)&0xFF)*it2+((gc2>> 8)&0xFF)*t2+0.5);
         uint32_t a=(uint32_t)(((gc1    )&0xFF)*it2+((gc2    )&0xFF)*t2+0.5);
         set_pixel(x2,y2,(r<<24)|(g<<16)|(b<<8)|a);
      }
   }
   return JS_UNDEFINED;
}

/* ── Batch 20: target, spider web, brick, wave shape, flame, zoom, util ─── */

/* drawTarget(cx,cy,r,rings,color) — concentric ring target */
static JSValue js_draw_target(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 5) return JS_UNDEFINED;
   int tcx =(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int tcy =(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int tr  =(int)double_from_js(ctx,argv[2],40.0);
   int rings=(int)double_from_js(ctx,argv[3],4.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   if (rings<1) rings=1;
   for (int i=1;i<=rings;i++){
      int ri=tr*i/rings;
      for (int y2=tcy-ri;y2<=tcy+ri;y2++)
         for (int x2=tcx-ri;x2<=tcx+ri;x2++){
            double d=sqrt((double)(x2-tcx)*(x2-tcx)+(double)(y2-tcy)*(y2-tcy));
            if (d>ri-1&&d<=ri) set_pixel(x2,y2,col);
         }
   }
   return JS_UNDEFINED;
}

/* fillTarget(cx,cy,r,rings,c1,c2) — alternating color bullseye */
static JSValue js_fill_target(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 6) return JS_UNDEFINED;
   int tcx  =(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int tcy  =(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int tr   =(int)double_from_js(ctx,argv[2],40.0);
   int rings=(int)double_from_js(ctx,argv[3],4.0);
   uint32_t c1=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   uint32_t c2=(uint32_t)color_from_js(ctx,argv[5],0xFF0000FFu);
   if (rings<1) rings=1;
   for (int y2=tcy-tr;y2<=tcy+tr;y2++)
      for (int x2=tcx-tr;x2<=tcx+tr;x2++){
         double d=sqrt((double)(x2-tcx)*(x2-tcx)+(double)(y2-tcy)*(y2-tcy));
         if (d>tr) continue;
         int ring=(int)(d*rings/tr);
         set_pixel(x2,y2,(ring%2==0)?c1:c2);
      }
   return JS_UNDEFINED;
}

/* drawSpiderWeb(cx,cy,r,rings,spokes,color) */
static JSValue js_draw_spider_web(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 6) return JS_UNDEFINED;
   int wcx   =(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int wcy   =(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   double wr =double_from_js(ctx,argv[2],40.0);
   int rings =(int)double_from_js(ctx,argv[3],4.0);
   int spokes=(int)double_from_js(ctx,argv[4],8.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   if (rings<1) rings=1; if (spokes<3) spokes=3;
   /* draw spokes */
   for (int s=0;s<spokes;s++){
      double a=s*2.0*M_PI/spokes;
      path_draw_line_segment(wcx,wcy,(int)(wcx+cos(a)*wr),(int)(wcy+sin(a)*wr),col);
   }
   /* draw rings */
   for (int ri=1;ri<=rings;ri++){
      double rr=wr*ri/rings;
      int prevX=(int)(wcx+rr), prevY=wcy;
      for (int s=1;s<=spokes;s++){
         double a=s*2.0*M_PI/spokes;
         int nx2=(int)(wcx+cos(a)*rr), ny2=(int)(wcy+sin(a)*rr);
         path_draw_line_segment(prevX,prevY,nx2,ny2,col);
         prevX=nx2; prevY=ny2;
      }
   }
   return JS_UNDEFINED;
}

/* drawBrickPattern(x,y,w,h,bw,bh,color) */
static JSValue js_draw_brick_pattern(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 7) return JS_UNDEFINED;
   int bx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int by=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int bw=(int)double_from_js(ctx,argv[2],100.0);
   int bh=(int)double_from_js(ctx,argv[3],100.0);
   int tw=(int)double_from_js(ctx,argv[4],20.0);
   int th=(int)double_from_js(ctx,argv[5],10.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[6],0xFFFFFFFFu);
   if (tw<2)tw=2; if (th<2)th=2;
   /* horizontal mortar lines */
   for (int y2=by;y2<by+bh;y2+=th)
      for (int x2=bx;x2<bx+bw;x2++) set_pixel(x2,y2,col);
   /* vertical mortar, offset per row */
   for (int row=0;;row++){
      int y2=by+row*th;
      if (y2>=by+bh) break;
      int offset=(row%2==0)?0:tw/2;
      for (int x2=bx+offset;x2<bx+bw;x2+=tw)
         for (int y3=y2;y3<y2+th&&y3<by+bh;y3++) set_pixel(x2,y3,col);
   }
   return JS_UNDEFINED;
}

/* fillWaveShape(x,y,w,h,amp,freq,color) — wave-topped filled shape */
static JSValue js_fill_wave_shape(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 7) return JS_UNDEFINED;
   int wx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int wy=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int ww=(int)double_from_js(ctx,argv[2],100.0);
   int wh=(int)double_from_js(ctx,argv[3],60.0);
   double wamp =double_from_js(ctx,argv[4],10.0);
   double wfreq=double_from_js(ctx,argv[5],2.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[6],0xFFFFFFFFu);
   for (int x2=wx;x2<wx+ww;x2++){
      double t=(double)(x2-wx)/ww;
      int yTop=wy+(int)(wamp*sin(t*wfreq*2.0*M_PI));
      for (int y2=yTop;y2<wy+wh;y2++) set_pixel(x2,y2,col);
   }
   return JS_UNDEFINED;
}

/* CIE Lab → RGB helper (D65 illuminant) */
static uint32_t lab_to_rgba(double Llab, double astar, double bstar, uint8_t alpha)
{
   /* Lab → XYZ */
   double fy=(Llab+16.0)/116.0;
   double fx=astar/500.0+fy;
   double fz=fy-bstar/200.0;
   double x=(fx*fx*fx>0.008856)?fx*fx*fx:(fx-16.0/116.0)/7.787;
   double y=(fy*fy*fy>0.008856)?fy*fy*fy:(fy-16.0/116.0)/7.787;
   double z=(fz*fz*fz>0.008856)?fz*fz*fz:(fz-16.0/116.0)/7.787;
   /* D65 reference */
   x*=0.95047; z*=1.08883;
   /* XYZ → linear sRGB */
   double rl= 3.2406*x - 1.5372*y - 0.4986*z;
   double gl=-0.9689*x + 1.8758*y + 0.0415*z;
   double bl= 0.0557*x - 0.2040*y + 1.0570*z;
   /* gamma */
#define SRGB(v) ((v)<=0.0031308?12.92*(v):1.055*pow((v),1.0/2.4)-0.055)
   rl=SRGB(rl); gl=SRGB(gl); bl=SRGB(bl);
#undef SRGB
   if(rl<0)rl=0;if(rl>1)rl=1;
   if(gl<0)gl=0;if(gl>1)gl=1;
   if(bl<0)bl=0;if(bl>1)bl=1;
   return ((uint32_t)(rl*255+0.5)<<24)|((uint32_t)(gl*255+0.5)<<16)|((uint32_t)(bl*255+0.5)<<8)|alpha;
}

/* colorFromLab(Llab,alab,blab) → color */
static JSValue js_color_from_lab(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double Lv=argc>0?double_from_js(ctx,argv[0],50.0):50.0;
   double av=argc>1?double_from_js(ctx,argv[1],0.0):0.0;
   double bv=argc>2?double_from_js(ctx,argv[2],0.0):0.0;
   return JS_NewInt32(ctx,(int32_t)lab_to_rgba(Lv,av,bv,255));
}

/* drawFlame(cx,cy,h,color) — flame outline (teardrop) */
static JSValue js_draw_flame(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 4) return JS_UNDEFINED;
   int fcx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int fcy=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int fh =(int)double_from_js(ctx,argv[2],40.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[3],0xFFFFFFFFu);
   int fw=fh/3;
   /* draw outer flame profile using parametric curve */
   int steps=60;
   int prevX=fcx,prevY=fcy;
   for (int i=0;i<=steps;i++){
      double t=(double)i/steps * 2.0 * M_PI;
      /* flame parametric: x = fw*sin(t)*(1-0.4*sin(t/2)), y = -fh*0.5*(1-cos(t)) */
      double xo=(double)fw*sin(t)*(1.0-0.3*sin(t*0.5));
      double yo=-(double)fh*0.5*(1.0-cos(t));
      int px2=fcx+(int)xo, py2=fcy+(int)yo;
      if (i>0) path_draw_line_segment(prevX,prevY,px2,py2,col);
      prevX=px2; prevY=py2;
   }
   return JS_UNDEFINED;
}

/* fillFlame(cx,cy,h,color) — filled flame */
static JSValue js_fill_flame(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 4) return JS_UNDEFINED;
   int fcx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int fcy=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int fh =(int)double_from_js(ctx,argv[2],40.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[3],0xFFFFFFFFu);
   int fw=fh/3;
   for (int y2=fcy-fh;y2<=fcy;y2++){
      double trel=(double)(fcy-y2)/(double)fh; /* 1 at top, 0 at base */
      /* width narrows toward top */
      int xw=(int)(fw*sin(trel*M_PI)*(1.0-0.2*trel));
      for (int x2=fcx-xw;x2<=fcx+xw;x2++) set_pixel(x2,y2,col);
   }
   return JS_UNDEFINED;
}

/* screenZoom(factor,cx,cy) — zoom toward a point */
static JSValue js_screen_zoom(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double factor = argc>0 ? double_from_js(ctx,argv[0],1.2) : 1.2;
   double zcx    = argc>1 ? double_from_js(ctx,argv[1],NOVA64_WIDTH*0.5)  : NOVA64_WIDTH*0.5;
   double zcy    = argc>2 ? double_from_js(ctx,argv[2],NOVA64_HEIGHT*0.5) : NOVA64_HEIGHT*0.5;
   if (factor<=0.01) factor=0.01;

   int cx0=0,cy0=0,cw=NOVA64_WIDTH,ch=NOVA64_HEIGHT;
   if (clip_active){cx0=clip_x;cy0=clip_y;cw=clip_w;ch=clip_h;}
   int x1=cx0,y1=cy0,x2=cx0+cw-1,y2=cy0+ch-1;
   if (x2>=NOVA64_WIDTH) x2=NOVA64_WIDTH-1;
   if (y2>=NOVA64_HEIGHT) y2=NOVA64_HEIGHT-1;
   int W=x2-x1+1,H=y2-y1+1;
   if (W<=0||H<=0) return JS_UNDEFINED;

   uint32_t *src=(uint32_t*)malloc((size_t)(W*H)*sizeof(uint32_t));
   if (!src) return JS_UNDEFINED;
   for (int r=0;r<H;r++)
      for (int c=0;c<W;c++)
         src[r*W+c]=framebuffer[(y1+r)*NOVA64_WIDTH+(x1+c)];

   for (int r=0;r<H;r++){
      for (int c=0;c<W;c++){
         double sx=(c+x1-zcx)/factor+zcx-x1;
         double sy=(r+y1-zcy)/factor+zcy-y1;
         int si=(int)(sx+0.5), sj=(int)(sy+0.5);
         if (si>=0&&si<W&&sj>=0&&sj<H)
            framebuffer[(y1+r)*NOVA64_WIDTH+(x1+c)]=src[sj*W+si];
         else
            framebuffer[(y1+r)*NOVA64_WIDTH+(x1+c)]=0xFF000000u;
      }
   }
   free(src);
   return JS_UNDEFINED;
}

/* drawDotLine(x1,y1,x2,y2,spacing,r,color) — dots along a line */
static JSValue js_draw_dot_line(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 7) return JS_UNDEFINED;
   double dx1=double_from_js(ctx,argv[0],0.0)-(double)cam2d_x;
   double dy1=double_from_js(ctx,argv[1],0.0)-(double)cam2d_y;
   double dx2=double_from_js(ctx,argv[2],100.0)-(double)cam2d_x;
   double dy2=double_from_js(ctx,argv[3],0.0)-(double)cam2d_y;
   int spacing=(int)double_from_js(ctx,argv[4],8.0);
   int dr  =(int)double_from_js(ctx,argv[5],2.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[6],0xFFFFFFFFu);
   if (spacing<1) spacing=1;
   double ddx=dx2-dx1,ddy=dy2-dy1;
   double len=sqrt(ddx*ddx+ddy*ddy);
   if (len<0.5) return JS_UNDEFINED;
   double ux=ddx/len,uy=ddy/len;
   for (double d=0;d<=len;d+=spacing){
      int cx2=(int)(dx1+ux*d), cy2=(int)(dy1+uy*d);
      for (int y2=cy2-dr;y2<=cy2+dr;y2++)
         for (int x2=cx2-dr;x2<=cx2+dr;x2++){
            double dist=sqrt((double)(x2-cx2)*(x2-cx2)+(double)(y2-cy2)*(y2-cy2));
            if (dist<=dr) set_pixel(x2,y2,col);
         }
   }
   return JS_UNDEFINED;
}

/* oscillate(t,freq,lo,hi) — sine oscillation between lo and hi */
static JSValue js_oscillate(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double t  = argc>0 ? double_from_js(ctx,argv[0],0.0) : 0.0;
   double fr = argc>1 ? double_from_js(ctx,argv[1],1.0) : 1.0;
   double lo = argc>2 ? double_from_js(ctx,argv[2],0.0) : 0.0;
   double hi = argc>3 ? double_from_js(ctx,argv[3],1.0) : 1.0;
   double v  = (sin(t*fr*2.0*M_PI)*0.5+0.5)*(hi-lo)+lo;
   return JS_NewFloat64(ctx,v);
}

/* pulseValue(t,period) → t mod period normalized to 0-1 */
static JSValue js_pulse_value(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double t  = argc>0 ? double_from_js(ctx,argv[0],0.0) : 0.0;
   double per= argc>1 ? double_from_js(ctx,argv[1],1.0) : 1.0;
   if (per<=0.0) per=1.0;
   double v=fmod(t,per)/per;
   if (v<0.0) v+=1.0;
   return JS_NewFloat64(ctx,v);
}

/* ── Batch 19: color blends, screen effects, wave draw, bubble, connector ─── */

/* colorLighten(c1,c2) — lighten blend: max per channel */
static JSValue js_color_lighten(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 2) return JS_UNDEFINED;
   uint32_t c1=(uint32_t)color_from_js(ctx,argv[0],0xFF000000u);
   uint32_t c2=(uint32_t)color_from_js(ctx,argv[1],0xFF000000u);
#define MAX_CH(a,b) ((uint32_t)((a)>(b)?(a):(b)))
   uint32_t r=MAX_CH((c1>>24)&0xFF,(c2>>24)&0xFF);
   uint32_t g=MAX_CH((c1>>16)&0xFF,(c2>>16)&0xFF);
   uint32_t b=MAX_CH((c1>> 8)&0xFF,(c2>> 8)&0xFF);
   uint32_t a=(c1)&0xFF;
#undef MAX_CH
   return JS_NewInt32(ctx,(int32_t)((r<<24)|(g<<16)|(b<<8)|a));
}

/* colorDarken(c1,c2) — darken blend: min per channel */
static JSValue js_color_darken(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 2) return JS_UNDEFINED;
   uint32_t c1=(uint32_t)color_from_js(ctx,argv[0],0xFFFFFFFFu);
   uint32_t c2=(uint32_t)color_from_js(ctx,argv[1],0xFFFFFFFFu);
#define MIN_CH(a,b) ((uint32_t)((a)<(b)?(a):(b)))
   uint32_t r=MIN_CH((c1>>24)&0xFF,(c2>>24)&0xFF);
   uint32_t g=MIN_CH((c1>>16)&0xFF,(c2>>16)&0xFF);
   uint32_t b=MIN_CH((c1>> 8)&0xFF,(c2>> 8)&0xFF);
   uint32_t a=(c1)&0xFF;
#undef MIN_CH
   return JS_NewInt32(ctx,(int32_t)((r<<24)|(g<<16)|(b<<8)|a));
}

/* colorDifference(c1,c2) — absolute difference per channel */
static JSValue js_color_difference(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 2) return JS_UNDEFINED;
   uint32_t c1=(uint32_t)color_from_js(ctx,argv[0],0xFF000000u);
   uint32_t c2=(uint32_t)color_from_js(ctx,argv[1],0xFF000000u);
#define DIFF_CH(a,b) ((uint32_t)abs((int)(a)-(int)(b)))
   uint32_t r=DIFF_CH((c1>>24)&0xFF,(c2>>24)&0xFF);
   uint32_t g=DIFF_CH((c1>>16)&0xFF,(c2>>16)&0xFF);
   uint32_t b=DIFF_CH((c1>> 8)&0xFF,(c2>> 8)&0xFF);
   uint32_t a=(c1)&0xFF;
#undef DIFF_CH
   return JS_NewInt32(ctx,(int32_t)((r<<24)|(g<<16)|(b<<8)|a));
}

/* screenBrightnessContrast(brightness, contrast) — adjust levels */
static JSValue js_screen_brightness_contrast(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double bright = argc>0 ? double_from_js(ctx,argv[0],0.0) : 0.0;
   double cont   = argc>1 ? double_from_js(ctx,argv[1],1.0) : 1.0;

   int cx0=0,cy0=0,cw=NOVA64_WIDTH,ch=NOVA64_HEIGHT;
   if (clip_active){cx0=clip_x;cy0=clip_y;cw=clip_w;ch=clip_h;}
   int x1=cx0,y1=cy0,x2=cx0+cw-1,y2=cy0+ch-1;
   if (x2>=NOVA64_WIDTH) x2=NOVA64_WIDTH-1;
   if (y2>=NOVA64_HEIGHT) y2=NOVA64_HEIGHT-1;

   for (int y=y1;y<=y2;y++){
      for (int x=x1;x<=x2;x++){
         uint32_t p=framebuffer[y*NOVA64_WIDTH+x];
         int r=(p>>24)&0xFF,g=(p>>16)&0xFF,b=(p>>8)&0xFF,a=(p)&0xFF;
         /* apply brightness (additive) then contrast (scale around 128) */
         int nr=(int)((r+bright*255-128)*cont+128+0.5);
         int ng=(int)((g+bright*255-128)*cont+128+0.5);
         int nb=(int)((b+bright*255-128)*cont+128+0.5);
         if(nr<0)nr=0;if(nr>255)nr=255;
         if(ng<0)ng=0;if(ng>255)ng=255;
         if(nb<0)nb=0;if(nb>255)nb=255;
         framebuffer[y*NOVA64_WIDTH+x]=((uint32_t)nr<<24)|((uint32_t)ng<<16)|((uint32_t)nb<<8)|(uint32_t)a;
      }
   }
   return JS_UNDEFINED;
}

/* drawSineWave(x,y,w,amp,freq,phase,color) — draw a sine curve */
static JSValue js_draw_sine_wave(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 7) return JS_UNDEFINED;
   int sx   =(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int sy   =(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int sw   =(int)double_from_js(ctx,argv[2],100.0);
   double amp  =double_from_js(ctx,argv[3],20.0);
   double freq =double_from_js(ctx,argv[4],1.0);
   double phase=double_from_js(ctx,argv[5],0.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[6],0xFFFFFFFFu);
   int prevX=sx, prevY=sy;
   for (int i=0;i<=sw;i++){
      double t=(double)i/sw;
      int cx2=sx+i;
      int cy2=sy-(int)(amp*sin(freq*t*2.0*M_PI+phase));
      if (i>0) path_draw_line_segment(prevX,prevY,cx2,cy2,col);
      prevX=cx2; prevY=cy2;
   }
   return JS_UNDEFINED;
}

/* drawSquiggle(x1,y1,x2,y2,amp,freq,color) — perpendicular sine along line */
static JSValue js_draw_squiggle(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 7) return JS_UNDEFINED;
   double qx1=double_from_js(ctx,argv[0],0.0)-(double)cam2d_x;
   double qy1=double_from_js(ctx,argv[1],0.0)-(double)cam2d_y;
   double qx2=double_from_js(ctx,argv[2],100.0)-(double)cam2d_x;
   double qy2=double_from_js(ctx,argv[3],0.0)-(double)cam2d_y;
   double amp =double_from_js(ctx,argv[4],8.0);
   double freq=double_from_js(ctx,argv[5],3.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[6],0xFFFFFFFFu);
   double dx=qx2-qx1,dy=qy2-qy1;
   double len=sqrt(dx*dx+dy*dy);
   if (len<0.5) return JS_UNDEFINED;
   double ux=dx/len,uy=dy/len;
   double nx=-uy,ny=ux;
   int steps=(int)len;
   int prevX=(int)qx1,prevY=(int)qy1;
   for (int i=1;i<=steps;i++){
      double t=(double)i/steps;
      double off=amp*sin(t*freq*2.0*M_PI);
      int cx2=(int)(qx1+ux*len*t+nx*off);
      int cy2=(int)(qy1+uy*len*t+ny*off);
      path_draw_line_segment(prevX,prevY,cx2,cy2,col);
      prevX=cx2; prevY=cy2;
   }
   return JS_UNDEFINED;
}

/* screenGlitch(amount) — RGB channel displacement */
static JSValue js_screen_glitch(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int amt=(int)(argc>0?double_from_js(ctx,argv[0],4.0):4.0);
   if (amt<1) amt=1; if (amt>20) amt=20;

   int cx0=0,cy0=0,cw=NOVA64_WIDTH,ch=NOVA64_HEIGHT;
   if (clip_active){cx0=clip_x;cy0=clip_y;cw=clip_w;ch=clip_h;}
   int x1=cx0,y1=cy0,x2=cx0+cw-1,y2=cy0+ch-1;
   if (x2>=NOVA64_WIDTH) x2=NOVA64_WIDTH-1;
   if (y2>=NOVA64_HEIGHT) y2=NOVA64_HEIGHT-1;
   int W=x2-x1+1,H=y2-y1+1;
   if (W<=0||H<=0) return JS_UNDEFINED;

   uint32_t *src=(uint32_t*)malloc((size_t)(W*H)*sizeof(uint32_t));
   if (!src) return JS_UNDEFINED;
   for (int r=0;r<H;r++)
      for (int c=0;c<W;c++)
         src[r*W+c]=framebuffer[(y1+r)*NOVA64_WIDTH+(x1+c)];

   for (int r=0;r<H;r++){
      int shift=((r*7+13)%17<9)?amt:0;
      for (int c=0;c<W;c++){
         int rc=c-shift; if(rc<0)rc=0; if(rc>=W)rc=W-1;
         int gc=c;
         int bc=c+shift; if(bc>=W)bc=W-1;
         uint32_t rp=src[r*W+rc], gp=src[r*W+gc], bp=src[r*W+bc];
         uint32_t rch=(rp>>24)&0xFF, gch=(gp>>16)&0xFF, bch=(bp>>8)&0xFF;
         uint32_t ach=(src[r*W+c])&0xFF;
         framebuffer[(y1+r)*NOVA64_WIDTH+(x1+c)]=(rch<<24)|(gch<<16)|(bch<<8)|ach;
      }
   }
   free(src);
   return JS_UNDEFINED;
}

/* drawBubble(cx,cy,r,color) — bubble outline with highlight arc */
static JSValue js_draw_bubble(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 4) return JS_UNDEFINED;
   int bcx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int bcy=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int br =(int)double_from_js(ctx,argv[2],20.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[3],0xFFFFFFFFu);
   /* draw main circle */
   for (int y2=bcy-br;y2<=bcy+br;y2++){
      for (int x2=bcx-br;x2<=bcx+br;x2++){
         double dist=sqrt((double)(x2-bcx)*(x2-bcx)+(double)(y2-bcy)*(y2-bcy));
         if (dist>br-1&&dist<=br) set_pixel(x2,y2,col);
      }
   }
   /* specular arc highlight (upper-left) */
   uint32_t hl=(col&0xFFFFFF00u)|((col&0xFF)+40>255?255:(col&0xFF)+40);
   int hr=(int)(br*0.45), hcx=bcx-(int)(br*0.3), hcy=bcy-(int)(br*0.3);
   for (int y2=hcy-hr;y2<=hcy+hr;y2++){
      for (int x2=hcx-hr;x2<=hcx+hr;x2++){
         double d=sqrt((double)(x2-hcx)*(x2-hcx)+(double)(y2-hcy)*(y2-hcy));
         if (d>hr-1&&d<=hr) set_pixel(x2,y2,hl);
      }
   }
   return JS_UNDEFINED;
}

/* fillBubble(cx,cy,r,color) — filled bubble with radial gradient */
static JSValue js_fill_bubble(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 4) return JS_UNDEFINED;
   int bcx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int bcy=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int br =(int)double_from_js(ctx,argv[2],20.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[3],0xFFFFFFFFu);
   uint32_t ri=(col>>24)&0xFF, gi=(col>>16)&0xFF, bi=(col>>8)&0xFF, ai=(col)&0xFF;
   for (int y2=bcy-br;y2<=bcy+br;y2++){
      for (int x2=bcx-br;x2<=bcx+br;x2++){
         double dist=sqrt((double)(x2-bcx)*(x2-bcx)+(double)(y2-bcy)*(y2-bcy));
         if (dist>br) continue;
         double t=dist/br;
         uint32_t nr=(uint32_t)(ri*(1.0-t*0.3)+0.5);
         uint32_t ng=(uint32_t)(gi*(1.0-t*0.3)+0.5);
         uint32_t nb=(uint32_t)(bi*(1.0-t*0.3)+255*t*0.1+0.5);
         if(nr>255)nr=255;if(ng>255)ng=255;if(nb>255)nb=255;
         set_pixel(x2,y2,(nr<<24)|(ng<<16)|(nb<<8)|ai);
      }
   }
   /* specular dot */
   int hx=bcx-(int)(br*0.3), hy=bcy-(int)(br*0.3), hr=(int)(br*0.25);
   for (int y2=hy-hr;y2<=hy+hr;y2++)
      for (int x2=hx-hr;x2<=hx+hr;x2++){
         double d=sqrt((double)(x2-hx)*(x2-hx)+(double)(y2-hy)*(y2-hy));
         if (d<=hr) set_pixel(x2,y2,rgba8(255,255,255,(uint8_t)(200*(1.0-d/hr))));
      }
   return JS_UNDEFINED;
}

/* colorPinLight(c1,c2) — pin light blend */
static JSValue js_color_pin_light(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 2) return JS_UNDEFINED;
   uint32_t c1=(uint32_t)color_from_js(ctx,argv[0],0xFF000000u);
   uint32_t c2=(uint32_t)color_from_js(ctx,argv[1],0xFF000000u);
#define PIN(a,b) ((int)(b)<128 ? ((int)(a)<2*(int)(b)?(int)(a):2*(int)(b)) : ((int)(a)>2*(int)(b)-255?(int)(a):2*(int)(b)-255))
   uint32_t r=(uint32_t)PIN((c1>>24)&0xFF,(c2>>24)&0xFF);
   uint32_t g=(uint32_t)PIN((c1>>16)&0xFF,(c2>>16)&0xFF);
   uint32_t b=(uint32_t)PIN((c1>> 8)&0xFF,(c2>> 8)&0xFF);
   uint32_t a=(c1)&0xFF;
#undef PIN
   if(r>255)r=255; if(g>255)g=255; if(b>255)b=255;
   return JS_NewInt32(ctx,(int32_t)((r<<24)|(g<<16)|(b<<8)|a));
}

/* drawConnector(x1,y1,x2,y2,color) — smooth S-curve connector */
static JSValue js_draw_connector(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 5) return JS_UNDEFINED;
   double nx1=double_from_js(ctx,argv[0],0.0)-(double)cam2d_x;
   double ny1=double_from_js(ctx,argv[1],0.0)-(double)cam2d_y;
   double nx2=double_from_js(ctx,argv[2],100.0)-(double)cam2d_x;
   double ny2=double_from_js(ctx,argv[3],0.0)-(double)cam2d_y;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[4],0xFFFFFFFFu);
   /* cubic bezier with horizontal tangents */
   double cx1=nx1+(nx2-nx1)*0.5, cy1=ny1;
   double cx2=nx1+(nx2-nx1)*0.5, cy2=ny2;
   int steps=80;
   int prevX=(int)nx1,prevY=(int)ny1;
   for (int i=1;i<=steps;i++){
      double t=(double)i/steps, it=1.0-t;
      double bx=it*it*it*nx1+3*it*it*t*cx1+3*it*t*t*cx2+t*t*t*nx2;
      double by=it*it*it*ny1+3*it*it*t*cy1+3*it*t*t*cy2+t*t*t*ny2;
      path_draw_line_segment(prevX,prevY,(int)bx,(int)by,col);
      prevX=(int)bx; prevY=(int)by;
   }
   return JS_UNDEFINED;
}

/* drawHatch(x,y,w,h,angle,spacing,color) — hatching over a rect */
static JSValue js_draw_hatch(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 7) return JS_UNDEFINED;
   int hx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int hy=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   int hw=(int)double_from_js(ctx,argv[2],100.0);
   int hh=(int)double_from_js(ctx,argv[3],100.0);
   double ang  =double_from_js(ctx,argv[4],45.0)*M_PI/180.0;
   int spacing =(int)double_from_js(ctx,argv[5],8.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[6],0xFFFFFFFFu);
   if (spacing<1) spacing=1;
   double ca=cos(ang), sa=sin(ang);
   int diag=(int)sqrt((double)(hw*hw+hh*hh))+spacing;
   for (int d=-diag; d<=diag+hw+hh; d+=spacing){
      /* line in direction (ca,sa) passing through (hx+d*(-sa), hy+d*ca) */
      double ox=hx+d*(-sa), oy=hy+d*ca;
      int lx1=(int)(ox - ca*diag), ly1=(int)(oy - sa*diag);
      int lx2=(int)(ox + ca*diag), ly2=(int)(oy + sa*diag);
      /* clip to rect and draw */
      for (int s=0; s<=diag*2; s++){
         double t=(double)s/(diag*2);
         int px2=(int)(lx1+(lx2-lx1)*t);
         int py2=(int)(ly1+(ly2-ly1)*t);
         if (px2>=hx&&px2<hx+hw&&py2>=hy&&py2<hy+hh)
            set_pixel(px2,py2,col);
      }
   }
   return JS_UNDEFINED;
}

/* ── Batch 18: vector utils, color blends, trail, gradients, gear, CRT ─── */

/* vecFromAngle(degrees) → {x,y} unit vector */
static JSValue js_vec_from_angle(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double deg = argc>0 ? double_from_js(ctx,argv[0],0.0) : 0.0;
   double rad = deg * M_PI / 180.0;
   JSValue obj = JS_NewObject(ctx);
   JS_SetPropertyStr(ctx, obj, "x", JS_NewFloat64(ctx, cos(rad)));
   JS_SetPropertyStr(ctx, obj, "y", JS_NewFloat64(ctx, sin(rad)));
   return obj;
}

/* closestPointOnLine(px,py,x1,y1,x2,y2) → {x,y} nearest point on segment */
static JSValue js_closest_point_on_line(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 6) return JS_UNDEFINED;
   double px=double_from_js(ctx,argv[0],0.0), py=double_from_js(ctx,argv[1],0.0);
   double x1=double_from_js(ctx,argv[2],0.0), y1=double_from_js(ctx,argv[3],0.0);
   double x2=double_from_js(ctx,argv[4],0.0), y2=double_from_js(ctx,argv[5],0.0);
   double dx=x2-x1, dy=y2-y1;
   double lenSq=dx*dx+dy*dy;
   double rx=x1, ry=y1;
   if (lenSq > 1e-12) {
      double t=((px-x1)*dx+(py-y1)*dy)/lenSq;
      if (t<0.0) t=0.0; if (t>1.0) t=1.0;
      rx=x1+t*dx; ry=y1+t*dy;
   }
   JSValue obj=JS_NewObject(ctx);
   JS_SetPropertyStr(ctx,obj,"x",JS_NewFloat64(ctx,rx));
   JS_SetPropertyStr(ctx,obj,"y",JS_NewFloat64(ctx,ry));
   return obj;
}

/* distToLine(px,py,x1,y1,x2,y2) → distance from point to segment */
static JSValue js_dist_to_line(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 6) return JS_NewFloat64(ctx,0.0);
   double px=double_from_js(ctx,argv[0],0.0), py=double_from_js(ctx,argv[1],0.0);
   double x1=double_from_js(ctx,argv[2],0.0), y1=double_from_js(ctx,argv[3],0.0);
   double x2=double_from_js(ctx,argv[4],0.0), y2=double_from_js(ctx,argv[5],0.0);
   double dx=x2-x1, dy=y2-y1;
   double lenSq=dx*dx+dy*dy;
   double cx=x1,cy=y1;
   if (lenSq > 1e-12) {
      double t=((px-x1)*dx+(py-y1)*dy)/lenSq;
      if (t<0.0) t=0.0; if (t>1.0) t=1.0;
      cx=x1+t*dx; cy=y1+t*dy;
   }
   double ex=px-cx, ey=py-cy;
   return JS_NewFloat64(ctx, sqrt(ex*ex+ey*ey));
}

/* drawTrail(x1,y1,x2,y2,w1,w2,color) — tapered line (filled trapezoid) */
static JSValue js_draw_trail(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 7) return JS_UNDEFINED;
   float fx1=(float)double_from_js(ctx,argv[0],0.0)-(float)cam2d_x;
   float fy1=(float)double_from_js(ctx,argv[1],0.0)-(float)cam2d_y;
   float fx2=(float)double_from_js(ctx,argv[2],0.0)-(float)cam2d_x;
   float fy2=(float)double_from_js(ctx,argv[3],0.0)-(float)cam2d_y;
   float w1 =(float)double_from_js(ctx,argv[4],4.0)*0.5f;
   float w2 =(float)double_from_js(ctx,argv[5],1.0)*0.5f;
   uint32_t col=(uint32_t)color_from_js(ctx,argv[6],0xFFFFFFFFu);
   float dx=fx2-fx1, dy=fy2-fy1;
   float len=sqrtf(dx*dx+dy*dy);
   if (len<0.5f) return JS_UNDEFINED;
   float nx=-dy/len, ny=dx/len;
   /* render as quads along line using scanline fill */
   /* 4 corners of trapezoid */
   float ax=fx1+nx*w1, ay=fy1+ny*w1;
   float bx=fx1-nx*w1, by=fy1-ny*w1;
   float cx2=fx2+nx*w2, cy2=fy2+ny*w2;
   float dx2=fx2-nx*w2, dy2=fy2-ny*w2;
   /* draw as two triangles */
   /* triangle 1: a, b, c */
   int minY=(int)fminf(fminf(ay,by),fminf(cy2,dy2));
   int maxY=(int)fmaxf(fmaxf(ay,by),fmaxf(cy2,dy2));
   for (int y=minY; y<=maxY; y++) {
      /* for each y, find x extents via edge intersections */
      float xmin=1e9f, xmax=-1e9f;
      float edges[4][4]={{ax,ay,cx2,cy2},{ax,ay,bx,by},{bx,by,dx2,dy2},{cx2,cy2,dx2,dy2}};
      for (int e=0;e<4;e++) {
         float ey0=edges[e][1], ey1=edges[e][3];
         if ((ey0<=y&&y<=ey1)||(ey1<=y&&y<=ey0)) {
            float t=(ey0==ey1)?0.0f:(float)(y-ey0)/(ey1-ey0);
            float xi=edges[e][0]+(edges[e][2]-edges[e][0])*t;
            if (xi<xmin) xmin=xi;
            if (xi>xmax) xmax=xi;
         }
      }
      for (int x=(int)xmin; x<=(int)xmax; x++) set_pixel(x,y,col);
   }
   return JS_UNDEFINED;
}

/* colorDodge(c1,c2) — color dodge blend */
static JSValue js_color_dodge(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 2) return JS_UNDEFINED;
   uint32_t c1=(uint32_t)color_from_js(ctx,argv[0],0xFF000000u);
   uint32_t c2=(uint32_t)color_from_js(ctx,argv[1],0xFF000000u);
#define DODGE(a,b) ((int)(b)==255 ? 255 : (int)fmin(255.0,(int)(a)*255/(255-(int)(b))))
   uint32_t r=(uint32_t)DODGE((c1>>24)&0xFF,(c2>>24)&0xFF);
   uint32_t g=(uint32_t)DODGE((c1>>16)&0xFF,(c2>>16)&0xFF);
   uint32_t b=(uint32_t)DODGE((c1>> 8)&0xFF,(c2>> 8)&0xFF);
   uint32_t a=(c1)&0xFF;
#undef DODGE
   return JS_NewInt32(ctx,(int32_t)((r<<24)|(g<<16)|(b<<8)|a));
}

/* colorBurn(c1,c2) — color burn blend */
static JSValue js_color_burn(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 2) return JS_UNDEFINED;
   uint32_t c1=(uint32_t)color_from_js(ctx,argv[0],0xFF000000u);
   uint32_t c2=(uint32_t)color_from_js(ctx,argv[1],0xFF000000u);
#define BURN(a,b) ((int)(b)==0 ? 0 : (int)fmax(0.0,255-(255-(int)(a))*255/(int)(b)))
   uint32_t r=(uint32_t)BURN((c1>>24)&0xFF,(c2>>24)&0xFF);
   uint32_t g=(uint32_t)BURN((c1>>16)&0xFF,(c2>>16)&0xFF);
   uint32_t b=(uint32_t)BURN((c1>> 8)&0xFF,(c2>> 8)&0xFF);
   uint32_t a=(c1)&0xFF;
#undef BURN
   return JS_NewInt32(ctx,(int32_t)((r<<24)|(g<<16)|(b<<8)|a));
}

/* fillRadialGradient(cx,cy,r,c1,c2) — radial gradient from center to edge */
static JSValue js_fill_radial_gradient(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 5) return JS_UNDEFINED;
   int rcx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int rcy=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   double rad=double_from_js(ctx,argv[2],50.0);
   uint32_t col1=(uint32_t)color_from_js(ctx,argv[3],0xFFFFFFFFu);
   uint32_t col2=(uint32_t)color_from_js(ctx,argv[4],0x00000000u);
   int ir=(int)rad+1;
   for (int y=rcy-ir;y<=rcy+ir;y++){
      for (int x=rcx-ir;x<=rcx+ir;x++){
         double dist=sqrt((double)(x-rcx)*(x-rcx)+(double)(y-rcy)*(y-rcy));
         if (dist>rad) continue;
         double t=dist/rad;
         double it=1.0-t;
         uint32_t r=(uint32_t)((col1>>24&0xFF)*it+(col2>>24&0xFF)*t);
         uint32_t g=(uint32_t)((col1>>16&0xFF)*it+(col2>>16&0xFF)*t);
         uint32_t b=(uint32_t)((col1>> 8&0xFF)*it+(col2>> 8&0xFF)*t);
         uint32_t a=(uint32_t)((col1    &0xFF)*it+(col2    &0xFF)*t);
         set_pixel(x,y,(r<<24)|(g<<16)|(b<<8)|a);
      }
   }
   return JS_UNDEFINED;
}

/* screenCRTWarp(strength) — barrel lens distortion */
static JSValue js_screen_crt_warp(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double k = argc>0 ? double_from_js(ctx,argv[0],0.3) : 0.3;

   int cx0=0,cy0=0,cw=NOVA64_WIDTH,ch=NOVA64_HEIGHT;
   if (clip_active){cx0=clip_x;cy0=clip_y;cw=clip_w;ch=clip_h;}
   int x1=cx0,y1=cy0,x2=cx0+cw-1,y2=cy0+ch-1;
   if (x2>=NOVA64_WIDTH) x2=NOVA64_WIDTH-1;
   if (y2>=NOVA64_HEIGHT) y2=NOVA64_HEIGHT-1;
   int W=x2-x1+1,H=y2-y1+1;
   if (W<=0||H<=0) return JS_UNDEFINED;

   uint32_t *tmp=(uint32_t*)malloc((size_t)(W*H)*sizeof(uint32_t));
   if (!tmp) return JS_UNDEFINED;
   for (int r=0;r<H;r++)
      for (int c=0;c<W;c++)
         tmp[r*W+c]=framebuffer[(y1+r)*NOVA64_WIDTH+(x1+c)];

   double hw=W*0.5, hh=H*0.5;
   for (int r=0;r<H;r++){
      for (int c=0;c<W;c++){
         double nx2=(c-hw)/hw, ny2=(r-hh)/hh;
         double r2=nx2*nx2+ny2*ny2;
         double scale=1.0+k*r2;
         double sx=(nx2*scale)*hw+hw;
         double sy=(ny2*scale)*hh+hh;
         int si=(int)sx,sj=(int)sy;
         if (si>=0&&si<W&&sj>=0&&sj<H)
            framebuffer[(y1+r)*NOVA64_WIDTH+(x1+c)]=tmp[sj*W+si];
         else
            framebuffer[(y1+r)*NOVA64_WIDTH+(x1+c)]=0x00000000u;
      }
   }
   free(tmp);
   return JS_UNDEFINED;
}

/* screenOilPaint(radius) — Kuwahara-style painterly effect */
static JSValue js_screen_oil_paint(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int radius=(int)(argc>0?double_from_js(ctx,argv[0],2.0):2.0);
   if (radius<1) radius=1; if (radius>6) radius=6;

   int cx0=0,cy0=0,cw=NOVA64_WIDTH,ch=NOVA64_HEIGHT;
   if (clip_active){cx0=clip_x;cy0=clip_y;cw=clip_w;ch=clip_h;}
   int x1=cx0,y1=cy0,x2=cx0+cw-1,y2=cy0+ch-1;
   if (x2>=NOVA64_WIDTH) x2=NOVA64_WIDTH-1;
   if (y2>=NOVA64_HEIGHT) y2=NOVA64_HEIGHT-1;
   int W=x2-x1+1,H=y2-y1+1;
   if (W<=0||H<=0) return JS_UNDEFINED;

   uint32_t *src=(uint32_t*)malloc((size_t)(W*H)*sizeof(uint32_t));
   if (!src) return JS_UNDEFINED;
   for (int r=0;r<H;r++)
      for (int c=0;c<W;c++)
         src[r*W+c]=framebuffer[(y1+r)*NOVA64_WIDTH+(x1+c)];

   /* 4 quadrant Kuwahara */
   for (int r=0;r<H;r++){
      for (int c=0;c<W;c++){
         double bestVar=1e18; uint32_t bestColor=src[r*W+c];
         int qx[4]={0,-radius,0,-radius}, qy[4]={0,0,-radius,-radius};
         for (int q=0;q<4;q++){
            long sumR=0,sumG=0,sumB=0; int cnt=0;
            for (int dy=qy[q];dy<=qy[q]+radius;dy++)
               for (int dx=qx[q];dx<=qx[q]+radius;dx++){
                  int sr=r+dy,sc=c+dx;
                  if (sr<0||sr>=H||sc<0||sc>=W) continue;
                  uint32_t p=src[sr*W+sc];
                  sumR+=(p>>24)&0xFF; sumG+=(p>>16)&0xFF; sumB+=(p>>8)&0xFF; cnt++;
               }
            if (!cnt) continue;
            double mr=sumR/cnt, mg=sumG/cnt, mb=sumB/cnt;
            double var=0;
            for (int dy=qy[q];dy<=qy[q]+radius;dy++)
               for (int dx=qx[q];dx<=qx[q]+radius;dx++){
                  int sr=r+dy,sc=c+dx;
                  if (sr<0||sr>=H||sc<0||sc>=W) continue;
                  uint32_t p=src[sr*W+sc];
                  double dr=((p>>24)&0xFF)-mr;
                  double dg=((p>>16)&0xFF)-mg;
                  double db=((p>> 8)&0xFF)-mb;
                  var+=dr*dr+dg*dg+db*db;
               }
            if (var<bestVar){
               bestVar=var;
               bestColor=((uint32_t)(mr+0.5)<<24)|((uint32_t)(mg+0.5)<<16)|((uint32_t)(mb+0.5)<<8)|(src[r*W+c]&0xFF);
            }
         }
         framebuffer[(y1+r)*NOVA64_WIDTH+(x1+c)]=bestColor;
      }
   }
   free(src);
   return JS_UNDEFINED;
}

/* drawGear(cx,cy,r,teeth,toothH,color) — gear outline */
static JSValue js_draw_gear(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 6) return JS_UNDEFINED;
   int gcx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int gcy=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   double gr   =double_from_js(ctx,argv[2],30.0);
   int    teeth=(int)double_from_js(ctx,argv[3],8.0);
   double toothH=double_from_js(ctx,argv[4],6.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   if (teeth<4) teeth=4;
   int segs=teeth*4;
   double outerR=gr+toothH, innerR=gr;
   int prevX=0,prevY=0;
   for (int i=0;i<=segs;i++){
      double a=i*2.0*M_PI/segs;
      int qi=i%4;
      double r2=(qi==1||qi==2)?outerR:innerR;
      int nx2=(int)(gcx+cos(a)*r2), ny2=(int)(gcy+sin(a)*r2);
      if (i>0) path_draw_line_segment(prevX,prevY,nx2,ny2,col);
      prevX=nx2; prevY=ny2;
   }
   return JS_UNDEFINED;
}

/* fillGear(cx,cy,r,teeth,toothH,color) — filled gear */
static JSValue js_fill_gear(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 6) return JS_UNDEFINED;
   int gcx=(int)double_from_js(ctx,argv[0],0.0)-(int)cam2d_x;
   int gcy=(int)double_from_js(ctx,argv[1],0.0)-(int)cam2d_y;
   double gr   =double_from_js(ctx,argv[2],30.0);
   int    teeth=(int)double_from_js(ctx,argv[3],8.0);
   double toothH=double_from_js(ctx,argv[4],6.0);
   uint32_t col=(uint32_t)color_from_js(ctx,argv[5],0xFFFFFFFFu);
   if (teeth<4) teeth=4;
   double outerR=gr+toothH;
   int maxR=(int)(outerR+2);
   for (int py=gcy-maxR;py<=gcy+maxR;py++){
      for (int px=gcx-maxR;px<=gcx+maxR;px++){
         double dx=(double)(px-gcx), dy=(double)(py-gcy);
         double dist=sqrt(dx*dx+dy*dy);
         if (dist>outerR+1.0) continue;
         if (dist<gr){set_pixel(px,py,col);continue;}
         /* check if in a tooth */
         double angle=atan2(dy,dx);
         if (angle<0) angle+=2.0*M_PI;
         double toothAngle=fmod(angle,2.0*M_PI/teeth)*teeth/(2.0*M_PI);
         /* toothAngle in [0,1] per tooth; tooth occupies [0.25,0.75] */
         if (toothAngle>=0.25&&toothAngle<=0.75&&dist<=outerR)
            set_pixel(px,py,col);
      }
   }
   return JS_UNDEFINED;
}

/* colorFromFloats(r,g,b,a) — create color from 0.0-1.0 float components */
static JSValue js_color_from_floats(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   double r=argc>0?double_from_js(ctx,argv[0],0.0):0.0;
   double g=argc>1?double_from_js(ctx,argv[1],0.0):0.0;
   double b=argc>2?double_from_js(ctx,argv[2],0.0):0.0;
   double a=argc>3?double_from_js(ctx,argv[3],1.0):1.0;
   if(r<0)r=0;if(r>1)r=1; if(g<0)g=0;if(g>1)g=1;
   if(b<0)b=0;if(b>1)b=1; if(a<0)a=0;if(a>1)a=1;
   uint32_t ri=(uint32_t)(r*255+0.5), gi=(uint32_t)(g*255+0.5);
   uint32_t bi=(uint32_t)(b*255+0.5), ai=(uint32_t)(a*255+0.5);
   return JS_NewInt32(ctx,(int32_t)((ri<<24)|(gi<<16)|(bi<<8)|ai));
}

/* ── Batch 17: vector math, color blends, trig helpers, glow, ruler ─── */

/* reflectVector(vx,vy,nx,ny) → {x,y} — reflect v off unit normal n */
static JSValue js_reflect_vector(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 4) return JS_UNDEFINED;
   double vx   = double_from_js(ctx,argv[0],0.0);
   double vy   = double_from_js(ctx,argv[1],0.0);
   double nx   = double_from_js(ctx,argv[2],0.0);
   double ny   = double_from_js(ctx,argv[3],1.0);
   double dot2 = 2.0*(vx*nx + vy*ny);
   JSValue obj = JS_NewObject(ctx);
   JS_SetPropertyStr(ctx, obj, "x", JS_NewFloat64(ctx, vx - dot2*nx));
   JS_SetPropertyStr(ctx, obj, "y", JS_NewFloat64(ctx, vy - dot2*ny));
   return obj;
}

/* rotateVector(vx,vy,angle) → {x,y} — rotate by degrees */
static JSValue js_rotate_vector(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 3) return JS_UNDEFINED;
   double vx  = double_from_js(ctx,argv[0],0.0);
   double vy  = double_from_js(ctx,argv[1],0.0);
   double deg = double_from_js(ctx,argv[2],0.0);
   double rad = deg * M_PI / 180.0;
   double c   = cos(rad), s = sin(rad);
   JSValue obj = JS_NewObject(ctx);
   JS_SetPropertyStr(ctx, obj, "x", JS_NewFloat64(ctx, vx*c - vy*s));
   JS_SetPropertyStr(ctx, obj, "y", JS_NewFloat64(ctx, vx*s + vy*c));
   return obj;
}

/* colorMultiply(c1,c2) — multiply blend */
static JSValue js_color_multiply(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 2) return JS_UNDEFINED;
   uint32_t c1 = (uint32_t)color_from_js(ctx,argv[0],0xFF000000u);
   uint32_t c2 = (uint32_t)color_from_js(ctx,argv[1],0xFF000000u);
   uint32_t r  = ((c1>>24)&0xFF)*((c2>>24)&0xFF)/255;
   uint32_t g  = ((c1>>16)&0xFF)*((c2>>16)&0xFF)/255;
   uint32_t b  = ((c1>> 8)&0xFF)*((c2>> 8)&0xFF)/255;
   uint32_t a  = ((c1    )&0xFF)*((c2    )&0xFF)/255;
   return JS_NewInt32(ctx, (int32_t)((r<<24)|(g<<16)|(b<<8)|a));
}

/* colorScreen(c1,c2) — screen blend */
static JSValue js_color_screen(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 2) return JS_UNDEFINED;
   uint32_t c1 = (uint32_t)color_from_js(ctx,argv[0],0xFF000000u);
   uint32_t c2 = (uint32_t)color_from_js(ctx,argv[1],0xFF000000u);
#define SCR(a,b) (255-(255-(int)(a))*(255-(int)(b))/255)
   uint32_t r = (uint32_t)SCR((c1>>24)&0xFF,(c2>>24)&0xFF);
   uint32_t g = (uint32_t)SCR((c1>>16)&0xFF,(c2>>16)&0xFF);
   uint32_t b = (uint32_t)SCR((c1>> 8)&0xFF,(c2>> 8)&0xFF);
   uint32_t a = (uint32_t)SCR((c1    )&0xFF,(c2    )&0xFF);
#undef SCR
   return JS_NewInt32(ctx, (int32_t)((r<<24)|(g<<16)|(b<<8)|a));
}

/* colorOverlay(c1,c2) — overlay blend */
static JSValue js_color_overlay(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   if (argc < 2) return JS_UNDEFINED;
   uint32_t c1 = (uint32_t)color_from_js(ctx,argv[0],0xFF000000u);
   uint32_t c2 = (uint32_t)color_from_js(ctx,argv[1],0xFF000000u);
#define OVL(a,b) ((int)(a)<128 ? 2*(int)(a)*(int)(b)/255 : 255-2*(255-(int)(a))*(255-(int)(b))/255)
   uint32_t r = (uint32_t)OVL((c1>>24)&0xFF,(c2>>24)&0xFF);
   uint32_t g = (uint32_t)OVL((c1>>16)&0xFF,(c2>>16)&0xFF);
   uint32_t b = (uint32_t)OVL((c1>> 8)&0xFF,(c2>> 8)&0xFF);
   uint32_t a = (c1)&0xFF;
#undef OVL
   return JS_NewInt32(ctx, (int32_t)((r<<24)|(g<<16)|(b<<8)|a));
}

