static bool core_perf_enabled(void)
{
   /* Always-on when the in-game FPS overlay is showing so the overlay can
      surface per-stage timings without needing the env var or log fishing. */
   if (g_fps_overlay_enabled)
      return true;
   const char *enabled = getenv("NOVA64_PERF");
   return enabled && enabled[0] && strcmp(enabled, "0");
}

/* Snapshot of the most-recent 60-frame averages, written by
   core_perf_record_frame and read by the FPS overlay so it can show
   per-stage breakdowns live. Updated once every 60 frames (~1 s at 60 fps). */
static float g_fps_avg_cart_ms          = 0.0f;
static float g_fps_avg_render_ms        = 0.0f;
static float g_fps_avg_frame_ms         = 0.0f;
static float g_fps_avg_post_ms          = 0.0f;
static float g_fps_avg_overlay_total_ms = 0.0f;
static unsigned g_fps_avg_draw_calls    = 0;

static uint64_t core_perf_now_us(void)
{
#ifdef _WIN32
   static LARGE_INTEGER frequency;
   static bool frequency_ready = false;
   LARGE_INTEGER counter;
   if (!frequency_ready) {
      QueryPerformanceFrequency(&frequency);
      frequency_ready = true;
   }
   QueryPerformanceCounter(&counter);
   return (uint64_t)((counter.QuadPart * 1000000ULL) / (uint64_t)frequency.QuadPart);
#else
   struct timespec ts;
   clock_gettime(CLOCK_MONOTONIC, &ts);
   return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)(ts.tv_nsec / 1000ULL);
#endif
}

static void core_perf_begin_frame(void)
{
   core_perf_frame_instance_transform_calls = 0;
   core_perf_frame_draw_calls = 0;
   core_perf_frame_overlay_uploads = 0;
   core_perf_frame_post_us = 0;
   core_perf_frame_overlay_convert_us = 0;
   core_perf_frame_overlay_upload_us = 0;
   core_perf_frame_overlay_draw_us = 0;
}

static void core_perf_record_frame(uint64_t cart_us, uint64_t render_us, uint64_t frame_us)
{
   if (!core_perf_enabled())
      return;

   core_perf.interval_frames++;
   core_perf.cart_total_us += cart_us;
   core_perf.render_total_us += render_us;
   core_perf.frame_total_us += frame_us;
   if (cart_us > core_perf.cart_max_us)
      core_perf.cart_max_us = cart_us;
   if (render_us > core_perf.render_max_us)
      core_perf.render_max_us = render_us;
   if (frame_us > core_perf.frame_max_us)
      core_perf.frame_max_us = frame_us;
   core_perf.post_total_us += core_perf_frame_post_us;
   if (core_perf_frame_post_us > core_perf.post_max_us)
      core_perf.post_max_us = core_perf_frame_post_us;
   core_perf.overlay_convert_total_us += core_perf_frame_overlay_convert_us;
   if (core_perf_frame_overlay_convert_us > core_perf.overlay_convert_max_us)
      core_perf.overlay_convert_max_us = core_perf_frame_overlay_convert_us;
   core_perf.overlay_upload_total_us += core_perf_frame_overlay_upload_us;
   if (core_perf_frame_overlay_upload_us > core_perf.overlay_upload_max_us)
      core_perf.overlay_upload_max_us = core_perf_frame_overlay_upload_us;
   core_perf.overlay_draw_total_us += core_perf_frame_overlay_draw_us;
   if (core_perf_frame_overlay_draw_us > core_perf.overlay_draw_max_us)
      core_perf.overlay_draw_max_us = core_perf_frame_overlay_draw_us;
   core_perf.instance_transform_calls += core_perf_frame_instance_transform_calls;
   core_perf.draw_calls += core_perf_frame_draw_calls;
   core_perf.overlay_uploads += core_perf_frame_overlay_uploads;

   if (core_perf.interval_frames >= 60) {
      unsigned frames = core_perf.interval_frames;
      char message[768];
      snprintf(message, sizeof(message),
         "[nova64-perf] frames=%u cart_us avg=%llu max=%llu render_us avg=%llu max=%llu frame_us avg=%llu max=%llu post_us avg=%llu max=%llu overlay_convert_us avg=%llu max=%llu overlay_upload_us avg=%llu max=%llu overlay_draw_us avg=%llu max=%llu inst_xform/frame=%llu draw_calls/frame=%llu overlay_uploads/frame=%llu",
         frames,
         (unsigned long long)(core_perf.cart_total_us / frames),
         (unsigned long long)core_perf.cart_max_us,
         (unsigned long long)(core_perf.render_total_us / frames),
         (unsigned long long)core_perf.render_max_us,
         (unsigned long long)(core_perf.frame_total_us / frames),
         (unsigned long long)core_perf.frame_max_us,
         (unsigned long long)(core_perf.post_total_us / frames),
         (unsigned long long)core_perf.post_max_us,
         (unsigned long long)(core_perf.overlay_convert_total_us / frames),
         (unsigned long long)core_perf.overlay_convert_max_us,
         (unsigned long long)(core_perf.overlay_upload_total_us / frames),
         (unsigned long long)core_perf.overlay_upload_max_us,
         (unsigned long long)(core_perf.overlay_draw_total_us / frames),
         (unsigned long long)core_perf.overlay_draw_max_us,
         (unsigned long long)(core_perf.instance_transform_calls / frames),
         (unsigned long long)(core_perf.draw_calls / frames),
         (unsigned long long)(core_perf.overlay_uploads / frames));
      nova64_log_line(RETRO_LOG_INFO, message);

      /* Publish averages for the FPS overlay (microseconds → milliseconds). */
      g_fps_avg_cart_ms          = (float)(core_perf.cart_total_us           / frames) / 1000.0f;
      g_fps_avg_render_ms        = (float)(core_perf.render_total_us         / frames) / 1000.0f;
      g_fps_avg_frame_ms         = (float)(core_perf.frame_total_us          / frames) / 1000.0f;
      g_fps_avg_post_ms          = (float)(core_perf.post_total_us           / frames) / 1000.0f;
      g_fps_avg_overlay_total_ms =
         (float)((core_perf.overlay_convert_total_us
                + core_perf.overlay_upload_total_us
                + core_perf.overlay_draw_total_us) / frames) / 1000.0f;
      g_fps_avg_draw_calls       = (unsigned)(core_perf.draw_calls           / frames);

      memset(&core_perf, 0, sizeof(core_perf));
   }
}

static struct nova64_perf_timer *perf_timer_for_label(const char *label, bool create)
{
   if (!label || !label[0])
      return NULL;
   for (int i = 0; i < NOVA64_MAX_PERF_TIMERS; i++) {
      if (perf_timers[i].used && !strcmp(perf_timers[i].label, label))
         return &perf_timers[i];
   }
   if (!create)
      return NULL;
   for (int i = 0; i < NOVA64_MAX_PERF_TIMERS; i++) {
      if (!perf_timers[i].used) {
         perf_timers[i].used = true;
         snprintf(perf_timers[i].label, sizeof(perf_timers[i].label), "%s", label);
         return &perf_timers[i];
      }
   }
   return NULL;
}

static JSValue js_perf_begin(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   const char *label = argc > 0 ? JS_ToCString(ctx, argv[0]) : NULL;
   struct nova64_perf_timer *timer = perf_timer_for_label(label, true);
   if (label)
      JS_FreeCString(ctx, label);
   if (!timer)
      return JS_NewBool(ctx, false);
   timer->active = true;
   timer->started_at = clock();
   return JS_NewBool(ctx, true);
}

static JSValue js_perf_end(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   const char *label = argc > 0 ? JS_ToCString(ctx, argv[0]) : NULL;
   struct nova64_perf_timer *timer = perf_timer_for_label(label, false);
   if (label)
      JS_FreeCString(ctx, label);
   if (!timer || !timer->active)
      return JS_NewFloat64(ctx, 0.0);
   clock_t ended_at = clock();
   double elapsed = (double)(ended_at - timer->started_at) / (double)CLOCKS_PER_SEC;
   if (elapsed < 0.0)
      elapsed = 0.0;
   timer->active = false;
   timer->total += elapsed;
   timer->count++;
   return JS_NewFloat64(ctx, elapsed);
}

static JSValue js_perf_report(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val; (void)argc; (void)argv;
   JSValue report = JS_NewObject(ctx);
   for (int i = 0; i < NOVA64_MAX_PERF_TIMERS; i++) {
      if (!perf_timers[i].used)
         continue;
      JSValue entry = JS_NewObject(ctx);
      JS_SetPropertyStr(ctx, entry, "total", JS_NewFloat64(ctx, perf_timers[i].total));
      JS_SetPropertyStr(ctx, entry, "count", JS_NewUint32(ctx, perf_timers[i].count));
      JS_SetPropertyStr(ctx, entry, "active", JS_NewBool(ctx, perf_timers[i].active));
      JS_SetPropertyStr(ctx, report, perf_timers[i].label, entry);
   }
   return report;
}

static JSValue js_perf_clear(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)ctx; (void)this_val; (void)argc; (void)argv;
   memset(perf_timers, 0, sizeof(perf_timers));
   return JS_UNDEFINED;
}

static void log_perf_report_if_requested(void)
{
   const char *enabled = getenv("NOVA64_PERF");
   if (!enabled || !enabled[0] || !strcmp(enabled, "0"))
      return;
   if (!log_cb)
      return;
   for (int i = 0; i < NOVA64_MAX_PERF_TIMERS; i++) {
      if (perf_timers[i].used) {
         log_cb(RETRO_LOG_INFO, "[nova64] perf %s total=%.6f count=%u active=%d\n",
               perf_timers[i].label, perf_timers[i].total, perf_timers[i].count,
               perf_timers[i].active ? 1 : 0);
      }
   }
}

static int button_index_from_js(JSContext *ctx, JSValueConst value)
{
   if (JS_IsNumber(value)) {
      int index = int_from_js(ctx, value, -1);
      /* Allow the extended range; js_btn / js_btnp route indices 8+
         through ext_buttons[] which is populated from extra keyboard /
         joypad sources. Browser ports use 8-13 (web KEYMAP); RA-only
         bridges live above that. */
      return index >= 0 && index < NOVA64_EXT_BUTTON_COUNT ? index : -1;
   }

   const char *name = JS_ToCString(ctx, value);
   if (!name)
      return -1;

   int index = -1;
   if (!strcmp(name, "left"))
      index = NOVA64_BTN_LEFT;
   else if (!strcmp(name, "right"))
      index = NOVA64_BTN_RIGHT;
   else if (!strcmp(name, "up"))
      index = NOVA64_BTN_UP;
   else if (!strcmp(name, "down"))
      index = NOVA64_BTN_DOWN;
   else if (!strcmp(name, "z") || !strcmp(name, "b"))
      index = NOVA64_BTN_Z;
   else if (!strcmp(name, "x") || !strcmp(name, "a"))
      index = NOVA64_BTN_X;
   else if (!strcmp(name, "c") || !strcmp(name, "y"))
      index = NOVA64_BTN_C;
   else if (!strcmp(name, "v"))
      index = NOVA64_BTN_V;
   JS_FreeCString(ctx, name);
   return index;
}

static JSValue js_btn(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   int index = argc > 0 ? button_index_from_js(ctx, argv[0]) : -1;
   int port  = argc > 1 ? int_from_js(ctx, argv[1], 0) : 0;
   if (port <= 0 || port >= NOVA64_MAX_PORTS) {
      if (index < 0) return JS_NewBool(ctx, false);
      /* Indices 0-7 use buttons[] (existing behaviour); 8+ route
         through ext_buttons[] (web-compat extended layer + RA bridges). */
      bool held = index < NOVA64_BUTTON_COUNT ? buttons[index] : ext_buttons[index];
      return JS_NewBool(ctx, held);
   }
   /* Multi-port joypad: only the 8-button native layout is tracked
      per port, so out-of-range indices return false. */
   return JS_NewBool(ctx, (index >= 0 && index < NOVA64_BUTTON_COUNT) ? mp_buttons[port][index] : false);
}

static JSValue js_btnp(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   int index = argc > 0 ? button_index_from_js(ctx, argv[0]) : -1;
   int port  = argc > 1 ? int_from_js(ctx, argv[1], 0) : 0;
   if (port <= 0 || port >= NOVA64_MAX_PORTS) {
      if (index < 0) return JS_NewBool(ctx, false);
      bool edge = index < NOVA64_BUTTON_COUNT ? pressed_buttons[index] : ext_pressed_buttons[index];
      return JS_NewBool(ctx, edge);
   }
   return JS_NewBool(ctx, (index >= 0 && index < NOVA64_BUTTON_COUNT) ? mp_pressed_buttons[port][index] : false);
}

static int key_code_from_js(JSContext *ctx, JSValueConst value)
{
   if (JS_IsNumber(value)) {
      int code = int_from_js(ctx, value, -1);
      return (code >= 0 && code < NOVA64_KEY_TABLE_SIZE) ? code : -1;
   }
   const char *name = JS_ToCString(ctx, value);
   if (!name)
      return -1;
   char key[64];
   size_t key_len = strlen(name);
   size_t copy_len = key_len < sizeof(key) - 1 ? key_len : sizeof(key) - 1;
   for (size_t i = 0; i < copy_len; i++)
      key[i] = (char)tolower((unsigned char)name[i]);
   key[copy_len] = '\0';
   int code = -1;
   if (!strcmp(key, "up") || !strcmp(key, "arrowup"))
                                     code = NOVA64_RETROK_UP;
   else if (!strcmp(key, "down") || !strcmp(key, "arrowdown"))
                                     code = NOVA64_RETROK_DOWN;
   else if (!strcmp(key, "left") || !strcmp(key, "arrowleft"))
                                     code = NOVA64_RETROK_LEFT;
   else if (!strcmp(key, "right") || !strcmp(key, "arrowright"))
                                     code = NOVA64_RETROK_RIGHT;
   else if (!strcmp(key, "space") || !strcmp(key, " "))
                                     code = NOVA64_RETROK_SPACE;
   else if (!strcmp(key, "enter") || !strcmp(key, "return"))
                                     code = NOVA64_RETROK_RETURN;
   else if (!strcmp(key, "escape") || !strcmp(key, "esc"))
                                     code = NOVA64_RETROK_ESCAPE;
   else if (!strcmp(key, "backspace")) code = NOVA64_RETROK_BACKSPACE;
   else if (!strcmp(key, "tab"))    code = NOVA64_RETROK_TAB;
   else if (!strcmp(key, "shift") || !strcmp(key, "lshift"))
                                     code = NOVA64_RETROK_LSHIFT;
   else if (!strcmp(key, "rshift")) code = NOVA64_RETROK_RSHIFT;
   else if (!strcmp(key, "ctrl") || !strcmp(key, "control") ||
            !strcmp(key, "lctrl") || !strcmp(key, "lcontrol"))
                                     code = NOVA64_RETROK_LCTRL;
   else if (!strcmp(key, "rctrl") || !strcmp(key, "rcontrol"))
                                     code = NOVA64_RETROK_RCTRL;
   else if (!strcmp(key, "alt") || !strcmp(key, "lalt"))
                                     code = NOVA64_RETROK_LALT;
   else if (!strcmp(key, "ralt"))   code = NOVA64_RETROK_RALT;
   else if (key[0] >= 'a' && key[0] <= 'z' && key[1] == '\0')
      code = (int)key[0]; /* a-z maps to RETROK 97-122 */
   else if (key[0] >= '0' && key[0] <= '9' && key[1] == '\0')
      code = (int)key[0]; /* 0-9 maps to RETROK 48-57 */
   /* Web DOM event.code form: "KeyA".."KeyZ" -> single letter.
    * Wizardry-3d uses `keyp('KeyA')` to toggle auto-combat, `keyp('KeyW')`
    * for forward, etc.; without this branch every Key* check returns -1
    * and the cart's keyboard hotkeys silently no-op on RA. */
   else if (key_len == 4 && key[0] == 'k' && key[1] == 'e' && key[2] == 'y' &&
            key[3] >= 'a' && key[3] <= 'z')
      code = (int)key[3];
   /* Web DOM event.code form: "Digit0".."Digit9" -> single digit. */
   else if (key_len == 6 && key[0] == 'd' && key[1] == 'i' && key[2] == 'g' &&
            key[3] == 'i' && key[4] == 't' && key[5] >= '0' && key[5] <= '9')
      code = (int)key[5];
   else if (key[0] == 'f') {
      int fn = (int)strtol(key + 1, NULL, 10);
      if (fn >= 1 && fn <= 12)
         code = NOVA64_RETROK_F1 + (fn - 1);
   }
   JS_FreeCString(ctx, name);
   return code;
}

/* Map a keyboard key to one or more joypad button indices so keyboard-only
 * web carts work on RetroArch gamepads. Returns the number of mapped indices.
 * Direction keys map to one native button; "confirm" keys (Space, Enter) map
 * to four face buttons so any platform's "OK" convention fires. */
static int joypad_buttons_for_key(int code, int out[NOVA64_BUTTON_COUNT])
{
   switch (code) {
      case NOVA64_RETROK_LEFT:  out[0] = 0; return 1;  /* LEFT */
      case NOVA64_RETROK_RIGHT: out[0] = 1; return 1;  /* RIGHT */
      case NOVA64_RETROK_UP:    out[0] = 2; return 1;  /* UP */
      case NOVA64_RETROK_DOWN:  out[0] = 3; return 1;  /* DOWN */
      case NOVA64_RETROK_SPACE:
      case NOVA64_RETROK_RETURN:
         out[0] = 4; out[1] = 5; out[2] = 6; out[3] = 7;  /* B, A, Y, X */
         return 4;
      case 'z': out[0] = NOVA64_BTN_Z; return 1; /* Web KeyZ -> virtual Z */
      case 'x': out[0] = NOVA64_BTN_X; return 1; /* Web KeyX -> virtual X */
      case 'c': out[0] = NOVA64_BTN_C; return 1; /* Web KeyC -> virtual C */
      case 'v': out[0] = NOVA64_BTN_V; return 1; /* Web KeyV -> virtual V */
      default: return 0;
   }
}

/* For keys that have an extended-button overlay (web KEYMAP slots 8..13),
 * return the ext_buttons[] index that mirrors the key. Lets controllers
 * trigger cart-side keyp('KeyA') etc. via the extended mapping populated
 * in update_input (SELECT->'a', L->'q', R->'w', START->Enter, etc.). */
static int ext_button_for_key(int code)
{
   switch (code) {
      case 97:  return 8;   /* 'a' / SELECT */
      case 115: return 9;   /* 's' */
      case 113: return 10;  /* 'q' / L */
      case 119: return 11;  /* 'w' / R */
      case NOVA64_RETROK_RETURN: return 12; /* Enter / START */
      case NOVA64_RETROK_SPACE:  return 13; /* Space / SELECT-or-face */
      /* Slot 14 = "menu / back". Routes Escape and Backspace to the START
       * button so any cart using keyp('Escape') for menu exit / cancel
       * also fires on a controller. Deliberately a fresh slot (not 12)
       * so confirm-intent (Enter) and menu-intent (Esc) stay separable. */
      case NOVA64_RETROK_ESCAPE:    return 14;
      case NOVA64_RETROK_BACKSPACE: return 14;
      /* Slot 15 = inventory/select. Keeps KeyI/Tab separate from slot 8
       * so keyboard A does not accidentally open inventory. */
      case 'i': return 15;
      case NOVA64_RETROK_TAB: return 15;
      default: return -1;
   }
}

static bool key_held_or_joypad(int code)
{
   if (code < 0 || code >= NOVA64_KEY_TABLE_SIZE) return false;
   if (key_held[code]) return true;
   int idx[NOVA64_BUTTON_COUNT];
   int n = joypad_buttons_for_key(code, idx);
   for (int i = 0; i < n; i++)
      if (buttons[idx[i]]) return true;
   int ext = ext_button_for_key(code);
   if (ext >= 0 && ext_buttons[ext]) return true;
   return false;
}

static bool key_pressed_or_joypad(int code)
{
   if (code < 0 || code >= NOVA64_KEY_TABLE_SIZE) return false;
   if (key_held[code] && !key_prev_held[code]) return true;
   int idx[NOVA64_BUTTON_COUNT];
   int n = joypad_buttons_for_key(code, idx);
   for (int i = 0; i < n; i++)
      if (pressed_buttons[idx[i]]) return true;
   int ext = ext_button_for_key(code);
   if (ext >= 0 && ext_pressed_buttons[ext]) return true;
   return false;
}

static JSValue js_key(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int code = argc > 0 ? key_code_from_js(ctx, argv[0]) : -1;
   return JS_NewBool(ctx, key_held_or_joypad(code));
}

static JSValue js_keyp(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int code = argc > 0 ? key_code_from_js(ctx, argv[0]) : -1;
   return JS_NewBool(ctx, key_pressed_or_joypad(code));
}

static int mouse_btn_index(JSContext *ctx, JSValueConst value)
{
   if (JS_IsNumber(value)) {
      int i = int_from_js(ctx, value, -1);
      return (i >= 0 && i < NOVA64_MOUSE_BTN_COUNT) ? i : -1;
   }
   const char *name = JS_ToCString(ctx, value);
   if (!name) return -1;
   int idx = -1;
   if (!strcmp(name, "left"))        idx = 0;
   else if (!strcmp(name, "right"))  idx = 1;
   else if (!strcmp(name, "middle")) idx = 2;
   JS_FreeCString(ctx, name);
   return idx;
}

static JSValue js_mouse_x(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val; (void)argc; (void)argv;
   return JS_NewInt32(ctx, mouse_rel_x);
}

static JSValue js_mouse_y(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val; (void)argc; (void)argv;
   return JS_NewInt32(ctx, mouse_rel_y);
}

static JSValue js_mouse_btn(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int idx = argc > 0 ? mouse_btn_index(ctx, argv[0]) : -1;
   if (idx < 0) return JS_NewBool(ctx, false);
   return JS_NewBool(ctx, mouse_btns[idx]);
}

static JSValue js_mouse_btnp(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int idx = argc > 0 ? mouse_btn_index(ctx, argv[0]) : -1;
   if (idx < 0) return JS_NewBool(ctx, false);
   return JS_NewBool(ctx, mouse_btns[idx] && !mouse_prev_btns[idx]);
}

static JSValue js_touch_x(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val; (void)argc; (void)argv;
   return JS_NewInt32(ctx, touch_count > 0 ? touch_x : 0);
}

static JSValue js_touch_y(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val; (void)argc; (void)argv;
   return JS_NewInt32(ctx, touch_count > 0 ? touch_y : 0);
}

static JSValue js_touch_count(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val; (void)argc; (void)argv;
   return JS_NewInt32(ctx, touch_count);
}

/* Parse a trailing { material, emissive, emissiveIntensity, roughness,
 * metalness, flatShading } options object from createCube / createSphere /
 * etc. Web carts pass this as the last arg to set material properties at
 * construction time. Without parsing, torches in wizardry-3d come back as
 * solid colored cubes instead of glowing emissive bulbs. */
static void apply_mesh_options(JSContext *ctx, struct nova64_mesh *mesh, JSValueConst opts)
{
   if (!mesh || !JS_IsObject(opts) || JS_IsArray(opts)) return;
   JSValue v;

   v = JS_GetPropertyStr(ctx, opts, "emissive");
   if (!JS_IsUndefined(v) && !JS_IsNull(v)) {
      mesh->emissive_color = color_from_js(ctx, v, mesh->emissive_color);
      if (mesh->emissive_intensity <= 0.0f) mesh->emissive_intensity = 1.0f;
   }
   JS_FreeValue(ctx, v);

   v = JS_GetPropertyStr(ctx, opts, "emissiveColor");
   if (!JS_IsUndefined(v) && !JS_IsNull(v))
      mesh->emissive_color = color_from_js(ctx, v, mesh->emissive_color);
   JS_FreeValue(ctx, v);

   v = JS_GetPropertyStr(ctx, opts, "emissiveIntensity");
   if (JS_IsNumber(v))
      mesh->emissive_intensity = (float)clamp_double(double_from_js(ctx, v, mesh->emissive_intensity), 0.0, 4.0);
   JS_FreeValue(ctx, v);

   /* Web carts also pass plain `intensity:` alongside `material:'emissive'`
    * (wizardry-3d torches, portals). Accept it as emissive intensity when
    * the material is emissive or when no explicit emissiveIntensity was set. */
   v = JS_GetPropertyStr(ctx, opts, "intensity");
   if (JS_IsNumber(v))
      mesh->emissive_intensity = (float)clamp_double(double_from_js(ctx, v, mesh->emissive_intensity), 0.0, 4.0);
   JS_FreeValue(ctx, v);

   v = JS_GetPropertyStr(ctx, opts, "material");
   if (JS_IsString(v)) {
      const char *m = JS_ToCString(ctx, v);
      if (m) {
         if (!strcmp(m, "emissive") && mesh->emissive_intensity <= 0.0f)
            mesh->emissive_intensity = 1.0f;
         JS_FreeCString(ctx, m);
      }
   }
   JS_FreeValue(ctx, v);

   v = JS_GetPropertyStr(ctx, opts, "roughness");
   if (JS_IsNumber(v))
      mesh->roughness = (float)clamp_double(double_from_js(ctx, v, mesh->roughness), 0.0, 1.0);
   JS_FreeValue(ctx, v);

   v = JS_GetPropertyStr(ctx, opts, "metalness");
   if (JS_IsNumber(v))
      mesh->metalness = (float)clamp_double(double_from_js(ctx, v, mesh->metalness), 0.0, 1.0);
   JS_FreeValue(ctx, v);

   v = JS_GetPropertyStr(ctx, opts, "flatShading");
   if (JS_IsBool(v))
      mesh->flat_shading = JS_ToBool(ctx, v);
   JS_FreeValue(ctx, v);

   v = JS_GetPropertyStr(ctx, opts, "opacity");
   if (JS_IsNumber(v))
      mesh->opacity = (float)clamp_double(double_from_js(ctx, v, mesh->opacity), 0.0, 1.0);
   JS_FreeValue(ctx, v);

   v = JS_GetPropertyStr(ctx, opts, "transparent");
   if (JS_IsBool(v))
      mesh->transparent = JS_ToBool(ctx, v);
   JS_FreeValue(ctx, v);
}

/* Find the trailing options object among argv (if any) and apply it to mesh.
 * Web-cart pattern: createCube(size, color, [x,y,z], {emissive: 0xff8833}). */
static void apply_trailing_options(JSContext *ctx, struct nova64_mesh *mesh, int argc, JSValueConst *argv)
{
   for (int i = argc - 1; i >= 0; i--) {
      if (JS_IsObject(argv[i]) && !JS_IsArray(argv[i]) && !JS_IsFunction(ctx, argv[i])) {
         apply_mesh_options(ctx, mesh, argv[i]);
         return;
      }
   }
}

static JSValue js_create_cube(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int handle = allocate_mesh(NOVA64_MESH_CUBE);
   if (!handle)
      return JS_ThrowInternalError(ctx, "Nova64 mesh table is full");

   struct nova64_mesh *mesh = mesh_from_handle(handle);
   if (!mesh)
      return JS_NewInt32(ctx, handle);

   if (argc >= 4 && JS_IsNumber(argv[0]) && JS_IsNumber(argv[1]) &&
         JS_IsNumber(argv[2]) && JS_IsNumber(argv[3])) {
      mesh->scale[0] = (float)clamp_double(fabs(double_from_js(ctx, argv[0], 1.0)), 0.001, 10000.0);
      mesh->scale[1] = (float)clamp_double(fabs(double_from_js(ctx, argv[1], 1.0)), 0.001, 10000.0);
      mesh->scale[2] = (float)clamp_double(fabs(double_from_js(ctx, argv[2], 1.0)), 0.001, 10000.0);
      mesh->color = color_from_js(ctx, argv[3], mesh->color);
      if (argc > 4)
         set_position_from_js(ctx, argv[4], mesh->position);
   } else if (argc >= 2 && JS_IsNumber(argv[0]) && !JS_IsArray(argv[1])) {
      double size = clamp_double(fabs(double_from_js(ctx, argv[0], 1.0)), 0.001, 10000.0);
      mesh->scale[0] = (float)size;
      mesh->scale[1] = (float)size;
      mesh->scale[2] = (float)size;
      mesh->color = color_from_js(ctx, argv[1], mesh->color);
      if (argc > 2)
         set_position_from_js(ctx, argv[2], mesh->position);
   } else if (argc > 0) {
      mesh->color = color_from_js(ctx, argv[0], mesh->color);
      if (argc > 1)
         set_position_from_js(ctx, argv[1], mesh->position);
   }
   apply_trailing_options(ctx, mesh, argc, argv);
   return JS_NewInt32(ctx, handle);
}

static JSValue js_create_sphere(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int handle = allocate_mesh(NOVA64_MESH_SPHERE);
   if (!handle)
      return JS_ThrowInternalError(ctx, "Nova64 mesh table is full");

   struct nova64_mesh *mesh = mesh_from_handle(handle);
   if (!mesh)
      return JS_NewInt32(ctx, handle);

   if (argc >= 2 && JS_IsNumber(argv[0]) && !JS_IsArray(argv[1])) {
      double radius = clamp_double(fabs(double_from_js(ctx, argv[0], 1.0)), 0.001, 10000.0);
      mesh->scale[0] = (float)(radius * 2.0);
      mesh->scale[1] = (float)(radius * 2.0);
      mesh->scale[2] = (float)(radius * 2.0);
      mesh->color = color_from_js(ctx, argv[1], mesh->color);
      if (argc > 2)
         set_position_from_js(ctx, argv[2], mesh->position);
   } else if (argc > 0) {
      mesh->color = color_from_js(ctx, argv[0], mesh->color);
      if (argc > 1)
         set_position_from_js(ctx, argv[1], mesh->position);
   }
   apply_trailing_options(ctx, mesh, argc, argv);
   return JS_NewInt32(ctx, handle);
}

static JSValue js_create_plane(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   int handle = allocate_mesh(NOVA64_MESH_PLANE);
   if (!handle)
      return JS_ThrowInternalError(ctx, "Nova64 mesh table is full");

   struct nova64_mesh *mesh = mesh_from_handle(handle);
   if (!mesh)
      return JS_NewInt32(ctx, handle);

   if (argc >= 2 && JS_IsNumber(argv[0]) && JS_IsNumber(argv[1])) {
      double width = double_from_js(ctx, argv[0], 1.0);
      double height = double_from_js(ctx, argv[1], 1.0);
      mesh->scale[0] = (float)clamp_double(fabs(width), 0.001, 10000.0);
      mesh->scale[1] = (float)clamp_double(fabs(height), 0.001, 10000.0);
      mesh->scale[2] = 1.0f;
      if (argc > 2)
         mesh->color = color_from_js(ctx, argv[2], mesh->color);
      if (argc > 3)
         set_position_from_js(ctx, argv[3], mesh->position);
   } else if (argc > 0) {
      mesh->color = color_from_js(ctx, argv[0], mesh->color);
   }
   apply_trailing_options(ctx, mesh, argc, argv);
   return JS_NewInt32(ctx, handle);
}

/* createCapsule(radius, height, color [, position]) */
static JSValue js_create_capsule(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int handle = allocate_mesh(NOVA64_MESH_CAPSULE);
   if (!handle)
      return JS_ThrowInternalError(ctx, "Nova64 mesh table is full");
   struct nova64_mesh *mesh = mesh_from_handle(handle);
   if (!mesh)
      return JS_NewInt32(ctx, handle);

   if (argc >= 3 && JS_IsNumber(argv[0]) && JS_IsNumber(argv[1])) {
      double radius = clamp_double(fabs(double_from_js(ctx, argv[0], 0.5)), 0.001, 10000.0);
      double height = clamp_double(fabs(double_from_js(ctx, argv[1], 1.0)), 0.001, 10000.0);
      /* scale[0]=scale[2]=diameter, scale[1]=total height */
      mesh->scale[0] = (float)(radius * 2.0);
      mesh->scale[1] = (float)height;
      mesh->scale[2] = (float)(radius * 2.0);
      mesh->color = color_from_js(ctx, argv[2], mesh->color);
      if (argc > 3)
         set_position_from_js(ctx, argv[3], mesh->position);
   } else if (argc > 0) {
      mesh->color = color_from_js(ctx, argv[0], mesh->color);
   }
   apply_trailing_options(ctx, mesh, argc, argv);
   return JS_NewInt32(ctx, handle);
}

/* createCylinder(radiusTop, radiusBottom, height, color [, position]) */
static JSValue js_create_cylinder(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   (void)this_val;
   int handle = allocate_mesh(NOVA64_MESH_CYLINDER);
   if (!handle)
      return JS_ThrowInternalError(ctx, "Nova64 mesh table is full");
   struct nova64_mesh *mesh = mesh_from_handle(handle);
   if (!mesh)
      return JS_NewInt32(ctx, handle);

   if (argc >= 4 && JS_IsNumber(argv[0]) && JS_IsNumber(argv[1]) && JS_IsNumber(argv[2])) {
      double rTop    = clamp_double(fabs(double_from_js(ctx, argv[0], 0.5)), 0.001, 10000.0);
      double rBottom = clamp_double(fabs(double_from_js(ctx, argv[1], 0.5)), 0.001, 10000.0);
      double height  = clamp_double(fabs(double_from_js(ctx, argv[2], 1.0)), 0.001, 10000.0);
      /* scale[0]=2*rTop, scale[2]=2*rBottom, scale[1]=height */
      mesh->scale[0] = (float)(rTop    * 2.0);
      mesh->scale[1] = (float)height;
      mesh->scale[2] = (float)(rBottom * 2.0);
      mesh->color = color_from_js(ctx, argv[3], mesh->color);
      if (argc > 4)
         set_position_from_js(ctx, argv[4], mesh->position);
   } else if (argc > 0) {
      mesh->color = color_from_js(ctx, argv[0], mesh->color);
   }
   apply_trailing_options(ctx, mesh, argc, argv);
   return JS_NewInt32(ctx, handle);
}

static JSValue js_vec3_array(JSContext *ctx, const float value[3])
{
   JSValue array = JS_NewArray(ctx);
   JS_SetPropertyUint32(ctx, array, 0, JS_NewFloat64(ctx, value[0]));
   JS_SetPropertyUint32(ctx, array, 1, JS_NewFloat64(ctx, value[1]));
   JS_SetPropertyUint32(ctx, array, 2, JS_NewFloat64(ctx, value[2]));
   return array;
}

static float normalize_positive_transform(double value)
{
   return value > 0.0 ? (float)clamp_double(value, 0.001, 10000.0) : 1.0f;
}

static void set_transform_vec3_from_args(JSContext *ctx, int argc, JSValueConst *argv,
      int start, float target[3], bool positive, bool uniform_single)
{
   if (argc <= start)
      return;

   float next[3] = {target[0], target[1], target[2]};
   if (set_position_from_js(ctx, argv[start], next)) {
      target[0] = positive ? normalize_positive_transform(next[0]) : next[0];
      target[1] = positive ? normalize_positive_transform(next[1]) : next[1];
      target[2] = positive ? normalize_positive_transform(next[2]) : next[2];
      return;
   }

   double fallback = positive ? 1.0 : 0.0;
   double x = double_from_js(ctx, argv[start], fallback);
   double y = argc > start + 1 ? double_from_js(ctx, argv[start + 1], fallback) :
      (uniform_single ? x : fallback);
   double z = argc > start + 2 ? double_from_js(ctx, argv[start + 2], fallback) :
      (uniform_single ? x : fallback);
   target[0] = positive ? normalize_positive_transform(x) : (float)x;
   target[1] = positive ? normalize_positive_transform(y) : (float)y;
   target[2] = positive ? normalize_positive_transform(z) : (float)z;
}

static JSValue js_destroy_mesh(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
   int handle = int_from_js(ctx, argc > 0 ? argv[0] : JS_UNDEFINED, 0);
   struct nova64_mesh *mesh = mesh_from_handle(handle);
   if (mesh) {
      free(mesh->custom_verts);
      free(mesh->custom_indices);
      free(mesh->instance_transforms);
      free(mesh->instance_colors);
      free(mesh->instance_visible);
      if (gles.active && gles.DeleteBuffers) {
         if (mesh->gl_custom_vbo) gles.DeleteBuffers(1, &mesh->gl_custom_vbo);
         if (mesh->gl_custom_ibo) gles.DeleteBuffers(1, &mesh->gl_custom_ibo);
      }
      memset(mesh, 0, sizeof(*mesh));
   }
   return JS_UNDEFINED;
}

